INSERT INTO `GovDocNews` (`o_id`,`DocTitle`,`ShortTitle`,`DocHtmlCon`,`DocContent`,`SUBDOCTITLE`,`DOCKEYWORDS`,`DocAbstract`,`DOCSOURCENAME`,`DOCAUTHOR`,`DOCRELTIME`,`DocLink`,`DOCPUBTIME`,`SITEID`,`SITENAME`,`CHANNELID`,`DOCPUBURL`,`DOCSTATUS`) VALUES	 (1647203,'北京信息科技大学2020年招聘公告',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_web trs_key4format"><p style="text-indent: 2em;">北京信息科技大学由原机械部所属的北京机械工业学院和原电子部所属的北京信息工程学院合并组建，是北京市重点支持建设的普通高等学校，在长达80余年的办学历史中，形成了鲜明的信息特色、行业特色、军工特色。学校的5个校区坐落于海淀区和朝阳区，占地1183亩的昌平新校区将于2020年基本建成。</p><p style="text-indent: 2em;">学校已形成以工为主，工、管、理、经、文、法6个学科门类协调发展的学科格局，拥有北京市重点学科和重点建设学科12个。现有一级学科硕士点14个，4个专业硕士学位授权种类、8个工程硕士授权领域，成功入选2018-2020年博士学位授予立项建设单位。拥有教育部重点实验室、北京实验室、北京市重点实验室、北京市国际科技合作基地、北京市哲学社会科学研究基地和北京市高校工程中心等国家级、省部级科研机构21个， “先进光电子器件与系统学科创新引智基地”入选国家“111计划”。现有全日制本科生10916人、研究生1430人、留学生159人。2018年学校高端信息产业技术研究院获批设立博士后科研工作站。</p><p style="text-indent: 2em;">当前，学校正以“双一流”建设为导向，继续推进特色发展、质量发展、内涵发展、差异化发展，朝着建设信息特色鲜明的高水平大学大步迈进。</p><p style="text-indent: 2em;">现根据学校工作需要，面向社会公开招聘编制内工作人员。所需岗位及要求见附件1。详情请关注学校主页的招聘公告。</p><p style="text-indent: 2em;">学校网址：http://www.bistu.edu.cn/</p><p style="text-indent: 2em;">一、应聘的基本条件</p><p style="text-indent: 2em;">1、遵守宪法和法律，具有良好的品行，身心健康；</p><p style="text-indent: 2em;">2、满足申报岗位的相关要求；</p><p style="text-indent: 2em;">3、满足北京市相关政策要求；</p><p style="text-indent: 2em;">4、博士毕业生，年龄一般在35周岁以内；硕士毕业生，年龄一般在30周岁以内；</p><p style="text-indent: 2em;">5、符合事业单位公开招聘人员回避制度的要求。</p><p style="text-indent: 2em;">二、应聘人员的待遇</p><p style="text-indent: 2em;">按国家、北京市及校内有关文件执行。</p><p style="text-indent: 2em;">三、申报时间及方式：</p><p style="text-indent: 2em;">1、报名截止时间：2020年4月1日。</p><p style="text-indent: 2em;">2、应聘其他专技岗、学生工作岗、新疆籍少数民族学生专职辅导员岗及行政管理岗（序号16至20）的人员须填写应聘申请表（见附件2），并将应聘申请表以附件的形式发往邮箱bistu2020@163.com，邮件主题以及应聘申请表的命名格式为：“应聘岗位名称--姓名--性别--出生日期”，邮件附件也可再附个人详细简历；其余岗位应聘人员则直接将个人详细简历发送至对应单位联系人的电子邮箱即可。</p><p style="text-indent: 2em;">四、招聘程序：</p><p style="text-indent: 2em;">1、申报。见第三条规定；</p><p style="text-indent: 2em;">2、简历筛选。由学校根据用人需求、应聘者学历学位层次、专业方向、工作经历进行筛选；</p><p style="text-indent: 2em;">3、笔试。由学校根据用人需求，对应聘者的专业知识与能力或管理能力进行测试；</p><p style="text-indent: 2em;">4、面试。由学校根据用人需求，按照应聘人数与岗位数不超过3:1的比例进入面试，不足3:1的，按实际应聘人数确定，对应聘者采取试讲或结构化面试。笔试成绩与面试成绩所占比重为3:7；</p><p style="text-indent: 2em;">5、体检。由学校统一组织体检；</p><p style="text-indent: 2em;">6、考察。各设岗二级机构开展实践考察；</p><p style="text-indent: 2em;">7、确定拟聘人选。根据考察情况，确定拟聘人选；</p><p style="text-indent: 2em;">8、公示。由学校分期在校园网主页上公示7个工作日。</p><p style="text-indent: 2em;">&nbsp;</p><p style="text-align: right; text-indent: 2em;">北京信息科技大学</p><p style="text-align: right; text-indent: 2em;">2020年2月17日</p><p style="text-align: left;"><br/></p><p style="text-indent: 2em;">附件1：北京信息科技大学2020年招聘岗位信息汇总表</p><p style="text-indent: 2em;">附件2：北京信息科技大学2020年其他专技、行政管理、学生工作岗位应聘申请表</p></div>','北京信息科技大学由原机械部所属的北京机械工业学院和原电子部所属的北京信息工程学院合并组建，是北京市重点支持建设的普通高等学校，在长达80余年的办学历史中，形成了鲜明的信息特色、行业特色、军工特色。学校的5个校区坐落于海淀区和朝阳区，占地1183亩的昌平新校区将于2020年基本建成。学校已形成以工为主，工、管、理、经、文、法6个学科门类协调发展的学科格局，拥有北京市重点学科和重点建设学科12个。现有一级学科硕士点14个，4个专业硕士学位授权种类、8个工程硕士授权领域，成功入选2018-2020年博士学位授予立项建设单位。拥有教育部重点实验室、北京实验室、北京市重点实验室、北京市国际科技合作基地、北京市哲学社会科学研究基地和北京市高校工程中心等国家级、省部级科研机构21个， “先进光电子器件与系统学科创新引智基地”入选国家“111计划”。现有全日制本科生10916人、研究生1430人、留学生159人。2018年学校高端信息产业技术研究院获批设立博士后科研工作站。当前，学校正以“双一流”建设为导向，继续推进特色发展、质量发展、内涵发展、差异化发展，朝着建设信息特色鲜明的高水平大学大步迈进。现根据学校工作需要，面向社会公开招聘编制内工作人员。所需岗位及要求见附件1。详情请关注学校主页的招聘公告。学校网址：http://www.bistu.edu.cn/一、应聘的基本条件1、遵守宪法和法律，具有良好的品行，身心健康；2、满足申报岗位的相关要求；3、满足北京市相关政策要求；4、博士毕业生，年龄一般在35周岁以内；硕士毕业生，年龄一般在30周岁以内；5、符合事业单位公开招聘人员回避制度的要求。二、应聘人员的待遇按国家、北京市及校内有关文件执行。三、申报时间及方式：1、报名截止时间：2020年4月1日。2、应聘其他专技岗、学生工作岗、新疆籍少数民族学生专职辅导员岗及行政管理岗（序号16至20）的人员须填写应聘申请表（见附件2），并将应聘申请表以附件的形式发往邮箱bistu2020@163.com，邮件主题以及应聘申请表的命名格式为：“应聘岗位名称--姓名--性别--出生日期”，邮件附件也可再附个人详细简历；其余岗位应聘人员则直接将个人详细简历发送至对应单位联系人的电子邮箱即可。四、招聘程序：1、申报。见第三条规定；2、简历筛选。由学校根据用人需求、应聘者学历学位层次、专业方向、工作经历进行筛选；3、笔试。由学校根据用人需求，对应聘者的专业知识与能力或管理能力进行测试；4、面试。由学校根据用人需求，按照应聘人数与岗位数不超过3:1的比例进入面试，不足3:1的，按实际应聘人数确定，对应聘者采取试讲或结构化面试。笔试成绩与面试成绩所占比重为3:7；5、体检。由学校统一组织体检；6、考察。各设岗二级机构开展实践考察；7、确定拟聘人选。根据考察情况，确定拟聘人选；8、公示。由学校分期在校园网主页上公示7个工作日。 北京信息科技大学2020年2月17日附件1：北京信息科技大学2020年招聘岗位信息汇总表附件2：北京信息科技大学2020年其他专技、行政管理、学生工作岗位应聘申请表',NULL,'事业单位;公开招聘',NULL,'北京信息科技大学',NULL,'2020-02-17 17:38:00',NULL,'2022-03-21 22:51:51',6,'北京市人力资源和社会保障局',39157,'http://rsj.beijing.gov.cn/weimenhu/wgsgg/202002/t20200217_1647203.html',10),	 (870295,'关于北京市人力资源和社会保障局及所属单位2016年公开遴选成绩公示公告','关于北京市人力资源和社会保障局及所属单位2016年公开遴选成绩公示公告','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><p style="margin: 0cm 0cm 0pt; text-align: justify; text-indent: 32pt; -ms-text-justify: inter-ideograph; mso-char-indent-count: 2.0;"><span style="font-family: 仿宋_GB2312; font-size: 16pt;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;">&nbsp;&nbsp; 按照《北京市<span style="line-height: 100%; font-size: 16pt;">2016</span>年市级机关公开遴选公务员工作实施方案》的要求，我局公开遴选公务员的笔试、面试、综合评价已结束。现将综合成绩予以公示。公示期间，如有异议，请向北京市人力资源和社会保障局人事处反映。 <span style="line-height: 100%; font-size: 16pt;"></span></span></span></span></span></p><p style="margin: 0cm 0cm 0pt; text-align: justify; text-indent: 32pt; -ms-text-justify: inter-ideograph; mso-char-indent-count: 2.0;"><span style="font-family: 仿宋_GB2312; font-size: 16pt;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;">&nbsp;&nbsp; 联系电话：<span style="line-height: 100%; font-size: 16pt;">63161290</span></span></span></span></span></p><p style="margin: 0cm 0cm 0pt; text-align: justify; text-indent: 32pt; -ms-text-justify: inter-ideograph; mso-char-indent-count: 2.0;"><span style="font-family: 仿宋_GB2312; font-size: 16pt;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;">&nbsp;&nbsp; 公示时间：<span style="line-height: 100%; font-size: 16pt;">2016</span>年<span style="line-height: 100%; font-size: 16pt;">7</span>月<span style="line-height: 100%; font-size: 16pt;">1</span>日至<span style="line-height: 100%; font-size: 16pt;">7</span>月<span style="line-height: 100%; font-size: 16pt;">5</span>日<span style="line-height: 100%; font-size: 16pt;"></span></span></span></span></span></p><p style="margin: 0cm 0cm 0pt; text-align: justify; text-indent: 32pt; -ms-text-justify: inter-ideograph; mso-char-indent-count: 2.0;"><span style="font-family: 仿宋_GB2312; font-size: 16pt;"></span></p><p style="margin: 0cm 0cm 0pt; text-align: justify; text-indent: 32pt; -ms-text-justify: inter-ideograph; mso-char-indent-count: 2.0;"><span style="font-family: 仿宋_GB2312; font-size: 16pt;"></span></p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 172.5pt; mso-char-indent-count: 11.5;"><span style="font-family: 仿宋_GB2312; font-size: 15pt; mso-hansi-font-family: 宋体;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 北京市人力资源和社会保障局人事处<span style="line-height: 100%; font-size: 16pt;"></span></span></span></span></span></p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;"><span style="line-height: 100%; font-family: 仿宋_GB2312; font-size: 16pt; mso-hansi-font-family: 宋体;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2016</span><span style="line-height: 100%; font-family: 仿宋_GB2312; font-size: 16pt; mso-hansi-font-family: 宋体;">年<span style="line-height: 100%; font-size: 16pt;">7</span>月<span style="line-height: 100%; font-size: 16pt;">1</span>日</span></span></span></span></p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;">&nbsp;</p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;">&nbsp;</p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;">&nbsp;</p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;"><span style="line-height: 100%; font-family: 仿宋_GB2312; font-size: 16pt; mso-hansi-font-family: 宋体;"><span style="font-family: Calibri;"><strong><span style="font-family: 仿宋_GB2312; font-size: 18pt; mso-bidi-font-family: 仿宋_GB2312; mso-ansi-language: ZH-CN;">北京市人力资源和社会保障局及所属单位</span></strong></span><span style="font-family: Calibri;"><strong><span style="font-family: 仿宋_GB2312; font-size: 18pt; mso-hansi-font-family: &quot;Times New Roman&quot;; mso-bidi-font-family: 仿宋_GB2312; mso-ansi-language: ZH-CN;">2016年公开遴选综合成绩</span></strong></span></span></span></span></span></p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;">&nbsp;</p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;"><span style="font-family: 仿宋;"><span style="font-size: 16pt;"><span style="line-height: 100%;"><span style="line-height: 100%; font-family: 仿宋_GB2312; font-size: 16pt; mso-hansi-font-family: 宋体;"><span style="font-family: Calibri;"><strong><span style="font-family: &quot;Times New Roman&quot;,&quot;serif&quot;; font-size: 18pt; mso-fareast-font-family: 仿宋_GB2312;"></span></strong></span></span></span></span></span></p><p class="MsoNormal" style="margin: 0cm 0cm 0pt; text-indent: 232pt; mso-char-indent-count: 14.5;"><span style="line-height: 100%; font-size: 16pt;"></span><table class="MsoNormalTable" style