INSERT INTO `GovDocNews` (`o_id`,`DocTitle`,`ShortTitle`,`DocHtmlCon`,`DocContent`,`SUBDOCTITLE`,`DOCKEYWORDS`,`DocAbstract`,`DOCSOURCENAME`,`DOCAUTHOR`,`DOCRELTIME`,`DocLink`,`DOCPUBTIME`,`SITEID`,`SITENAME`,`CHANNELID`,`DOCPUBURL`,`DOCSTATUS`) VALUES	 (871003,'北京市人力资源和社会保障局2014年度部门决算信息','北京市人力资源和社会保障局2014年度部门决算信息',NULL,NULL,NULL,'北京市人力资源和社会保障局;2014年度部门决算信息','北京市人力资源和社会保障局2014年度部门决算信息','自发','北京市人力资源和社会保障局','2015-08-20 10:20:00',NULL,'2023-08-27 18:15:34',6,'北京市人力资源和社会保障局',15258,'http://rsj.beijing.gov.cn/xxgk/zfxxgk/yjs/201912/t20191206_871003.html',10),	 (871265,'北京市高级专业技术职务任职资格评审申报表','北京市高级专业技术职务任职资格评审申报表',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 11:15:00',NULL,'2022-11-03 14:22:00',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/P020191206405134987372.doc',10),	 (870304,'2015年下半年北京市劳动保障职业技能实训中心（北京市实验技工学校）招聘补充公告','2015年下半年北京市劳动保障职业技能实训中心（北京市实验技工学校）招聘补充公告','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_key4format trs_web"><div><p>北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。根据学校工作需要及报名情况，对部分岗位的招聘条件进行调整，现将补充公告说明如下：</p><p>一、&nbsp;应聘基本条件</p><p><span style="text-indent: 32px;">见相关文档</span></p><p>二、补充岗位、人数及条件</p><p>教学秘书岗位由原招聘1人增加到4人；</p><p>学生管理岗位由原招聘2人增加到5人；</p><p>财务管理岗位要求调整为，对具有5年以上工作经验者，可适当放宽至40周岁。</p><p>三、报名时间</p><p>报名时间延长至2015年12月14日。</p><p>四、招聘程序</p><p>见相关文档</p><p>五、学校地址</p><p>北校区：昌平区南口路32号（主教学区），邮编：102200 </p><p>南校区：朝阳区惠新东街5号（亚运村以东小营附近），邮编：100029</p><p>学校网站： http://www.bjsyjx.org/</p><p>我们热诚期待您的加入！ </p><p></p><p style="text-align: right">北京市劳动保障职业技能实训中心</p><p style="text-align: right">（北京市实验技工学校）</p><p style="text-align: right">二〇一五年十二月</p></div></div>','北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。根据学校工作需要及报名情况，对部分岗位的招聘条件进行调整，现将补充公告说明如下：一、 应聘基本条件见相关文档二、补充岗位、人数及条件教学秘书岗位由原招聘1人增加到4人；学生管理岗位由原招聘2人增加到5人；财务管理岗位要求调整为，对具有5年以上工作经验者，可适当放宽至40周岁。三、报名时间报名时间延长至2015年12月14日。四、招聘程序见相关文档五、学校地址北校区：昌平区南口路32号（主教学区），邮编：102200 南校区：朝阳区惠新东街5号（亚运村以东小营附近），邮编：100029学校网站： http://www.bjsyjx.org/我们热诚期待您的加入！ 北京市劳动保障职业技能实训中心（北京市实验技工学校）二〇一五年十二月',NULL,NULL,'北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。补充岗位、人数及条件教学秘书岗位由原招聘1人增加到4人.学校地址北校区:昌平区南口路32号(主教学区),邮编：102200南校区：朝阳区惠新东街5号（亚运村以东小营附近），邮编：100029学校网站：http://www.bjsyjx.org/我们热诚期待您的加入！','北京市人力资源和社会保障局','北京市人力资源和社会保障局','2015-12-04 16:34:00',NULL,'2024-03-06 20:57:04',6,'北京市人力资源和社会保障局',15268,'https://rsj.beijing.gov.cn/xxgk/zfxxgk/rsxx/201912/t20191206_870304.html',10),	 (870305,'2015年下半年北京市劳动保障职业技能实训中心（北京市实验技工学校)招聘公告','2015年下半年北京市劳动保障职业技能实训中心（北京市实验技工学校)招聘公告','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。中心（技校）以北京劳动保障职业学院为依托，现已形成技师、高级工、中级工等多层次技能人才的培养格局，中职教育与高职教育无缝衔接。根据工作需要，中心（技校）公开招聘工作人员，现将有关事项公告如下：</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">一、应聘基本条件</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、坚持中国共产党的领导，热爱职业教育事业，遵纪守法、品行端正，责任心强，乐于奉献。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、有较强的语言表达能力、沟通协调能力和良好的文字写作能力。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">3</span><span style="font-size: 10.5pt;">、身心健康，年龄<span style="font-size: 10.5pt;">35</span>周岁以下（<span style="font-size: 10.5pt;">1980</span>年<span style="font-size: 10.5pt;">11</span>月<span style="font-size: 10.5pt;">1</span>日以后出生）。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">4</span><span style="font-size: 10.5pt;">、具有北京市常住户口，且人事行政关系在北京。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">5</span><span style="font-size: 10.5pt;">、具有招聘岗位所要求的学历（学位）及其他资格条件。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">二、招聘岗位及要求</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">岗位需求、学历学位、所需专业、招聘人数等具体要求见附件。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">三、报名时间</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">报名时间：<span style="font-size: 10.5pt;">2015</span>年<span style="font-size: 10.5pt;">12</span>月<span style="font-size: 10.5pt;">3</span>日。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">四、招聘程序</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（一）网上报名：请报考人员将电子简历及《北京市实验技工学校（北京劳动保障职业技能实训中心）公开招聘报名表》（见附件）发送至电子邮箱：<span style="font-size: 10.5pt;">hr@bvclss.cn</span>，应聘格式请注明<span style="font-size: 10.5pt;">:</span>应聘职位<span style="font-size: 10.5pt;">-</span>姓名<span style="font-size: 10.5pt;">-</span>专业<span style="font-size: 10.5pt;">-</span>学校。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（二）资格审查</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、对网上报名材料进行初审，初审合格者通知报送纸质材料。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">报送材料地点：北京市朝阳区惠新东街<span style="font-size: 10.5pt;">5</span>号 人事处（北楼<span style="font-size: 10.5pt;">105</span>室）</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">&nbsp;&nbsp;</span><span style="font-size: 10.5pt;">联系人：李老师<span style="font-size: 10.5pt;">&nbsp;</span>联系电话：<span style="font-size: 10.5pt;">010-80112456</span></span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、根据资格审查情况，确定参加初试人员名单。应聘者须对所提供的信息、资料内容的真实性、准确性负责，如有不实，将取消应聘资格。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（三）考试及考察</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、初选符合岗位资格人员，参加学校组织的笔试，笔试合格人员进入面试；面试合格人员进入实操考核；实操考核安排办公软件及实训设备操作，考察办公自动化水平及专业技能等，成绩均为百分制，合格分数线均为<span style="font-size: 10.5pt;">60</span>分。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名，按照拟招聘岗位<span style="font-size: 10.5pt;">1: 2</span>的比例确定<span style="font-size: 10.5pt;">(</span>不足<span style="font-size: 10.5pt;">1</span>：<span style="font-size: 10.5pt;">2</span>比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占<span style="font-size: 10.5pt;">30%</span>，面试成绩占<span style="font-size: 10.5pt;">40%</span>，实操成绩占<span style="font-size: 10.5pt;">30%</span>。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">3</span><span style="font-size: 10.5pt;">、笔试、面试和实操考核具体时间另行通知。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（四）公示及聘用</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">考察合格的拟聘用人员进行公示，公示期为<span style="font-size: 10.5pt;">7</span>个工作日。经公示无异议者，办理相关聘用手续。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">五、学校地址</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">北校区：昌平区南口路<span style="font-size: 10.5pt;">32</span>号（主教学区），邮编：<span style="font-size: 10.5pt;">102200 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">南校区：朝阳区惠新东街<span style="font-size: 10.5pt;">5</span>号（亚运村以东小营附近），邮编：<span style="font-size: 10.5pt;">100029</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">学校网站： </span><span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">http://www.bjsyjx.org/</span></span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">我们热诚期待您的加入！</span></p><p class="Custom_UnionStyle"><span style="font-size: 10.5pt;">&nbsp;</span></p><p class="Custom_UnionStyle" style="text-align: right;">　　<span style="font-size: 10.5pt;">北京市劳动保障职业技能实训中心</span></p><p class="Custom_UnionStyle" style="text-align: right;">　　<span style="font-size: 10.5pt;">（北京市实验技工学校）</span></p><p class="Custom_UnionStyle" style="text-align: right;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">&nbsp;二</span><span style="font-size: 10.5pt;">〇</span><span style="font-size: 10.5pt;">一五年十一月</span></span></p></div></div>','　　北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。中心（技校）以北京劳动保障职业学院为依托，现已形成技师、高级工、中级工等多层次技能人才的培养格局，中职教育与高职教育无缝衔接。根据工作需要，中心（技校）公开招聘工作人员，现将有关事项公告如下：　　一、应聘基本条件　　1、坚持中国共产党的领导，热爱职业教育事业，遵纪守法、品行端正，责任心强，乐于奉献。　　2、有较强的语言表达能力、沟通协调能力和良好的文字写作能力。　　3、身心健康，年龄35周岁以下（1980年11月1日以后出生）。　　4、具有北京市常住户口，且人事行政关系在北京。　　5、具有招聘岗位所要求的学历（学位）及其他资格条件。　　二、招聘岗位及要求　　岗位需求、学历学位、所需专业、招聘人数等具体要求见附件。　　三、报名时间　　报名时间：2015年12月3日。　　四、招聘程序　　（一）网上报名：请报考人员将电子简历及《北京市实验技工学校（北京劳动保障职业技能实训中心）公开招聘报名表》（见附件）发送至电子邮箱：hr@bvclss.cn，应聘格式请注明:应聘职位-姓名-专业-学校。　　（二）资格审查　　1、对网上报名材料进行初审，初审合格者通知报送纸质材料。　　报送材料地点：北京市朝阳区惠新东街5号 人事处（北楼105室）　　  联系人：李老师 联系电话：010-80112456　　2、根据资格审查情况，确定参加初试人员名单。应聘者须对所提供的信息、资料内容的真实性、准确性负责，如有不实，将取消应聘资格。　　（三）考试及考察　　1、初选符合岗位资格人员，参加学校组织的笔试，笔试合格人员进入面试；面试合格人员进入实操考核；实操考核安排办公软件及实训设备操作，考察办公自动化水平及专业技能等，成绩均为百分制，合格分数线均为60分。　　2、对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名，按照拟招聘岗位1: 2的比例确定(不足1：2比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占30%，面试成绩占40%，实操成绩占30%。　　3、笔试、面试和实操考核具体时间另行通知。　　（四）公示及聘用　　考察合格的拟聘用人员进行公示，公示期为7个工作日。经公示无异议者，办理相关聘用手续。　　五、学校地址　　北校区：昌平区南口路32号（主教学区），邮编：102200 　　南校区：朝阳区惠新东街5号（亚运村以东小营附近），邮编：100029　　学校网站： http://www.bjsyjx.org/　　我们热诚期待您的加入！ 　　北京市劳动保障职业技能实训中心　　（北京市实验技工学校）　　 二〇一五年十一月',NULL,'2015年;下半年北京市劳动保障职业技能实训中心;（北京市实验技工学校)招聘公告','北京市劳动保障职业技能实训中心（北京市实验技工学校）（以下简称“中心（技校）”）是隶属于北京劳动保障职业学院的正处级事业单位，是一所中等职业技术学校。网上报名:请报考人员将电子简历及《北京市实验技工学校(北京劳动保障职业技能实训中心)公开招聘报名表》(见附件)发送至电子邮箱:hr@bvclss.cn,应聘格式请注明:应聘职位-姓名-专业-学校。对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名,按照拟招聘岗位1:2的比例确定(不足1：2比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占30%，面试成绩占40%，实操成绩占30%。公示及聘用考察合格的拟聘用人员进行公示,公示期为7个工作日。','自发','北京市人力资源和社会保障局','2015-11-24 14:10:00',NULL,'2024-03-06 20:57:04',6,'北京市人力资源和社会保障局',15268,'https://rsj.beijing.gov.cn/xxgk/zfxxgk/rsxx/201912/t20191206_870305.html',10),	 (870306,'2015年下半年北京劳动保障职业学院招聘公告','2015年下半年北京劳动保障职业学院招聘公告','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">北京劳动保障职业学院是经国家教育部和北京市人民政府审定核准独立设置的市属普通高职院校，隶属于北京市人力资源和社会保障局。学院以培养高级技术应用型人才为目标，现为国家骨干高职院校、北京市示范性高职院校，“全国文明单位”。根据我院工作需要，学院公开招聘工作人员，现将有关事项公告如下： </span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">一、应聘基本条件</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、坚持中国共产党的领导，热爱职业教育事业，遵纪守法、品行端正，责任心强，乐于奉献。 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、学习成绩优良，有较强的语言表达能力、沟通协调能力和良好的文字写作能力。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">3</span><span style="font-size: 10.5pt;">、身心健康，年龄<span style="font-size: 10.5pt;">40</span>周岁以下（<span style="font-size: 10.5pt;">1975</span>年<span style="font-size: 10.5pt;">11</span>月<span style="font-size: 10.5pt;">1</span>日以后出生）。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">4</span><span style="font-size: 10.5pt;">、具有招聘岗位所要求的学历（学位）及其他资格条件。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">5</span><span style="font-size: 10.5pt;">、具有北京市常住户口，且人事行政关系在北京。 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">二、招聘岗位及要求（见附件）</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">岗位需求、学历学位、所需专业、招聘人数等具体要求见附件。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">三、报名时间</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">报名截止时间：<span style="font-size: 10.5pt;">2015</span>年<span style="font-size: 10.5pt;">12</span>月<span style="font-size: 10.5pt;">3</span>日。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">四、报名方式及相关说明</span></p><p class="Custom_UnionStyle" style="text-align: left;">　　<span style="font-size: 10.5pt;">（一）网上报名：请报考人员将电子简历及《北京劳动保障职业学院公开招聘报名表》（见附件）发送至电子邮箱：<span style="font-size: 10.5pt;">rs@bvclss.c</span>，应聘格式请注明：应聘职位<span style="font-size: 10.5pt;">-</span>姓名<span style="font-size: 10.5pt;">-</span>专业<span style="font-size: 10.5pt;">-</span>学校。 </span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（二）资格审查</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、学院对网上报名材料进行初审，初审合格者通知报送纸质材料。 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">报送材料地点：北京市朝阳区惠新东街<span style="font-size: 10.5pt;">5</span>号 人事处（北楼<span style="font-size: 10.5pt;">105</span>室） </span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">联系人：李老师<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">&nbsp;&nbsp; </span></span>联系电话：<span style="font-size: 10.5pt;">010-80112456</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、根据资格审查情况，确定参加初试人员名单。应聘者须对所提供的信息、资料内容的真实性、准确性负责，如有不实，将取消应聘资格。 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（三）考试及考察</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">1</span><span style="font-size: 10.5pt;">、初选符合岗位资格人员，参加学院组织的笔试<span style="font-size: 10.5pt;">,</span>笔试合格人员进入面试；面试合格人员进入实操考核；实操考核中教师岗：安排试讲，考察面试人员授课能力；行政管理岗：安排办公软件及实训设备操作，考察办公自动化水平及专业技能等。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2</span><span style="font-size: 10.5pt;">、笔试、面试、实操考核成绩均为百分制，合格分数线为<span style="font-size: 10.5pt;">60</span>分。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">3</span><span style="font-size: 10.5pt;">、对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名，按照拟招聘岗位<span style="font-size: 10.5pt;">1: 2</span>的比例确定<span style="font-size: 10.5pt;">(</span>不足<span style="font-size: 10.5pt;">1</span>：<span style="font-size: 10.5pt;">2</span>比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占<span style="font-size: 10.5pt;">30%</span>，面试成绩占<span style="font-size: 10.5pt;">40%</span>，实操成绩占<span style="font-size: 10.5pt;">30%</span>。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">4</span><span style="font-size: 10.5pt;">、笔试、面试和实操考核具体时间另行通知。</span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">（四）公示及聘用</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">考察合格的拟聘用人员进行公示，公示期为<span style="font-size: 10.5pt;">7</span>个工作日。经公示无异议者，办理相关聘用手续。</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">五、学院地址</span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">北校区：昌平区南口路<span style="font-size: 10.5pt;">32</span>号（主教学区），邮编：<span style="font-size: 10.5pt;">102200 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">南校区：朝阳区惠新东街<span style="font-size: 10.5pt;">5</span>号（亚运村以东小营附近），邮编：<span style="font-size: 10.5pt;">100029 </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">学院网站：<span style="font-size: 10.5pt;">www.bvclss.cn </span></span></p><p class="Custom_UnionStyle">　　<span style="font-size: 10.5pt;">我们热诚期待您的加入！ </span></p><p class="Custom_UnionStyle">&nbsp;</p><p class="Custom_UnionStyle" style="text-align: right;">　　<span style="font-size: 10.5pt;">北京劳动保障职业学院</span></p><p class="Custom_UnionStyle" style="text-align: right;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">二</span><span style="font-size: 10.5pt;">〇</span><span style="font-size: 10.5pt;">一五年十一月</span></span></p></div></div>','　　北京劳动保障职业学院是经国家教育部和北京市人民政府审定核准独立设置的市属普通高职院校，隶属于北京市人力资源和社会保障局。学院以培养高级技术应用型人才为目标，现为国家骨干高职院校、北京市示范性高职院校，“全国文明单位”。根据我院工作需要，学院公开招聘工作人员，现将有关事项公告如下： 　　一、应聘基本条件　　1、坚持中国共产党的领导，热爱职业教育事业，遵纪守法、品行端正，责任心强，乐于奉献。 　　2、学习成绩优良，有较强的语言表达能力、沟通协调能力和良好的文字写作能力。　　3、身心健康，年龄40周岁以下（1975年11月1日以后出生）。　　4、具有招聘岗位所要求的学历（学位）及其他资格条件。　　5、具有北京市常住户口，且人事行政关系在北京。 　　二、招聘岗位及要求（见附件）　　岗位需求、学历学位、所需专业、招聘人数等具体要求见附件。　　三、报名时间　　报名截止时间：2015年12月3日。　　四、报名方式及相关说明　　（一）网上报名：请报考人员将电子简历及《北京劳动保障职业学院公开招聘报名表》（见附件）发送至电子邮箱：rs@bvclss.c，应聘格式请注明：应聘职位-姓名-专业-学校。 　　（二）资格审查　　1、学院对网上报名材料进行初审，初审合格者通知报送纸质材料。 　　报送材料地点：北京市朝阳区惠新东街5号 人事处（北楼105室） 　　联系人：李老师   联系电话：010-80112456　　2、根据资格审查情况，确定参加初试人员名单。应聘者须对所提供的信息、资料内容的真实性、准确性负责，如有不实，将取消应聘资格。 　　（三）考试及考察　　1、初选符合岗位资格人员，参加学院组织的笔试,笔试合格人员进入面试；面试合格人员进入实操考核；实操考核中教师岗：安排试讲，考察面试人员授课能力；行政管理岗：安排办公软件及实训设备操作，考察办公自动化水平及专业技能等。　　2、笔试、面试、实操考核成绩均为百分制，合格分数线为60分。　　3、对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名，按照拟招聘岗位1: 2的比例确定(不足1：2比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占30%，面试成绩占40%，实操成绩占30%。　　4、笔试、面试和实操考核具体时间另行通知。　　（四）公示及聘用　　考察合格的拟聘用人员进行公示，公示期为7个工作日。经公示无异议者，办理相关聘用手续。　　五、学院地址　　北校区：昌平区南口路32号（主教学区），邮编：102200 　　南校区：朝阳区惠新东街5号（亚运村以东小营附近），邮编：100029 　　学院网站：www.bvclss.cn 　　我们热诚期待您的加入！  　　北京劳动保障职业学院　　二〇一五年十一月',NULL,'2015年;下半年北京劳动保障职业学院招聘公告','北京劳动保障职业学院是经国家教育部和北京市人民政府审定核准独立设置的市属普通高职院校，隶属于北京市人力资源和社会保障局。学院以培养高级技术应用型人才为目标，现为国家骨干高职院校、北京市示范性高职院校， “全国文明单位”。初选符合岗位资格人员,参加学院组织的笔试,笔试合格人员进入面试。对完成笔试、面试、实操考核三个环节的应聘人员进行综合成绩排名,按照拟招聘岗位1:2的比例确定(不足1：2比例的，按照实际人数进行考察）考察人选，综合成绩中笔试成绩占30%，面试成绩占40%，实操成绩占30%。公示及聘用考察合格的拟聘用人员进行公示,公示期为7个工作日。北京劳动保障职业学院二〇一五年十一月。','自发','北京市人力资源和社会保障局','2015-11-24 14:07:00',NULL,'2024-03-06 20:57:04',6,'北京市人力资源和社会保障局',15268,'https://rsj.beijing.gov.cn/xxgk/zfxxgk/rsxx/201912/t20191206_870306.html',10),	 (870307,'北京市部分事业单位定向公开招聘2015年合同期满大学生村官公告','北京市部分事业单位定向公开招聘2015年合同期满大学生村官公告','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><div class="Custom_UnionStyle"><div style="overflow-x: hidden; word-break: break-all">　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发</span><span style="font-size: 10.5pt">﹝</span><span style="font-size: 10.5pt">2010</span><span style="font-size: 10.5pt">﹞</span><span style="font-size: 10.5pt">102</span><span style="font-size: 10.5pt">号），按照“公开、平等、竞争、择优”原则，结合单位实际需求，现发布定向公开招聘<span style="font-size: 10.5pt">2015</span>年北京市合同期满大学生村官公告。</span></span><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">一、&nbsp;</span><span style="font-size: 10.5pt">招聘岗位、人数</span></span></p><p>　　<span style="font-size: 10.5pt">详见附件：北京市部分事业单位定向公开招聘<span style="font-size: 10.5pt">2015</span>年</span></p><p>　　<span style="font-size: 10.5pt">合同期满大学生村官职位表。</span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">二、&nbsp;</span><span style="font-size: 10.5pt">岗位薪酬和相关待遇</span></span></p><p>　　<span style="font-size: 10.5pt">享受国家和单位规定工资福利及社会保险等待遇。</span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">三、&nbsp;</span><span style="font-size: 10.5pt">招聘程序</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">（一）</span><span style="font-size: 10.5pt">报名的基本条件</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">1、</span><span style="font-size: 10.5pt">遵守中华人民共和国宪法和法律；</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">2、</span><span style="font-size: 10.5pt">具有良好的品行和职业道德；</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">3、</span><span style="font-size: 10.5pt">具备岗位所需的专业知识或技能条件；</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">4、</span><span style="font-size: 10.5pt">身体健康；</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">5、</span><span style="font-size: 10.5pt">北京市<span style="font-size: 10.5pt">2015</span>年合同期满大学生村官。</span></span></p><p>　　<span style="font-size: 10.5pt">应聘人员不能报考与本人有应回避亲属关系的岗位。</span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">（二）</span><span style="font-size: 10.5pt">报名和资格审查</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">1、</span><span style="font-size: 10.5pt">报名时间：<span style="font-size: 10.5pt">2015</span>年<span style="font-size: 10.5pt">4</span>月<span style="font-size: 10.5pt">30</span>日<span style="font-size: 10.5pt">10</span>：<span style="font-size: 10.5pt">00-15</span>：<span style="font-size: 10.5pt">00</span>。</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">2、</span><span style="font-size: 10.5pt">报名地点：<span style="font-size: 10.5pt">2015</span>年北京市合同期满大学生村官双向选择洽谈会现场（地点：中国国际科技会展中心一层）。</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">3、</span><span style="font-size: 10.5pt">报名要求：报名时，应聘人员需持本人全日制普通高校毕业证、学位证以及身份证原件和复印件，由各区县村官办出具同意应聘的介绍信，近期<span style="font-size: 10.5pt">1</span>寸同版免冠彩色照片<span style="font-size: 10.5pt">3</span>张。每位报考者只可报考一个符合招聘条件的职位。报名提交的应聘申请材料必须真实、准确，提供虚假材料的，一经查实，即取消应聘资格。</span></span></p><p>　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">（三）</span><span style="font-size: 10.5pt">考试</span></span></p><p>　　<span style="font-size: 10.5pt">考试按照《北京市事业单位公开招聘工作人员实施办法》有关规定组织实施。依据<span style="font-size: 10.5pt">2015</span>年北京市上半年公务员考试成绩（各用人单位具体成绩要求以报名现场公示为准）；直接安排面试。面试主要测试报考人员从事专业工作所必需的基本素质和职业能力，采用百分制计分。面试时间、地点待各用人单位另行通知。</span></p><p>　　<span style="font-size: 10.5pt">面试结束后，按照公务员考试成绩、面试成绩各占<span style="font-size: 10.5pt">40%</span>、<span style="font-size: 10.5pt">60%</span>的比例，采用百分制计算报考人员的总成绩。</span></p><p>　　<span style="font-size: 10.5pt">（四）体检</span></p><p>　　<span style="font-size: 10.5pt">根据招聘岗位拟聘人数和考生的总成绩从高分到低分确定等额的人选进行体检。体检标准及项目参照《公务员录用体检通用标准（试行）》。体检不合格的，按照总成绩排序依次替补人选。</span></p><p>　　<span style="font-size: 10.5pt">（五）公示与聘用</span></p><p>　　<span style="font-size: 10.5pt">经体检合格的拟聘人员名单，由各用人单位公示，公示时间为<span style="font-size: 10.5pt">7</span>个工作日。公示结果无异议的按照有关规定办理相关手续，签订聘用合同。</span></p><p>&nbsp;</p><p>　　<span style="font-size: 10.5pt">附件：北京市部分事业单位定向公开招聘<span style="font-size: 10.5pt">2015</span>年合同期满大学生村官职位表</span></p><p>&nbsp;</p><p style="text-align:right;">　　<span style="font-size: 10.5pt">北京市人力资源和社会保障局</span></p><p style="text-align:right;">　　<span style="font-size: 10.5pt"><span style="font-size: 10.5pt">2015</span><span style="font-size: 10.5pt">年<span style="font-size: 10.5pt">4</span>月<span style="font-size: 10.5pt">21</span>日</span></span></p></div></div></div></div>','　　根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发﹝2010﹞102号），按照“公开、平等、竞争、择优”原则，结合单位实际需求，现发布定向公开招聘2015年北京市合同期满大学生村官公告。　　一、 招聘岗位、人数　　详见附件：北京市部分事业单位定向公开招聘2015年　　合同期满大学生村官职位表。　　二、 岗位薪酬和相关待遇　　享受国家和单位规定工资福利及社会保险等待遇。　　三、 招聘程序　　（一）报名的基本条件　　1、遵守中华人民共和国宪法和法律；　　2、具有良好的品行和职业道德；　　3、具备岗位所需的专业知识或技能条件；　　4、身体健康；　　5、北京市2015年合同期满大学生村官。　　应聘人员不能报考与本人有应回避亲属关系的岗位。　　（二）报名和资格审查　　1、报名时间：2015年4月30日10：00-15：00。　　2、报名地点：2015年北京市合同期满大学生村官双向选择洽谈会现场（地点：中国国际科技会展中心一层）。　　3、报名要求：报名时，应聘人员需持本人全日制普通高校毕业证、学位证以及身份证原件和复印件，由各区县村官办出具同意应聘的介绍信，近期1寸同版免冠彩色照片3张。每位报考者只可报考一个符合招聘条件的职位。报名提交的应聘申请材料必须真实、准确，提供虚假材料的，一经查实，即取消应聘资格。　　（三）考试　　考试按照《北京市事业单位公开招聘工作人员实施办法》有关规定组织实施。依据2015年北京市上半年公务员考试成绩（各用人单位具体成绩要求以报名现场公示为准）；直接安排面试。面试主要测试报考人员从事专业工作所必需的基本素质和职业能力，采用百分制计分。面试时间、地点待各用人单位另行通知。　　面试结束后，按照公务员考试成绩、面试成绩各占40%、60%的比例，采用百分制计算报考人员的总成绩。　　（四）体检　　根据招聘岗位拟聘人数和考生的总成绩从高分到低分确定等额的人选进行体检。体检标准及项目参照《公务员录用体检通用标准（试行）》。体检不合格的，按照总成绩排序依次替补人选。　　（五）公示与聘用　　经体检合格的拟聘人员名单，由各用人单位公示，公示时间为7个工作日。公示结果无异议的按照有关规定办理相关手续，签订聘用合同。 　　附件：北京市部分事业单位定向公开招聘2015年合同期满大学生村官职位表 　　北京市人力资源和社会保障局　　2015年4月21日',NULL,'大学生村官','根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发﹝2010﹞102号），按照“公开、平等、竞争、择优”原则，结合单位实际需求，现发布定向公开招聘2015年北京市合同期满大学生村官公告。','自发','北京市人力资源和社会保障局','2015-04-21 14:16:00',NULL,'2024-03-06 20:57:04',6,'北京市人力资源和社会保障局',15268,'https://rsj.beijing.gov.cn/xxgk/zfxxgk/rsxx/201912/t20191206_870307.html',10),	 (870308,'关于北京市人力社保局农民工工作处和北京市医疗保险事务管理中心2015年考试录用公务员调剂报名的公告','关于北京市人力社保局农民工工作处和北京市医疗保险事务管理中心2015年考试录用公务员调剂报名的公告','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><div class="Custom_UnionStyle"><div style="-ms-word-break: break-all; -ms-overflow-x: hidden;"><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">根据《关于<span style="font-size: 10.5pt;">2015</span>年北京市各级机关招考公务员调剂工作有关问题的通知》，现将北京市人力社保局农民工工作处和北京市医疗保险事务管理中心<span style="font-size: 10.5pt;">2015</span>年考试录用公务员调剂报名工作有关事项公告如下：</span></span> </span><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">一、调剂报名时间</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2015</span><span style="font-size: 10.5pt;">年<span style="font-size: 10.5pt;">2</span>月<span style="font-size: 10.5pt;">2</span>日</span><span style="font-size: 10.5pt;">9:00</span><span style="font-size: 10.5pt;">—<span style="font-size: 10.5pt;">17:00</span>，<span style="font-size: 10.5pt;">2</span>月<span style="font-size: 10.5pt;">3</span>日<span style="font-size: 10.5pt;">9:00</span>—<span style="font-size: 10.5pt;">17:00</span>。</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">二、调剂报名地点</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">北京市人力资源和社会保障局西办公区，</span><span style="font-size: 10.5pt;">B</span><span style="font-size: 10.5pt;">532</span><span style="font-size: 10.5pt;">房间；地址：北京市西城区永定门西街<span style="font-size: 10.5pt;">5</span>号（南二环路陶然桥东北角）。</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">调剂当天考生本人不能到场的，可由他人代理进行调剂报名，代理人除须携带本公告要求的有关材料以外，还须携带本人身份证件。</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">三、调剂报名需携带的有关材料</span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">符合北京市人力社保局农民工工作处和北京市医疗保险事务管理中心职位要求，未进入首批参加面试人选名单，且公共科目笔试成绩达到合格分数线的考生可参加该两个职位的调剂。调剂报名考生需持网上打印的报名表、成绩单、身份证原件以及所报考职位资格条件要求的相关等级、资格、资质证书原件。 </span></span></span></p><p><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2015</span><span style="font-size: 10.5pt;">年应届毕业生，须提供学生证、校级毕业生就业主管部门盖章的毕业生就业推荐表等材料原件（在外地院校就读的北京生源考生还须携带本人户口本（卡）原件）；对于京外</span><span style="font-size: 10.5pt;">“</span><span style="font-size: 10.5pt;">985</span><span style="font-size: 10.5pt;">”</span><span style="font-size: 10.5pt;"> </span><span style="font-size: 10.5pt;">高校全日制大学本科以上应届优秀毕业生，除上述材料外，还需提供校级以上“三好学生”、“优秀学生干部”或者一等以上优秀学生奖学金证书<span style="font-size: 10.5pt;">;</span>获得相当于校级以上“三好学生”、“优秀学生干部”、“一等奖学金”等同等次其它奖励项目的，应同时提供毕业学校校级就业主管部门开具的证明。</span></span></span></p><p>&nbsp;</p><p style="text-align: right;"><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">北京市人力资源和社会保障局人事处</span></span></span></p><p style="text-align: right;"><span style="font-size: 10.5pt;">　　<span style="font-size: 10.5pt;"><span style="font-size: 10.5pt;">2015</span><span style="font-size: 10.5pt;">年<span style="font-size: 10.5pt;">1</span>月<span style="font-size: 10.5pt;">30</span>日</span></span></span></p></div></div></div></div>','　　根据《关于2015年北京市各级机关招考公务员调剂工作有关问题的通知》，现将北京市人力社保局农民工工作处和北京市医疗保险事务管理中心2015年考试录用公务员调剂报名工作有关事项公告如下： 　　一、调剂报名时间　　2015年2月2日9:00—17:00，2月3日9:00—17:00。　　二、调剂报名地点　　北京市人力资源和社会保障局西办公区，B532房间；地址：北京市西城区永定门西街5号（南二环路陶然桥东北角）。　　调剂当天考生本人不能到场的，可由他人代理进行调剂报名，代理人除须携带本公告要求的有关材料以外，还须携带本人身份证件。　　三、调剂报名需携带的有关材料　　符合北京市人力社保局农民工工作处和北京市医疗保险事务管理中心职位要求，未进入首批参加面试人选名单，且公共科目笔试成绩达到合格分数线的考生可参加该两个职位的调剂。调剂报名考生需持网上打印的报名表、成绩单、身份证原件以及所报考职位资格条件要求的相关等级、资格、资质证书原件。 　　2015年应届毕业生，须提供学生证、校级毕业生就业主管部门盖章的毕业生就业推荐表等材料原件（在外地院校就读的北京生源考生还须携带本人户口本（卡）原件）；对于京外“985” 高校全日制大学本科以上应届优秀毕业生，除上述材料外，还需提供校级以上“三好学生”、“优秀学生干部”或者一等以上优秀学生奖学金证书;获得相当于校级以上“三好学生”、“优秀学生干部”、“一等奖学金”等同等次其它奖励项目的，应同时提供毕业学校校级就业主管部门开具的证明。 　　北京市人力资源和社会保障局人事处　　2015年1月30日',NULL,'北京市人力社保局农民工工作处;和北京市医疗保险事务管理中心;2015年考试录用公务员调剂报名的公告','根据《关于2015年北京市各级机关招考公务员调剂工作有关问题的通知》，现将北京市人力社保局农民工工作处和北京市医疗保险事务管理中心2015年考试录用公务员调剂报名工作有关事项公告如下：一、调剂报名时间2015年2月2日9:00—17:00， 2月3日9:00—17:00。调剂报名需携带的有关材料符合北京市人力社保局农民工工作处和北京市医疗保险事务管理中心职位要求,未进入首批参加面试人选名单，且公共科目笔试成绩达到合格分数线的考生可参加该两个职位的调剂。2015年应届毕业生，须提供学生证、校级毕业生就业主管部门盖章的毕业生就业推荐表等材料原件（在外地院校就读的北京生源考生还须携带本人户口本（卡）原件）。','自发','北京市人力资源和社会保障局','2015-01-30 14:12:00',NULL,'2024-03-06 20:57:04',6,'北京市人力资源和社会保障局',15268,'https://rsj.beijing.gov.cn/xxgk/zfxxgk/rsxx/201912/t20191206_870308.html',10),	 (870934,'北京市人力资源和社会保障局2018年部门决算信息','北京市人力资源和社会保障局2018年部门决算信息','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_word trs_key4format"><p style="text-align:center">目录</p><p style="text-indent: 0em;">第一部分 2018年度部门决算报表</p><p style="text-indent: 2em;">一、收入支出决算总表</p><p style="text-indent: 2em;">二、收入决算表</p><p style="text-indent: 2em;">三、支出决算表</p><p style="text-indent: 2em;">四、财政拨款收入支出决算总表</p><p style="text-indent: 2em;">五、一般公共预算财政拨款支出决算表</p><p style="text-indent: 2em;">六、一般公共预算财政拨款基本支出决算表</p><p style="text-indent: 2em;">七、政府性基金预算财政拨款收入支出决算表</p><p style="text-indent: 2em;">八、政府性基金预算财政拨款基本支出决算表</p><p style="text-indent: 2em;">九、财政拨款“三公”经费支出决算表</p><p style="text-indent: 2em;">十、政府采购情况表</p><p style="text-indent: 2em;">十一、政府购买服务支出情况表</p><p style="text-indent: 0em;">第二部分 2018年度部门决算说明</p><p style="text-indent: 0em;">第三部分 2018年度其他重要事项的情况说明</p><p style="text-indent: 0em;">第四部分 2018年度部门绩效评价情况</p><p style="text-indent: 0em;"><br/></p><p style="text-align: center; text-indent: 0em;">第一部分 2018年度部门决算报表<span style="text-indent: 0em;">（见附件）</span></p><p style="text-align: center; text-indent: 0em;">第二部分 2018年度部门决算说明</p><p style="text-indent: 2em;">一、部门基本情况</p><p style="text-indent: 2em;">（一）部门机构设置、职责</p><p style="text-indent: 2em;">北京市人力资源和社会保障局2018年部门决算单位共计25家，包括：行政单位1家，为北京市人力资源和社会保障局机关,包括30个内设机构；所属单位24家，分别为：北京劳动保障职业学院、北京市劳动服务管理中心、北京市社会保险基金管理中心、北京市医疗保险事务管理中心、北京市劳动能力鉴定中心、北京市人事考试中心、北京市人力资源和社会保障宣传中心、北京市职业能力建设指导中心、北京市外国专家与外国人就业事务中心、北京市人力资源和社会保障局电话咨询服务中心、北京市职业技能鉴定管理中心、北京市人才服务中心、北京市职业介绍服务中心、北京市人才档案公共管理服务中心、北京市毕业生就业服务中心、北京市军队转业干部培训中心、北京市社会保险监督委员会办公室、北京市干部度假疗养中心、北京市实验技工学校、北京市退休职工活动站、北京市人力资源和社会保障局老干部服务中心、北京市人力资源和社会保障局机关事务服务中心、北京市新型农村合作医疗服务管理中心、北京市积分落户服务中心。</p><p style="text-indent: 2em;">部门机构职责：</p><p style="text-indent: 2em;">&nbsp;&nbsp;1.贯彻落实国家关于人力资源和社会保障方面的法律法规、规章和政策，起草本市相关地方性法规草案、政府规章草案。拟订人力资源和社会保障事业发展规划，并组织实施和监督检查。</p><p style="text-indent: 2em;">2.拟订本市人力资源市场发展规划和人力资源流动政策并组织实施，建立统一规范的人力资源市场并依法管理，促进人力资源合理流动、有效配置。</p><p style="text-indent: 2em;">3.负责本市促进就业工作。拟订统筹城乡就业发展规划，完善公共就业服务体系，会同有关部门研究拟订促进就业创业政策，制定就业困难群体就业援助政策，组织拟订公益性岗位开发管理政策。拟订并落实职业资格制度和职业技能等级评价相关政策，统筹建立面向城乡劳动者的职业培训制度。牵头拟订高校毕业生就业政策，会同有关部门拟订技能人才培养和激励政策。</p><p style="text-indent: 2em;">4.统筹建立覆盖城乡的养老、失业、工伤社会保障体系。拟订本市城乡社会保险及补充保险政策和标准并组织实施。会同有关部门拟订社会保险及补充保险基金管理和监督制度，参与拟订本市社会保障基金投资政策。</p><p style="text-indent: 2em;">5.负责本市就业、失业、社会保险基金预测预警和信息引导，拟订应对预案，实施预防、调节和控制，保持就业形势稳定和社会保险基金总体收支平衡。</p><p style="text-indent: 2em;">6.负责本市公务员工资、津贴、补贴、奖金、福利等有关政策的组织实施。负责事业单位人员工资、福利的综合管理和分配制度改革工作。拟订事业单位人员工资、津贴、补贴、奖金、福利等政策并组织实施。研究建立企事业单位人员工资正常增长和支付保障机制。拟订事业单位人员离退休等政策并组织实施。</p><p style="text-indent: 2em;">7.会同有关部门指导本市事业单位人事制度改革，拟订事业单位人员管理政策。拟订专业技术人员管理和继续教育政策，牵头推进深化职称制度改革工作。健全博士后管理制度。研究拟订积分落户管理实施细则和操作规范并组织落实。拟订外国人来京就业的政策、规划和管理办法并指导实施。</p><p style="text-indent: 2em;">8.会同有关部门拟订本市农民工工作综合性政策和规划，推动落实农民工相关政策，协调解决重点难点问题，维护农民工合法权益。</p><p style="text-indent: 2em;">9.统筹拟订本市劳动关系政策和劳动人事争议调解仲裁制度，完善劳动关系协调机制。拟订企业职工工资收入分配宏观调控政策、消除非法使用童工政策、女工和未成年工特殊劳动保护政策，组织实施劳动保障监察，协调劳动者维权工作，依法查处相关重大案件。</p><p style="text-indent: 2em;">10.完成市委、市政府交办的其他任务。</p><p style="text-indent: 2em;">11.与市医保局的有关职责分工。市人力资源社会保障局统筹全市社会保障卡的发行、运用和管理工作；市医保局负责制定社会保障卡在医疗保障方面使用管理的标准规范，并会同市人力资源社会保障局做好管理工作。同时，基本医疗保险、生育保险政策的电话咨询服务，统一纳入市人力资源社会保障局咨询服务平台，市医保局负责做好相关政策的培训、群众意见建议及投诉举报的办理工作。两部门应当建立工作机制，做好信息共享和政策衔接等工作。</p><p style="text-indent: 2em;">（二）人员构成情况</p><p style="text-indent: 2em;">本部门行政编制336人，实有人数283人；事业编制1465人，实有人数1205人。</p><p style="text-indent: 2em;"><span></span>二、收入支出决算总体情况说明</p><p style="text-indent: 2em;">2018年度收、支总计235713.71万元，比上年增加3010.08万元，增长1.29%。</p><p style="text-indent: 2em;">（一）收入决算说明</p><p style="text-indent: 2em;">2018年度本年收入合计212919.01万元，比上年减少588.27万元，下降0.28%，其中：财政拨款收入202861.54万元，占收入合计的95.28%；上级补助收入0万元，占收入合计的0%；事业收入2626.32万元，占收入合计的1.23%；经营收入3.01万元，占收入合计的0.00%；附属单位上缴收入0万元，占收入合计的0%；其他收入7428.14万元，占收入合计的3.49%。</p><p style="text-indent: 2em;">（二）支出决算说明</p><p style="text-indent: 2em;">2018年度本年支出合计216002.73万元，比上年增加12528.06万元，增长6.16%，其中：基本支出60898.64万元，占支出合计的28.19%；项目支出155101.08万元，占支出合计的71.81%;上缴上级支出0万元，占支出合计的0%；经营支出3.01万元,占支出合计的0%；对附属单位补助支出0万元，占支出合计的0%。</p><p style="text-indent: 2em;">三、财政拨款收入支出决算总体情况说明</p><p style="text-indent: 2em;">2018年度财政拨款收、支总计209737.33万元，比上年增加5024.49万元，增长2.45%。主要原因：上年结转的中央转移支付项目资金在本年度支付。</p><p style="text-indent: 2em;">四、一般公共预算财政拨款支出决算情况说明</p><p style="text-indent: 2em;">（一）一般公共预算财政拨款支出决算总体情况</p><p style="text-indent: 2em;">2018年度一般公共预算财政拨款支出203872.33万元，主要用于以下方面（按大类）：一般公共服务支出11062.95万元，占本年财政拨款支出5.43%；教育支出35540.11万元，占本年财政拨款支出17.43%；社会保障和就业支出86600.48万元，占本年财政拨款支出42.48%；医疗卫生与计划生育支出70668.79万元，占本年财政拨款支出34.66%。</p><p style="text-indent: 2em;">（二）一般公共预算财政拨款支出决算具体情况</p><p style="text-indent: 2em;">1、“一般公共服务支出”（类）2018年度决算11062.95万元，比2018年年初预算减少1231.64万元，下降10.02%。其中：</p><p style="text-indent: 2em;">“人力资源事务”2018年度决算11062.95万元，比2018年年初预算减少1231.64万元，下降10.02%。主要原因：一是我局机关本级全市系统表彰奖励专项经费，由于部分奖项主办单位未按计划开展评选表彰工作，形成部分项目经费结余；二是我局机关本级留学人员创新创业特别贡献奖评选活动项目经费当年未形成支出。</p><p style="text-indent: 2em;">2、“教育支出”2018年度决算35540.11万元，比2018年年初预算减少2686.89万元，下降7.03%。其中：</p><p style="text-indent: 2em;">“普通教育”2018年度决算6462.36万元，比2018年年初预算减少37.64万元，下降0.58%。主要原因：我局所属市医疗保险事务管理中心2018年市属大专院校学生医疗费用实际申报医药费金额少于预算金额。</p><p style="text-indent: 2em;">“职业教育”2018年度决算20473.50万元，比2018年年初预算减少1011.84万元，下降4.71%。主要原因：我局所属北京劳动保障学院因2018年招生结构调整，文科生比例增加，学生实习实训支出降低。</p><p style="text-indent: 2em;">“成人教育”2018年度决算6300.97万元，比2018年年初预算减少1261.74万元，下降16.68%。主要原因：我局所属市人事考试中心2018年注册助理安全工程师取消，二级建造师、勘察设计、中央公务员等考试科次减少，考务费、资格审核费相应减少。</p><p style="text-indent: 2em;">“进修及培训”2018年度决算699.58万元，比2018年年初预算减少138.86万元，下降16.56%。主要原因：一是我局所属市劳动服务管理中心年中核减创业导师培训经费项目预算65.4万元，二是我局严格执行厉行节约、反对浪费的原则，尽量利用自有场地进行培训，节约了支出。</p><p style="text-indent: 2em;">“其他教育支出”2018年度决算1603.70万元，比2018年年初预算减少236.82万元，下降12.87%。主要原因：我局所属职业技能鉴定管理中心首次实施《国家职业资格目录》，我市可开展的职业鉴定种类减少。</p><p style="text-indent: 2em;">3、“社会保障和就业支出”2018年度决算86600.48万元，比2018年年初预算增加3068.24万元，增长3.67%。其中：</p><p style="text-indent: 2em;">“人力资源和社会保障管理事务”2018年度决算83770.58万元，比2018年年初预算增加3659.54万元，增长4.57%。主要原因：我局所属市社会保险基金管理中心年初预算未包含北京市社会保险信息系统运行维护项目经费3788.44万元,形成实际支出数大于年初预算。</p><p style="text-indent: 2em;">“行政事业单位离退休”2018年度决算2705.91万元，比2018年年初预算减少591.30万元，下降17.93%。主要原因：当期养老保险缴费额度低于预期。</p><p style="text-indent: 2em;">“其他社会保障和就业支出”2018年度决算123.99万元，与2018年年初预算一致，主要用于人力资源和社会保障宣传经费。</p><p style="text-indent: 2em;">4、“医疗卫生与计划生育支出”2018年度决算70668.78万元，比2018年年初预算增加67993.86万元，增加2541.89%。其中：</p><p style="text-indent: 2em;">“医疗卫生与计划生育管理事务”2018年度决算250.97万元，比2018年年初预算减少6.28万元，下降2.44%。主要原因:我局所属事业单位市新型农村合作医疗服务管理中心严格控制一般性支出，减少了部分支出。</p><p style="text-indent: 2em;">“行政事业单位医疗”2018年度决算70417.81万元，比2018年年初预算增加68001.03万元，增长2813.69%。主要原因:2018年年中我局所属市医疗保险事务管理中心收到中央财政转移支付资金“在京中央大专院校医疗标准费”68058.56万元，由于该项目在年中拨付，未在年初预算中批复，致使决算数比年初预算数增长较大。</p><p style="text-indent: 2em;">五、政府性基金预算财政拨款支出决算情况说明</p><p style="text-indent: 2em;">本年度无此项支出</p><p style="text-indent: 2em;">六、财政拨款基本支出决算情况说明</p><p style="text-indent: 2em;">2018年本部门使用一般公共预算财政拨款安排基本支出55862.71万元，使用政府性基金财政拨款安排基本支出0万元，其中包括：（1）工资福利支出包括基本工资、津贴补贴、奖金、伙食补助费、绩效工资、其他社会保障缴费、其他工资福利等支出；（2）商品和服务支出包括办公费、印刷费、咨询费、手续费、水费、电费、邮电费、取暖费、物业管理费、差旅费、因公出国（境）费、维修（护）费、租赁费、会议费、培训费、公务接待费、专用材料费、劳务费、委托业务费、工会经费、福利费、公务用车运行维护费、其他交通费、其他商品和服务等支出；（3）对个人和家庭补助支出包括离休费、退休费、抚恤金、生活补助、救济费、医疗费补助、助学金、奖励金、其他对个人和家庭的补助等支出。（4）其他资本性支出包括办公设备购置、专用设备购置等。</p><p style="text-align: center; text-indent: 0em;">第三部分2018年度其他重要事项的情况说明</p><p style="text-indent: 2em;"></p><p style="text-indent: 2em;">一、“三公”经费财政拨款决算情况</p><p style="text-indent: 2em;">“三公”经费包括本部门所属1个行政单位、7个参照公务员法管理事业单位、17个事业单位。2018年“三公”经费财政拨款决算数278.05万元，比2018年“三公”经费财政拨款年初预算364.95万元减少86.90万元。其中：</p><p style="text-indent: 2em;">1.“因公出国（境）费用”2018年决算数155.99万元，比2018年年初预算数210万元减少54.01万元。主要原因：我局响应北京市号召，减少出国团组，压缩出国经费；2018年因公出国（境）费用主要用于“一带一路”人才建设、公务员分类管理、海外高层次人才引进、创新创业交流合作、医疗保险支付调研、医保基金按疾病诊断培训、职业教育合作，以及京港、京澳、京台交流等方面，为全市民生工作发展提供了新思路和新视野。2018年组织因公出国（境）团组9个44人次，人均因公出国（境）费用3.55万元。</p><p style="text-indent: 2em;">2.“公务接待费”2018年决算数1.27万元，比2018年年初预算数3.7万元减少2.43万元。主要原因：我局贯彻落实中央八项规定，厉行勤俭节约，减少公务接待，使公务接待费有所减少。2018年公务接待费主要用于外单位办事人员午餐费、外省市人力社保相关人员来我局检查、考察、调研工作餐费。公务接待53批次，公务接待926人次。</p><p style="text-indent: 2em;">3.“公务用车购置及运行维护费”2018年决算数120.79万元，比2018年年初预算数151.25万元减少30.46万元。其中，公务用车购置费2018年决算数16.96万元，与2018年年初预算数16.96万元一致。2018年更新公务车1辆，车均购置费16.96万元。公务用车运行维护费2018年决算数103.83万元，比2018年年初预算数134.29万元减少30.46万元，主要原因：贯彻落实北京市政府公务车改革精神，减少机动车运行成本。2018年公务用车运行维护费中，公务用车加油43.4万元，公务用车维修25.68万元，公务用车保险16.74万元，公务用车其他支出18.01万元。2018年公务用车保有量69辆，车均运行维护费1.50万元。</p><p style="text-indent: 2em;">二、机关运行经费支出情况</p><p style="text-indent: 2em;">2018年本部门行政单位（含参照公务员法管理事业单位）使用一般公共预算财政拨款安排的基本支出中的日常公用经费支出，合计2948.84万元，比上年增加37.37万元，增加原因：物价因素造成机关运行经费有所增加。</p><p style="text-indent: 2em;">三、政府采购支出情况</p><p style="text-indent: 2em;">2018年北京市人力资源和社会保障局政府采购支出总额43262.62万元，其中：政府采购货物支出4214.33万元，政府采购工程支出1512.08万元，政府采购服务支出37536.21万元。授予中小企业合同金额41932.65万元，占政府采购支出总额的96.93%，其中：授予小微企业合同金额4522.11万元，占政府采购支出总额的10.45%。</p><p style="text-indent: 2em;">四、国有资产占用情况</p><p style="text-indent: 2em;">固定资产总额111343.15万元，其中：汽车87辆，2063.20万元；单价100万元以上的专用设备6台（套），1254.06万元。</p><p style="text-indent: 2em;">五、国有资本经营预算财政拨款收支情况</p><p style="text-indent: 2em;">本年度无此项支出</p><p style="text-indent: 2em;">六、政府购买服务支出说明</p><p style="text-indent: 2em;">2018年本部门政府购买服务决算19412.93万元。</p><p style="text-indent: 2em;">七、专业名词解释</p><p style="text-indent: 2em;">1.“三公”经费：是指单位通过财政拨款资金安排的因公出国（境）费、公务用车购置及运行费和公务接待费。其中，因公出国（境）费指单位公务出国（境）的国际旅费、国外城市间交通费、住宿费、伙食费、培训费、公杂费等支出；公务用车购置及运行费指单位公务用车车辆购置支出（含车辆购置税）及单位按规定保留的公务用车租用费、燃料费、维修费、过路过桥费、保险费、安全奖励费等支出；公务接待费指单位按规定开支的各类公务接待（含外宾接待）支出。</p><p style="text-indent: 2em;">2.机关运行经费：是指行政单位（含参照公务员法管理事业单位）使用一般公共预算财政拨款安排的基本支出中的日常公用经费支出，包括办公及印刷费、邮电费、差旅费、会议费、福利费、维修(护)费、专用材料费、办公用房水电费、办公用房取暖费、办公用房物业管理费、公务用车运行维护费以及其他费用。</p><p style="text-indent: 2em;">3.政府采购：指各级国家机关、事业单位和团体组织，使用财政性资金采购依法制定的集中目录以内的或者采购限额标准以上的货物、工程和服务的行为。</p><p style="text-indent: 2em;">4.政府购买服务：是指各级党的机关、政府机关、人大机关、政协机关、审判机关、检察机关、民主党派机关、完全或主要承担行政职能的事业单位、纳入行政编制管理且经费完全或主要由财政负担的群团组织机关通过发挥市场机制作用，根据实际需要，把直接提供的一部分公共服务事项以及政府履职所需服务事项，按照一定的方式和程序，交由具备条件的社会力量和事业单位承担，并根据合同约定向其支付费用。</p><p style="text-indent: 2em;">5.基本支出：指为保障机构正常运转、完成日常工作任务而发生的人员支出和公用支出。</p><p style="text-indent: 2em;">6.项目支出：指在基本支出之外为完成特定行政任务或事业发展目标所发生的支出。</p><p style="text-align: center; text-indent: 2em;"></p><p style="text-align: center; text-indent: 2em;">第四部分 &nbsp;2018年度部门绩效评价情况</p><p style="text-indent: 2em;"></p><p style="text-indent: 2em;">一、绩效评价工作开展情况</p><p style="text-indent: 2em;">北京市人力资源和社会保障局对2018年度部门项目支出实施绩效评价，评价项目100个，占部门项目总数的31.55%，涉及金额73444.08万元。评价结果在100-90分(含90分)，能够按照预期绩效目标设定情况达到预期绩效目标的89个；评价结果在90-75分(含75分)，基本达成预期绩效指标且效果较好的项目11个。从评价情况来看，上述项目立项科学严谨，根据国家法律法规、国民经济和社会发展规划要求，制定与我局职能、发展规划和工作计划密切相关的总体目标，确保项目预算和绩效目标的科学性、合理性以及准确性。项目执行中做好评价工作，强化过程控制，及时纠正执行过程中存在的问题，确保项目按照设定的计划进行，采取切实措施进一步改进和加强财政支出项目管理，提高财政资金使用效益。</p><p style="text-indent: 2em;">二、来京务工人员就业状况抽样调查项目绩效评价报告</p><p style="text-indent: 2em;">(一) 评价对象概况</p><p style="text-indent: 2em;">按照市委、市政府关于加强流动人口调控以及做好流动人口有序流动工作的要求，贯彻落实我市“十二五”规划部署，全面掌握来京务工人员在京就业的总体情况，为市委、市政府制定有关人口调控就业政策提供第一手基础资料，2011年，北京市人力资源和社会保障局开展了来京务工人员就业状况抽样调查工作。</p><p style="text-indent: 2em;">2012年，北京市人力资源和社会保障局和市公安局联合下发了《关于开展来京务工人员就业状况抽样调查的通知》（京人社农工发〔2012〕323号），对调查时间、调查内容和方式、调查范围及样本量、职责分工、工作制度等予以明确，并将来京务工人员就业状况抽样调查报市统计局备案，列为北京市人力资源和社会保障局一项常规性调查工作。</p><p style="text-indent: 2em;">该项目具体实施单位为北京市人力资源和社会保障局农民工工作处。通过入户问卷调查方式，对外地来京务工人员进行调查，重点掌握来京务工人员的工作状况、工薪报酬、劳动关系、社会保险、劳动技能培训和劳动参与率等情况。通过项目实施，加强北京市流动人口的管理，全面掌握来京务工人员就业的总体情况及变化趋势，健全和完善相关公共就业服务，为领导决策提供数据支持，以及为政府制定相关人口调控政策提供数据支撑。持续监测并掌握来京务工人员结构特征，对提高公共就业服务质量、制定相关就业促进政策和调控人口等具有重要作用。</p><p style="text-indent: 2em;">上、下半年各进行一次，采用问卷调查方式，抽取样本共2万个，持续监测并掌握来京务工人员结构特征、就业状况等指标，形成一套完整全面的数据分析体系，对提高公共就业服务质量、制定相关就业促进政策和调控人口等具有重要作用。来京务工人员就业状况抽样调查已成为我市人力资源市场供求监测体系的基础性制度，是综合研判来京务工人员就业、失业状况的重要基础数据来源。</p><p style="text-indent: 2em;">依据来京务工人员就业状况抽样调查数据，形成了《外来农民工总量持续下降　就业稳定性进一步增强》《禁限产业转移和新兴产业发展对北京市就业形势影响情况研究》《农民工流动状况变化对北京市人力资源供给的影响及对策研究》《技术密集型行业占比增加 就业质量持续向好》《关于回天地区劳动者职住平衡状况的报告》《我市人力资源市场供求形势的分析》《我市就业形势的分析》《北京市精细化公共就业服务实施细则》等一系列研究成果。</p><p style="text-indent: 2em;">该项目预算批复资金260.80万元，资金实际到位260.80万元，全部为北京市财政拨款。截止2018年12月31日项目实际支出260.60万元，招标结余0.20万元，已上交财政。</p><p style="text-indent: 2em;">(二) 评价结论</p><p style="text-indent: 2em;">经评价，来京务工人员就业状况抽样调查综合得分87.00分，其中，项目决策13.98分，项目管理27.72分，项目绩效45.30分，项目综合绩效评定结果为“良好”。</p><p style="text-indent: 2em;">(三) 存在问题 &nbsp;</p><p style="text-indent: 2em;">1.绩效目标的指标设置应进一步细化</p><p style="text-indent: 2em;">部分绩效目标设置量化程度不够，如“服务对象满意度指标”指标值设定为“认可”，没有具体的数值指标，不能充分反映服务对象对项目结果认可或者满意的程度。</p><p style="text-indent: 2em;">2.实施方案编制不够全面</p><p style="text-indent: 2em;">项目实施方案编制不够全面，缺少责任分工、沟通协调等方面的内容，方案的针对性、指导性、可操作性有改进提高的空间。</p><p style="text-indent: 2em;">3.管理的安全性不足</p><p style="text-indent: 2em;">目前，来京务工人员就业状况抽样调查项目的基础数据由第三方在其公司的服务器和电脑中进行管理和保存，而数据中包括了大量的个人信息和户籍信息，应提升数据的安全性。</p><p style="text-indent: 2em;">4.绩效成果应进一步体现</p><p style="text-indent: 2em;">成果应用的不够充分，绩效实现缺少量化的证明材料，例如：“市政府及对口支援办等有关部门的认可度”指标，虽然有部分单位和部门使用调查数据的成果作为绩效证明材料，但绩效成果应进一步体现。</p><p style="text-indent: 2em;">(四) 建议</p><p style="text-indent: 2em;">1.绩效目标论证和填报</p><p style="text-indent: 2em;">建议项目单位按照绩效目标表的填报要求，结合项目实际情况制定科学，合理的绩效目标。</p><p style="text-indent: 2em;">2.项目实施方案的编制</p><p style="text-indent: 2em;">建议项目单位加强项目实施方案的编制，通过制定完整、全面的实施方案并严格按照执行，可以统一思路，明确分工；可以有效的提高项目的执行效率和规范性。</p><p style="text-indent: 2em;">3数据安全管理</p><p style="text-indent: 2em;">建议加强数据安全管理，应严格控制调查数据的保存和使用，要有安全防范措施。</p><p style="text-indent: 2em;">4.项目绩效资料的收集</p><p style="text-indent: 2em;">建议项目单位在项目完成后应继续对项目实施前后的绩效数据进行采集、整理和分析，充分体现项目实施的效果。</p><p></p></div>','目录第一部分 2018年度部门决算报表一、收入支出决算总表二、收入决算表三、支出决算表四、财政拨款收入支出决算总表五、一般公共预算财政拨款支出决算表六、一般公共预算财政拨款基本支出决算表七、政府性基金预算财政拨款收入支出决算表八、政府性基金预算财政拨款基本支出决算表九、财政拨款“三公”经费支出决算表十、政府采购情况表十一、政府购买服务支出情况表第二部分 2018年度部门决算说明第三部分 2018年度其他重要事项的情况说明第四部分 2018年度部门绩效评价情况第一部分 2018年度部门决算报表（见附件）第二部分 2018年度部门决算说明一、部门基本情况（一）部门机构设置、职责北京市人力资源和社会保障局2018年部门决算单位共计25家，包括：行政单位1家，为北京市人力资源和社会保障局机关,包括30个内设机构；所属单位24家，分别为：北京劳动保障职业学院、北京市劳动服务管理中心、北京市社会保险基金管理中心、北京市医疗保险事务管理中心、北京市劳动能力鉴定中心、北京市人事考试中心、北京市人力资源和社会保障宣传中心、北京市职业能力建设指导中心、北京市外国专家与外国人就业事务中心、北京市人力资源和社会保障局电话咨询服务中心、北京市职业技能鉴定管理中心、北京市人才服务中心、北京市职业介绍服务中心、北京市人才档案公共管理服务中心、北京市毕业生就业服务中心、北京市军队转业干部培训中心、北京市社会保险监督委员会办公室、北京市干部度假疗养中心、北京市实验技工学校、北京市退休职工活动站、北京市人力资源和社会保障局老干部服务中心、北京市人力资源和社会保障局机关事务服务中心、北京市新型农村合作医疗服务管理中心、北京市积分落户服务中心。部门机构职责：  1.贯彻落实国家关于人力资源和社会保障方面的法律法规、规章和政策，起草本市相关地方性法规草案、政府规章草案。拟订人力资源和社会保障事业发展规划，并组织实施和监督检查。2.拟订本市人力资源市场发展规划和人力资源流动政策并组织实施，建立统一规范的人力资源市场并依法管理，促进人力资源合理流动、有效配置。3.负责本市促进就业工作。拟订统筹城乡就业发展规划，完善公共就业服务体系，会同有关部门研究拟订促进就业创业政策，制定就业困难群体就业援助政策，组织拟订公益性岗位开发管理政策。拟订并落实职业资格制度和职业技能等级评价相关政策，统筹建立面向城乡劳动者的职业培训制度。牵头拟订高校毕业生就业政策，会同有关部门拟订技能人才培养和激励政策。4.统筹建立覆盖城乡的养老、失业、工伤社会保障体系。拟订本市城乡社会保险及补充保险政策和标准并组织实施。会同有关部门拟订社会保险及补充保险基金管理和监督制度，参与拟订本市社会保障基金投资政策。5.负责本市就业、失业、社会保险基金预测预警和信息引导，拟订应对预案，实施预防、调节和控制，保持就业形势稳定和社会保险基金总体收支平衡。6.负责本市公务员工资、津贴、补贴、奖金、福利等有关政策的组织实施。负责事业单位人员工资、福利的综合管理和分配制度改革工作。拟订事业单位人员工资、津贴、补贴、奖金、福利等政策并组织实施。研究建立企事业单位人员工资正常增长和支付保障机制。拟订事业单位人员离退休等政策并组织实施。7.会同有关部门指导本市事业单位人事制度改革，拟订事业单位人员管理政策。拟订专业技术人员管理和继续教育政策，牵头推进深化职称制度改革工作。健全博士后管理制度。研究拟订积分落户管理实施细则和操作规范并组织落实。拟订外国人来京就业的政策、规划和管理办法并指导实施。8.会同有关部门拟订本市农民工工作综合性政策和规划，推动落实农民工相关政策，协调解决重点难点问题，维护农民工合法权益。9.统筹拟订本市劳动关系政策和劳动人事争议调解仲裁制度，完善劳动关系协调机制。拟订企业职工工资收入分配宏观调控政策、消除非法使用童工政策、女工和未成年工特殊劳动保护政策，组织实施劳动保障监察，协调劳动者维权工作，依法查处相关重大案件。10.完成市委、市政府交办的其他任务。11.与市医保局的有关职责分工。市人力资源社会保障局统筹全市社会保障卡的发行、运用和管理工作；市医保局负责制定社会保障卡在医疗保障方面使用管理的标准规范，并会同市人力资源社会保障局做好管理工作。同时，基本医疗保险、生育保险政策的电话咨询服务，统一纳入市人力资源社会保障局咨询服务平台，市医保局负责做好相关政策的培训、群众意见建议及投诉举报的办理工作。两部门应当建立工作机制，做好信息共享和政策衔接等工作。（二）人员构成情况本部门行政编制336人，实有人数283人；事业编制1465人，实有人数1205人。二、收入支出决算总体情况说明2018年度收、支总计235713.71万元，比上年增加3010.08万元，增长1.29%。（一）收入决算说明2018年度本年收入合计212919.01万元，比上年减少588.27万元，下降0.28%，其中：财政拨款收入202861.54万元，占收入合计的95.28%；上级补助收入0万元，占收入合计的0%；事业收入2626.32万元，占收入合计的1.23%；经营收入3.01万元，占收入合计的0.00%；附属单位上缴收入0万元，占收入合计的0%；其他收入7428.14万元，占收入合计的3.49%。（二）支出决算说明2018年度本年支出合计216002.73万元，比上年增加12528.06万元，增长6.16%，其中：基本支出60898.64万元，占支出合计的28.19%；项目支出155101.08万元，占支出合计的71.81%;上缴上级支出0万元，占支出合计的0%；经营支出3.01万元,占支出合计的0%；对附属单位补助支出0万元，占支出合计的0%。三、财政拨款收入支出决算总体情况说明2018年度财政拨款收、支总计209737.33万元，比上年增加5024.49万元，增长2.45%。主要原因：上年结转的中央转移支付项目资金在本年度支付。四、一般公共预算财政拨款支出决算情况说明（一）一般公共预算财政拨款支出决算总体情况2018年度一般公共预算财政拨款支出203872.33万元，主要用于以下方面（按大类）：一般公共服务支出11062.95万元，占本年财政拨款支出5.43%；教育支出35540.11万元，占本年财政拨款支出17.43%；社会保障和就业支出86600.48万元，占本年财政拨款支出42.48%；医疗卫生与计划生育支出70668.79万元，占本年财政拨款支出34.66%。（二）一般公共预算财政拨款支出决算具体情况1、“一般公共服务支出”（类）2018年度决算11062.95万元，比2018年年初预算减少1231.64万元，下降10.02%。其中：“人力资源事务”2018年度决算11062.95万元，比2018年年初预算减少1231.64万元，下降10.02%。主要原因：一是我局机关本级全市系统表彰奖励专项经费，由于部分奖项主办单位未按计划开展评选表彰工作，形成部分项目经费结余；二是我局机关本级留学人员创新创业特别贡献奖评选活动项目经费当年未形成支出。2、“教育支出”2018年度决算35540.11万元，比2018年年初预算减少2686.89万元，下降7.03%。其中：“普通教育”2018年度决算6462.36万元，比2018年年初预算减少37.64万元，下降0.58%。主要原因：我局所属市医疗保险事务管理中心2018年市属大专院校学生医疗费用实际申报医药费金额少于预算金额。“职业教育”2018年度决算20473.50万元，比2018年年初预算减少1011.84万元，下降4.71%。主要原因：我局所属北京劳动保障学院因2018年招生结构调整，文科生比例增加，学生实习实训支出降低。“成人教育”2018年度决算6300.97万元，比2018年年初预算减少1261.74万元，下降16.68%。主要原因：我局所属市人事考试中心2018年注册助理安全工程师取消，二级建造师、勘察设计、中央公务员等考试科次减少，考务费、资格审核费相应减少。“进修及培训”2018年度决算699.58万元，比2018年年初预算减少138.86万元，下降16.56%。主要原因：一是我局所属市劳动服务管理中心年中核减创业导师培训经费项目预算65.4万元，二是我局严格执行厉行节约、反对浪费的原则，尽量利用自有场地进行培训，节约了支出。“其他教育支出”2018年度决算1603.70万元，比2018年年初预算减少236.82万元，下降12.87%。主要原因：我局所属职业技能鉴定管理中心首次实施《国家职业资格目录》，我市可开展的职业鉴定种类减少。3、“社会保障和就业支出”2018年度决算86600.48万元，比2018年年初预算增加3068.24万元，增长3.67%。其中：“人力资源和社会保障管理事务”2018年度决算83770.58万元，比2018年年初预算增加3659.54万元，增长4.57%。主要原因：我局所属市社会保险基金管理中心年初预算未包含北京市社会保险信息系统运行维护项目经费3788.44万元,形成实际支出数大于年初预算。“行政事业单位离退休”2018年度决算2705.91万元，比2018年年初预算减少591.30万元，下降17.93%。主要原因：当期养老保险缴费额度低于预期。“其他社会保障和就业支出”2018年度决算123.99万元，与2018年年初预算一致，主要用于人力资源和社会保障宣传经费。4、“医疗卫生与计划生育支出”2018年度决算70668.78万元，比2018年年初预算增加67993.86万元，增加2541.89%。其中：“医疗卫生与计划生育管理事务”2018年度决算250.97万元，比2018年年初预算减少6.28万元，下降2.44%。主要原因:我局所属事业单位市新型农村合作医疗服务管理中心严格控制一般性支出，减少了部分支出。“行政事业单位医疗”2018年度决算70417.81万元，比2018年年初预算增加68001.03万元，增长2813.69%。主要原因:2018年年中我局所属市医疗保险事务管理中心收到中央财政转移支付资金“在京中央大专院校医疗标准费”68058.56万元，由于该项目在年中拨付，未在年初预算中批复，致使决算数比年初预算数增长较大。五、政府性基金预算财政拨款支出决算情况说明本年度无此项支出六、财政拨款基本支出决算情况说明2018年本部门使用一般公共预算财政拨款安排基本支出55862.71万元，使用政府性基金财政拨款安排基本支出0万元，其中包括：（1）工资福利支出包括基本工资、津贴补贴、奖金、伙食补助费、绩效工资、其他社会保障缴费、其他工资福利等支出；（2）商品和服务支出包括办公费、印刷费、咨询费、手续费、水费、电费、邮电费、取暖费、物业管理费、差旅费、因公出国（境）费、维修（护）费、租赁费、会议费、培训费、公务接待费、专用材料费、劳务费、委托业务费、工会经费、福利费、公务用车运行维护费、其他交通费、其他商品和服务等支出；（3）对个人和家庭补助支出包括离休费、退休费、抚恤金、生活补助、救济费、医疗费补助、助学金、奖励金、其他对个人和家庭的补助等支出。（4）其他资本性支出包括办公设备购置、专用设备购置等。第三部分2018年度其他重要事项的情况说明一、“三公”经费财政拨款决算情况“三公”经费包括本部门所属1个行政单位、7个参照公务员法管理事业单位、17个事业单位。2018年“三公”经费财政拨款决算数278.05万元，比2018年“三公”经费财政拨款年初预算364.95万元减少86.90万元。其中：1.“因公出国（境）费用”2018年决算数155.99万元，比2018年年初预算数210万元减少54.01万元。主要原因：我局响应北京市号召，减少出国团组，压缩出国经费；2018年因公出国（境）费用主要用于“一带一路”人才建设、公务员分类管理、海外高层次人才引进、创新创业交流合作、医疗保险支付调研、医保基金按疾病诊断培训、职业教育合作，以及京港、京澳、京台交流等方面，为全市民生工作发展提供了新思路和新视野。2018年组织因公出国（境）团组9个44人次，人均因公出国（境）费用3.55万元。2.“公务接待费”2018年决算数1.27万元，比2018年年初预算数3.7万元减少2.43万元。主要原因：我局贯彻落实中央八项规定，厉行勤俭节约，减少公务接待，使公务接待费有所减少。2018年公务接待费主要用于外单位办事人员午餐费、外省市人力社保相关人员来我局检查、考察、调研工作餐费。公务接待53批次，公务接待926人次。3.“公务用车购置及运行维护费”2018年决算数120.79万元，比2018年年初预算数151.25万元减少30.46万元。其中，公务用车购置费2018年决算数16.96万元，与2018年年初预算数16.96万元一致。2018年更新公务车1辆，车均购置费16.96万元。公务用车运行维护费2018年决算数103.83万元，比2018年年初预算数134.29万元减少30.46万元，主要原因：贯彻落实北京市政府公务车改革精神，减少机动车运行成本。2018年公务用车运行维护费中，公务用车加油43.4万元，公务用车维修25.68万元，公务用车保险16.74万元，公务用车其他支出18.01万元。2018年公务用车保有量69辆，车均运行维护费1.50万元。二、机关运行经费支出情况2018年本部门行政单位（含参照公务员法管理事业单位）使用一般公共预算财政拨款安排的基本支出中的日常公用经费支出，合计2948.84万元，比上年增加37.37万元，增加原因：物价因素造成机关运行经费有所增加。三、政府采购支出情况2018年北京市人力资源和社会保障局政府采购支出总额43262.62万元，其中：政府采购货物支出4214.33万元，政府采购工程支出1512.08万元，政府采购服务支出37536.21万元。授予中小企业合同金额41932.65万元，占政府采购支出总额的96.93%，其中：授予小微企业合同金额4522.11万元，占政府采购支出总额的10.45%。四、国有资产占用情况固定资产总额111343.15万元，其中：汽车87辆，2063.20万元；单价100万元以上的专用设备6台（套），1254.06万元。五、国有资本经营预算财政拨款收支情况本年度无此项支出六、政府购买服务支出说明2018年本部门政府购买服务决算19412.93万元。七、专业名词解释1.“三公”经费：是指单位通过财政拨款资金安排的因公出国（境）费、公务用车购置及运行费和公务接待费。其中，因公出国（境）费指单位公务出国（境）的国际旅费、国外城市间交通费、住宿费、伙食费、培训费、公杂费等支出；公务用车购置及运行费指单位公务用车车辆购置支出（含车辆购置税）及单位按规定保留的公务用车租用费、燃料费、维修费、过路过桥费、保险费、安全奖励费等支出；公务接待费指单位按规定开支的各类公务接待（含外宾接待）支出。2.机关运行经费：是指行政单位（含参照公务员法管理事业单位）使用一般公共预算财政拨款安排的基本支出中的日常公用经费支出，包括办公及印刷费、邮电费、差旅费、会议费、福利费、维修(护)费、专用材料费、办公用房水电费、办公用房取暖费、办公用房物业管理费、公务用车运行维护费以及其他费用。3.政府采购：指各级国家机关、事业单位和团体组织，使用财政性资金采购依法制定的集中目录以内的或者采购限额标准以上的货物、工程和服务的行为。4.政府购买服务：是指各级党的机关、政府机关、人大机关、政协机关、审判机关、检察机关、民主党派机关、完全或主要承担行政职能的事业单位、纳入行政编制管理且经费完全或主要由财政负担的群团组织机关通过发挥市场机制作用，根据实际需要，把直接提供的一部分公共服务事项以及政府履职所需服务事项，按照一定的方式和程序，交由具备条件的社会力量和事业单位承担，并根据合同约定向其支付费用。5.基本支出：指为保障机构正常运转、完成日常工作任务而发生的人员支出和公用支出。6.项目支出：指在基本支出之外为完成特定行政任务或事业发展目标所发生的支出。第四部分  2018年度部门绩效评价情况一、绩效评价工作开展情况北京市人力资源和社会保障局对2018年度部门项目支出实施绩效评价，评价项目100个，占部门项目总数的31.55%，涉及金额73444.08万元。评价结果在100-90分(含90分)，能够按照预期绩效目标设定情况达到预期绩效目标的89个；评价结果在90-75分(含75分)，基本达成预期绩效指标且效果较好的项目11个。从评价情况来看，上述项目立项科学严谨，根据国家法律法规、国民经济和社会发展规划要求，制定与我局职能、发展规划和工作计划密切相关的总体目标，确保项目预算和绩效目标的科学性、合理性以及准确性。项目执行中做好评价工作，强化过程控制，及时纠正执行过程中存在的问题，确保项目按照设定的计划进行，采取切实措施进一步改进和加强财政支出项目管理，提高财政资金使用效益。二、来京务工人员就业状况抽样调查项目绩效评价报告(一) 评价对象概况按照市委、市政府关于加强流动人口调控以及做好流动人口有序流动工作的要求，贯彻落实我市“十二五”规划部署，全面掌握来京务工人员在京就业的总体情况，为市委、市政府制定有关人口调控就业政策提供第一手基础资料，2011年，北京市人力资源和社会保障局开展了来京务工人员就业状况抽样调查工作。2012年，北京市人力资源和社会保障局和市公安局联合下发了《关于开展来京务工人员就业状况抽样调查的通知》（京人社农工发〔2012〕323号），对调查时间、调查内容和方式、调查范围及样本量、职责分工、工作制度等予以明确，并将来京务工人员就业状况抽样调查报市统计局备案，列为北京市人力资源和社会保障局一项常规性调查工作。该项目具体实施单位为北京市人力资源和社会保障局农民工工作处。通过入户问卷调查方式，对外地来京务工人员进行调查，重点掌握来京务工人员的工作状况、工薪报酬、劳动关系、社会保险、劳动技能培训和劳动参与率等情况。通过项目实施，加强北京市流动人口的管理，全面掌握来京务工人员就业的总体情况及变化趋势，健全和完善相关公共就业服务，为领导决策提供数据支持，以及为政府制定相关人口调控政策提供数据支撑。持续监测并掌握来京务工人员结构特征，对提高公共就业服务质量、制定相关就业促进政策和调控人口等具有重要作用。上、下半年各进行一次，采用问卷调查方式，抽取样本共2万个，持续监测并掌握来京务工人员结构特征、就业状况等指标，形成一套完整全面的数据分析体系，对提高公共就业服务质量、制定相关就业促进政策和调控人口等具有重要作用。来京务工人员就业状况抽样调查已成为我市人力资源市场供求监测体系的基础性制度，是综合研判来京务工人员就业、失业状况的重要基础数据来源。依据来京务工人员就业状况抽样调查数据，形成了《外来农民工总量持续下降　就业稳定性进一步增强》《禁限产业转移和新兴产业发展对北京市就业形势影响情况研究》《农民工流动状况变化对北京市人力资源供给的影响及对策研究》《技术密集型行业占比增加 就业质量持续向好》《关于回天地区劳动者职住平衡状况的报告》《我市人力资源市场供求形势的分析》《我市就业形势的分析》《北京市精细化公共就业服务实施细则》等一系列研究成果。该项目预算批复资金260.80万元，资金实际到位260.80万元，全部为北京市财政拨款。截止2018年12月31日项目实际支出260.60万元，招标结余0.20万元，已上交财政。(二) 评价结论经评价，来京务工人员就业状况抽样调查综合得分87.00分，其中，项目决策13.98分，项目管理27.72分，项目绩效45.30分，项目综合绩效评定结果为“良好”。(三) 存在问题  1.绩效目标的指标设置应进一步细化部分绩效目标设置量化程度不够，如“服务对象满意度指标”指标值设定为“认可”，没有具体的数值指标，不能充分反映服务对象对项目结果认可或者满意的程度。2.实施方案编制不够全面项目实施方案编制不够全面，缺少责任分工、沟通协调等方面的内容，方案的针对性、指导性、可操作性有改进提高的空间。3.管理的安全性不足目前，来京务工人员就业状况抽样调查项目的基础数据由第三方在其公司的服务器和电脑中进行管理和保存，而数据中包括了大量的个人信息和户籍信息，应提升数据的安全性。4.绩效成果应进一步体现成果应用的不够充分，绩效实现缺少量化的证明材料，例如：“市政府及对口支援办等有关部门的认可度”指标，虽然有部分单位和部门使用调查数据的成果作为绩效证明材料，但绩效成果应进一步体现。(四) 建议1.绩效目标论证和填报建议项目单位按照绩效目标表的填报要求，结合项目实际情况制定科学，合理的绩效目标。2.项目实施方案的编制建议项目单位加强项目实施方案的编制，通过制定完整、全面的实施方案并严格按照执行，可以统一思路，明确分工；可以有效的提高项目的执行效率和规范性。3数据安全管理建议加强数据安全管理，应严格控制调查数据的保存和使用，要有安全防范措施。4.项目绩效资料的收集建议项目单位在项目完成后应继续对项目实施前后的绩效数据进行采集、整理和分析，充分体现项目实施的效果。',NULL,'北京市人力资源和社会保障局;2018年部门决算信息','分别为：北京劳动保障职业学院、北京市劳动服务管理中心、北京市社会保险基金管理中心、北京市医疗保险事务管理中心、北京市劳动能力鉴定中心、北京市人事考试中心、北京市人力资源和社会保障宣传中心、北京市职业能力建设指导中心、北京市外国专家与外国人就业事务中心、北京市人力资源和社会保障局电话咨询服务中心、北京市职业技能鉴定管理中心、北京市人才服务中心、北京市职业介绍服务中心、北京市人才档案公共管理服务中心、北京市毕业生就业服务中心、北京市军队转业干部培训中心、北京市社会保险监督委员会办公室、北京市干部度假疗养中心、北京市实验技工学校、北京市退休职工活动站、北京市人力资源和社会保障局老干部服务中心、北京市人力资源和社会保障局机关事务服务中心、北京市新型农村合作医疗服务管理中心、北京市积分落户服务中心。','北京市人力资源和社会保障局','北京市人力资源和社会保障局','2018-08-28 14:11:00',NULL,'2023-08-27 18:15:33',6,'北京市人力资源和社会保障局',15258,'http://rsj.beijing.gov.cn/xxgk/zfxxgk/yjs/201912/t20191206_870934.html',10),	 (871301,'事业单位年度考核表','事业单位年度考核表',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 11:15:00',NULL,'2022-11-03 14:22:01',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/P020191206405514906113.doc',10),	 (870939,'北京市人力资源和社会保障局2019年部门预算信息','北京市人力资源和社会保障局2019年部门预算信息','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_word trs_key4format"><p style="text-align: center; text-indent: 0em;">目 &nbsp;&nbsp;录</p><p style="text-align: left; text-indent: 0em;"><strong>第一部分 2019年度部门预算情况说明</strong></p><p style="text-indent: 2em;">一、部门基本情况</p><p style="text-indent: 2em;">二、2019年收入及支出总体情况</p><p style="text-indent: 2em;">三、主要支出情况</p><p style="text-indent: 2em;">四、部门“三公”经费财政拨款预算说明</p><p style="text-indent: 2em;">五、其他情况说明</p><p style="text-indent: 2em;">六、名词解释</p><p style="text-indent: 0em;"><strong>第二部分、2019年度部门预算报表</strong></p><p style="text-indent: 2em;">一、收支总表（预算01表）</p><p style="text-indent: 2em;">二、收入总表 （预算02表）</p><p style="text-indent: 2em;">三、支出总表（预算03表）</p><p style="text-indent: 2em;">四、政府采购预算明细表（预算04表）</p><p style="text-indent: 2em;">五、财政拨款收支总表（预算05表）</p><p style="text-indent: 2em;">六、一般公共预算财政拨款支出表（预算06表）</p><p style="text-indent: 2em;">七、一般公共预算财政拨款基本支出表（预算07表）</p><p style="text-indent: 2em;">八、一般公共预算财政拨款项目支出表（预算08表）</p><p style="text-indent: 2em;">九、政府性基金预算财政拨款支出表（预算09表）</p><p style="text-indent: 2em;">十、财政拨款（含一般公共预算和政府性基金预算）“三公”经费支出表（预算10表）</p><p style="text-indent: 2em;">十一、政府购买服务预算财政拨款明细表（预算11表）</p><p style="text-indent: 2em;">十二、项目支出绩效目标申报表（预算12表）</p><h2><p style="text-align: center; text-indent: 0em;">第一部分 2019年部门预算情况说明</p></h2><p style="text-indent: 0em;"><strong>一、部门基本情况</strong></p><p style="text-indent: 2em;">（一）部门机构设置、职责</p><p style="text-indent: 2em;">北京市人力资源和社会保障局预算编制单位20个,包括局机关和16个全额拨款事业单位以及3个差额拨款事业单位。</p><p style="text-indent: 2em;"><strong>部门机构职责</strong></p><p style="text-indent: 2em;">1、贯彻落实国家关于人力资源和社会保障方面的法律、法规、规章和政策，起草本市相关地方性法规草案、政府规章草案，拟订人力资源和社会保障事业发展规划，并组织实施和监督检查。</p><p style="text-indent: 2em;">2、拟订并组织实施本市人力资源市场发展规划和人力资源流动政策，建立统一规范的人力资源市场，依法管理人力资源市场，促进人力资源合理流动、有效配置。</p><p style="text-indent: 2em;">3、负责本市促进就业工作。拟订统筹城乡的就业发展规划和政策，完善公共就业服务体系，会同有关部门研究落实就业援助制度；拟订并落实职业资格制度相关政策，统筹建立面向城乡劳动者的职业培训制度；牵头拟订高校毕业生就业政策，会同有关部门拟订高技能人才、农村实用人才培养和激励政策。</p><p style="text-indent: 2em;">4、统筹建立覆盖城乡的社会保障体系。拟订并组织实施本市城乡社会保险及补充保险政策和标准；会同有关部门拟订社会保险及补充保险基金管理和监督制度，参与拟订本市社会保障基金投资政策。</p><p style="text-indent: 2em;">5、负责本市就业、失业、社会保险基金预测预警和信息引导，拟订应对预案，实施预防、调节和控制，保持就业形势稳定和社会保险基金总体收支平衡。</p><p style="text-indent: 2em;">6、负责本市机关事业单位人员工资、福利的综合管理和分配制度改革工作；拟订机关事业单位工作人员工资、福利、津贴、补贴等政策并组织实施；研究建立机关企事业单位工作人员工资正常增长和支付保障机制；拟订机关事业单位工作人员离退休等政策并组织实施。</p><p style="text-indent: 2em;">7、会同有关部门指导本市事业单位人事制度改革，拟订事业单位人员和机关工勤人员管理政策；参与人才管理工作，拟订专业技术人员管理和继续教育政策，牵头推进深化职称制度改革工作，健全博士后管理制度。</p><p style="text-indent: 2em;">8、会同有关部门拟订本市农民工工作综合性政策和规划，推动农民工相关政策的落实，协调解决重点、难点问题，维护农民工合法权益。</p><p style="text-indent: 2em;">9、统筹拟订本市劳动关系政策和劳动、人事争议调解仲裁制度，完善劳动关系协调机制，制定消除非法使用童工政策和女工、未成年工的特殊劳动保护政策，组织实施劳动监察，协调劳动者维权工作，依法查处重大案件。</p><p style="text-indent: 2em;">10、承办市政府交办的其他事项。</p><p style="text-indent: 2em;">（二）人员构成情况</p><p style="text-indent: 2em;">北京市人力资源和社会保障局行政编制在编人员228人；事业编制在编人员1083人；聘用人员471人。离退休人员609人，其中：离休15人，退休594人。</p><p style="text-indent: 0em;"><strong>二、2019年收入及支出总体情况</strong></p><p style="text-indent: 2em;">（一）收入预算总体情况</p><p style="text-indent: 2em;">2019年收入预算132752.03万元，比2018年145888.31万元减少13136.28万元，减少9%，减少的主要原因是：因机构改革部门职责和人员数量发生变化造成经费相应减少。其中：财政拨款119239.27万元、专户管理的事业收入2738.47万元、事业收入（不含专户管理的事业收入）165万元、事业单位经营收入5万元、其他收入7276.41万元、使用结余资金和事业基金等安排下年度预算3055.51万元、继续使用的财政性结转资金272.37万元。</p><p style="text-indent: 2em;">（二）支出预算总体情况</p><p style="text-indent: 2em;">2019年支出预算132752.03万元，比2018年145888.31万元减少13136.28万元，减少9%，减少的主要原因是：因机构改革部门职责和人员数量发生变化造成经费相应减少。其中：</p><p style="text-indent: 2em;">1、基本支出预算59817.29万元，比2018年62010.62万元减少2193.33万元，减少3.54%，主要是由于机构改革人员数量发生变化造成经费相应减少。</p><p style="text-indent: 2em;">2、项目支出预算72929.74万元，比2018年83874.69万元减少10944.95万元，减少13.05%，主要是由于机构改革部门职责发生变化造成经费相应减少。</p><p style="text-indent: 2em;">3、事业单位经营支出5万元，比2018年3万元增加2万元,主要是由于我局所属事业单位增加了对外经营收入。</p><p style="text-indent: 0em;"><strong>三、主要支出情况</strong></p><p style="text-indent: 2em;">2019年支出预算主要用于促进就业、完善社会保障体系、加强人才队伍建设、推进人事制度改革、构建和谐劳动关系、做好工资收入分配及信息化建设等人力资源和社会保障相关工作。</p><p style="text-indent: 0em;"><strong>四、部门“三公”经费财政拨款预算说明</strong></p><p style="text-indent: 2em;">（一）“三公”经费的单位范围</p><p style="text-indent: 2em;">北京市人力资源和社会保障局因公出国（境）费用、公务接待费、公务用车购置和运行维护费开支单位包括局机关和5个所属单位。其他单位2019年无财政拨款安排的“三公”经费预算。</p><p style="text-indent: 2em;">（二）“三公”经费预算财政拨款情况说明</p><p style="text-indent: 2em;">2019年“三公”经费财政拨款预算324.21万元，比2018年“三公”经费财政拨款预算减少40.74万元。其中：</p><p style="text-indent: 2em;">1.因公出国（境）费用。2019年预算数185万元，比2018年预算数210万元减少25万元，主要原因：因机构改革部门职责变化减少了部分因公出国（境）费用；2019年因公出国（境）费用主要用于科技创新与人力资源发展交流合作；第45届世界技能大赛技术交流；政府雇员招聘与激励合作；保障劳动者合法权益与信息化监管机制洽谈合作；就业创业鼓励政策与举措培训；京港、京澳交流合作；随团执行出访或培训任务等方面。</p><p style="text-indent: 2em;">2.公务接待费。2019年预算数2.46万元，比2018年预算数3.7万元减少1.24万元，主要原因：落实厉行勤俭节约要求，严格控制公务接待数量、规模和接待标准，公务接待费相应减少。2019年公务接待费主要用于外省市人力社保相关人员来我局考察、调研餐费等方面。</p><p style="text-indent: 2em;">3.公务用车购置和运行维护费。2019年预算数136.75万元，其中，公务用车购置费2019年预算数14.46万元，比2018年预算数16.96万元减少2.5万元，主要原因：2019年采购公务用车型号与2018年不同造成公务用车购置费减少；公务用车运行维护费2019年预算数122.29万元，其中：公务用车燃油60.36万元，公务用车维修22.85万元，公务用车保险22.71万元，其他16.37万元。公务用车运行维护费2019年比2018预算数134.29万元减少12万元。主要原因：2019年公务用车数量减少，同时落实厉行勤俭节约等要求，进一步压缩公务车运行维护费等。</p><p style="text-indent: 0em;"><strong>五、其他情况说明</strong></p><p style="text-indent: 2em;">（一）政府采购预算说明</p><p style="text-indent: 2em;">2019年北京市人力资源和社会保障局政府采购预算总额45837万元，其中：政府采购货物预算4243.46万元，政府采购工程预算3406.1万元，政府采购服务预算38187.44万元。</p><p style="text-indent: 2em;">（二）政府购买服务预算说明</p><p style="text-indent: 2em;">2019年北京市人力资源和社会保障局政府购买服务预算总额21693.92万元。</p><p style="text-indent: 2em;">（三）机关运行经费说明</p><p style="text-indent: 2em;">2019年北京市人力资源和社会保障局北京市人力资源和社会保障局机关1家行政单位以及北京市外国专家与外国人就业事务中心、北京市社会保险基金管理中心、北京市劳动能力鉴定中心、北京市劳动服务管理中心、北京市职业能力建设指导中心等5家参公管理事业单位的机关运行经费财政拨款预算2814.92万元。</p><p style="text-indent: 2em;">（四）项目支出绩效目标情况说明</p><p style="text-indent: 2em;">2019年，填报绩效目标的预算项目86个，占全部预算项目252个的34.13%。填报绩效目标的项目支出预算62268.21万元，占全部项目支出预算的85.38%。</p><p style="text-indent: 2em;">（五）国有资本经营预算财政拨款情况说明</p><p style="text-indent: 2em;">本部门2019年无国有资本经营预算财政拨款安排的预算。</p><p style="text-indent: 2em;">（六）国有资产占用情况说明</p><p style="text-indent: 2em;">截止2018年底，本部门固定资产总额111343.15万元，其中：车辆87台，2063.2万元；单位价值50万元以上的通用设备107台（套）、19006.59万元，单位价值100万元以上的专用设备6台（套）、1254.06万元。</p><p style="text-indent: 0em;"><strong>六、名词解释</strong></p><p style="text-indent: 2em;">“三公”经费财政拨款预算数：指本部门当年部门预算安排的因公出国（境）费用、公务接待费、公务用车购置和运行维护费预算数。</p><p style="text-indent: 2em;">机关运行经费：指为保障行政单位（含参照公务员法管理事业单位）运行用于购买货物和服务的各项资金，包括办公及印刷费、邮电费、差旅费、会议费、福利费、日常维修费、专用材料及一般设备购置费、办公用房水电费、办公用房取暖费、办公用房物业管理费、公务用车运行维护费以及其他费用。</p><p style="text-indent: 2em;">退休人员社会化管理服务：是指参保职工在办理退休手续后，其管理服务工作与原企业（参保单位）分离，社保关系和人事档案移交户籍所在地街道(乡镇)社保所实行属地管理，由社保所和社区服务组织提供相应服务；或移交至政府采购项目委托的企业社保平台，由其提供相应的服务。</p><h2><p style="text-align: center; text-indent: 0em;">第二部分 2019年部门预算报表</p></h2></div>','目   录第一部分 2019年度部门预算情况说明一、部门基本情况二、2019年收入及支出总体情况三、主要支出情况四、部门“三公”经费财政拨款预算说明五、其他情况说明六、名词解释第二部分、2019年度部门预算报表一、收支总表（预算01表）二、收入总表 （预算02表）三、支出总表（预算03表）四、政府采购预算明细表（预算04表）五、财政拨款收支总表（预算05表）六、一般公共预算财政拨款支出表（预算06表）七、一般公共预算财政拨款基本支出表（预算07表）八、一般公共预算财政拨款项目支出表（预算08表）九、政府性基金预算财政拨款支出表（预算09表）十、财政拨款（含一般公共预算和政府性基金预算）“三公”经费支出表（预算10表）十一、政府购买服务预算财政拨款明细表（预算11表）十二、项目支出绩效目标申报表（预算12表）第一部分 2019年部门预算情况说明一、部门基本情况（一）部门机构设置、职责北京市人力资源和社会保障局预算编制单位20个,包括局机关和16个全额拨款事业单位以及3个差额拨款事业单位。部门机构职责1、贯彻落实国家关于人力资源和社会保障方面的法律、法规、规章和政策，起草本市相关地方性法规草案、政府规章草案，拟订人力资源和社会保障事业发展规划，并组织实施和监督检查。2、拟订并组织实施本市人力资源市场发展规划和人力资源流动政策，建立统一规范的人力资源市场，依法管理人力资源市场，促进人力资源合理流动、有效配置。3、负责本市促进就业工作。拟订统筹城乡的就业发展规划和政策，完善公共就业服务体系，会同有关部门研究落实就业援助制度；拟订并落实职业资格制度相关政策，统筹建立面向城乡劳动者的职业培训制度；牵头拟订高校毕业生就业政策，会同有关部门拟订高技能人才、农村实用人才培养和激励政策。4、统筹建立覆盖城乡的社会保障体系。拟订并组织实施本市城乡社会保险及补充保险政策和标准；会同有关部门拟订社会保险及补充保险基金管理和监督制度，参与拟订本市社会保障基金投资政策。5、负责本市就业、失业、社会保险基金预测预警和信息引导，拟订应对预案，实施预防、调节和控制，保持就业形势稳定和社会保险基金总体收支平衡。6、负责本市机关事业单位人员工资、福利的综合管理和分配制度改革工作；拟订机关事业单位工作人员工资、福利、津贴、补贴等政策并组织实施；研究建立机关企事业单位工作人员工资正常增长和支付保障机制；拟订机关事业单位工作人员离退休等政策并组织实施。7、会同有关部门指导本市事业单位人事制度改革，拟订事业单位人员和机关工勤人员管理政策；参与人才管理工作，拟订专业技术人员管理和继续教育政策，牵头推进深化职称制度改革工作，健全博士后管理制度。8、会同有关部门拟订本市农民工工作综合性政策和规划，推动农民工相关政策的落实，协调解决重点、难点问题，维护农民工合法权益。9、统筹拟订本市劳动关系政策和劳动、人事争议调解仲裁制度，完善劳动关系协调机制，制定消除非法使用童工政策和女工、未成年工的特殊劳动保护政策，组织实施劳动监察，协调劳动者维权工作，依法查处重大案件。10、承办市政府交办的其他事项。（二）人员构成情况北京市人力资源和社会保障局行政编制在编人员228人；事业编制在编人员1083人；聘用人员471人。离退休人员609人，其中：离休15人，退休594人。二、2019年收入及支出总体情况（一）收入预算总体情况2019年收入预算132752.03万元，比2018年145888.31万元减少13136.28万元，减少9%，减少的主要原因是：因机构改革部门职责和人员数量发生变化造成经费相应减少。其中：财政拨款119239.27万元、专户管理的事业收入2738.47万元、事业收入（不含专户管理的事业收入）165万元、事业单位经营收入5万元、其他收入7276.41万元、使用结余资金和事业基金等安排下年度预算3055.51万元、继续使用的财政性结转资金272.37万元。（二）支出预算总体情况2019年支出预算132752.03万元，比2018年145888.31万元减少13136.28万元，减少9%，减少的主要原因是：因机构改革部门职责和人员数量发生变化造成经费相应减少。其中：1、基本支出预算59817.29万元，比2018年62010.62万元减少2193.33万元，减少3.54%，主要是由于机构改革人员数量发生变化造成经费相应减少。2、项目支出预算72929.74万元，比2018年83874.69万元减少10944.95万元，减少13.05%，主要是由于机构改革部门职责发生变化造成经费相应减少。3、事业单位经营支出5万元，比2018年3万元增加2万元,主要是由于我局所属事业单位增加了对外经营收入。三、主要支出情况2019年支出预算主要用于促进就业、完善社会保障体系、加强人才队伍建设、推进人事制度改革、构建和谐劳动关系、做好工资收入分配及信息化建设等人力资源和社会保障相关工作。四、部门“三公”经费财政拨款预算说明（一）“三公”经费的单位范围北京市人力资源和社会保障局因公出国（境）费用、公务接待费、公务用车购置和运行维护费开支单位包括局机关和5个所属单位。其他单位2019年无财政拨款安排的“三公”经费预算。（二）“三公”经费预算财政拨款情况说明2019年“三公”经费财政拨款预算324.21万元，比2018年“三公”经费财政拨款预算减少40.74万元。其中：1.因公出国（境）费用。2019年预算数185万元，比2018年预算数210万元减少25万元，主要原因：因机构改革部门职责变化减少了部分因公出国（境）费用；2019年因公出国（境）费用主要用于科技创新与人力资源发展交流合作；第45届世界技能大赛技术交流；政府雇员招聘与激励合作；保障劳动者合法权益与信息化监管机制洽谈合作；就业创业鼓励政策与举措培训；京港、京澳交流合作；随团执行出访或培训任务等方面。2.公务接待费。2019年预算数2.46万元，比2018年预算数3.7万元减少1.24万元，主要原因：落实厉行勤俭节约要求，严格控制公务接待数量、规模和接待标准，公务接待费相应减少。2019年公务接待费主要用于外省市人力社保相关人员来我局考察、调研餐费等方面。3.公务用车购置和运行维护费。2019年预算数136.75万元，其中，公务用车购置费2019年预算数14.46万元，比2018年预算数16.96万元减少2.5万元，主要原因：2019年采购公务用车型号与2018年不同造成公务用车购置费减少；公务用车运行维护费2019年预算数122.29万元，其中：公务用车燃油60.36万元，公务用车维修22.85万元，公务用车保险22.71万元，其他16.37万元。公务用车运行维护费2019年比2018预算数134.29万元减少12万元。主要原因：2019年公务用车数量减少，同时落实厉行勤俭节约等要求，进一步压缩公务车运行维护费等。五、其他情况说明（一）政府采购预算说明2019年北京市人力资源和社会保障局政府采购预算总额45837万元，其中：政府采购货物预算4243.46万元，政府采购工程预算3406.1万元，政府采购服务预算38187.44万元。（二）政府购买服务预算说明2019年北京市人力资源和社会保障局政府购买服务预算总额21693.92万元。（三）机关运行经费说明2019年北京市人力资源和社会保障局北京市人力资源和社会保障局机关1家行政单位以及北京市外国专家与外国人就业事务中心、北京市社会保险基金管理中心、北京市劳动能力鉴定中心、北京市劳动服务管理中心、北京市职业能力建设指导中心等5家参公管理事业单位的机关运行经费财政拨款预算2814.92万元。（四）项目支出绩效目标情况说明2019年，填报绩效目标的预算项目86个，占全部预算项目252个的34.13%。填报绩效目标的项目支出预算62268.21万元，占全部项目支出预算的85.38%。（五）国有资本经营预算财政拨款情况说明本部门2019年无国有资本经营预算财政拨款安排的预算。（六）国有资产占用情况说明截止2018年底，本部门固定资产总额111343.15万元，其中：车辆87台，2063.2万元；单位价值50万元以上的通用设备107台（套）、19006.59万元，单位价值100万元以上的专用设备6台（套）、1254.06万元。六、名词解释“三公”经费财政拨款预算数：指本部门当年部门预算安排的因公出国（境）费用、公务接待费、公务用车购置和运行维护费预算数。机关运行经费：指为保障行政单位（含参照公务员法管理事业单位）运行用于购买货物和服务的各项资金，包括办公及印刷费、邮电费、差旅费、会议费、福利费、日常维修费、专用材料及一般设备购置费、办公用房水电费、办公用房取暖费、办公用房物业管理费、公务用车运行维护费以及其他费用。退休人员社会化管理服务：是指参保职工在办理退休手续后，其管理服务工作与原企业（参保单位）分离，社保关系和人事档案移交户籍所在地街道(乡镇)社保所实行属地管理，由社保所和社区服务组织提供相应服务；或移交至政府采购项目委托的企业社保平台，由其提供相应的服务。第二部分 2019年部门预算报表',NULL,'北京市人力资源和社会保障局;2019年部门预算信息','“三公”经费预算财政拨款情况说明2019年“三公”经费财政拨款预算324.21万元,比2018年“三公”经费财政拨款预算减少40.74万元。政府采购预算说明2019年北京市人力资源和社会保障局政府采购预算总额45837万元,其中：政府采购货物预算4243.46万元，政府采购工程预算3406.1万元，政府采购服务预算38187.44万元。第二部分2019年部门预算报表附件：北京市人力资源和社会保障局2019年部门预算报表。','北京市人力资源和社会保障局','北京市人力资源和社会保障局','2019-02-27 09:31:00',NULL,'2023-08-27 18:15:33',6,'北京市人力资源和社会保障局',15258,'http://rsj.beijing.gov.cn/xxgk/zfxxgk/yjs/201912/t20191206_870939.html',10);

