INSERT INTO `GovDocNews` (`o_id`,`DocTitle`,`ShortTitle`,`DocHtmlCon`,`DocContent`,`SUBDOCTITLE`,`DOCKEYWORDS`,`DocAbstract`,`DOCSOURCENAME`,`DOCAUTHOR`,`DOCRELTIME`,`DocLink`,`DOCPUBTIME`,`SITEID`,`SITENAME`,`CHANNELID`,`DOCPUBURL`,`DOCSTATUS`) VALUES	 (871298,'百千万资助项目进度及经费使用计划表（个人资助）','百千万资助项目进度及经费使用计划表（个人资助）',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 11:15:00',NULL,'2022-11-03 14:22:01',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/P020191206405493046303.doc',10),	 (871303,'北京市机关技术工人职业技能培训鉴定附件','北京市机关技术工人职业技能培训鉴定附件',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 11:15:00',NULL,'2025-01-21 09:51:15',6,'北京市人力资源和社会保障局',18477,'https://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/P020191206405538179823.rar',10),	 (1978753,'市人力资源社会保障局：下半年用“四个三”稳就业保居民就业','市人力资源社会保障局：下半年用“四个三”稳就业保居民就业','<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><p style="text-align: left; text-indent: 2em;">近日，市人力资源社会保障局召开半年工作调度推进会。局党组书记、局长徐熙在会上强调，下半年要重点完成三项指标，落实好三个政策，帮扶三个重点群体，强化三个机制，全面打好稳就业保卫战。</p><p style="text-align: left; text-indent: 2em;"></p><p style="text-indent: 2em;">面对新冠肺炎疫情，本市实施“减”“免”“缓”“返”“补”“保”等20余项政策措施，纾解企业经营困难，全力稳定工作岗位。截至6月底，本市城镇调查失业率为4.8%，就业局势保持基本稳定；通过减免养老、失业、工伤三项社会保险费，为企业减负545亿元，占五项社会保险费减免总额的近七成，惠及62.1万户企业、900.4万名职工；缓征养老、失业、工伤三险24亿元，惠及1.7万户企业。全市事业单位空余岗位主要用于招聘应届大学生。同时，本市结合疫情防控常态化的形势，着力开展以训稳岗和精准培训帮扶，推行“互联网＋职业技能培训”，截至目前，全市已有5万家享受一次性培训补贴和以训稳岗培训补贴政策的企业开展了培训，109万名企业参保职工在线参加了培训。<br/>&nbsp; &nbsp; &nbsp; 徐熙在讲话中强调，做好下半年工作，全市人社系统要会统计、会分析、敢用数、能用数、善用数，用数据推进各项工作。要提高站位，敢于担当，勇于担责，确保数据的准确性、全面性、科学性。要扎实做好“局处长走流程”专项活动，将专项活动作为下半年党建工作的抓手贯穿始终。要全面理解局处长走流程，做好“接诉即办”和“未诉先办”，在“办”字上求突破；要切实抓好活动成效；要积极创建活动品牌。<br/>&nbsp; &nbsp; &nbsp; 徐熙要求，下半年，要全面打好稳就业保卫战，要重点完成城镇调查失业率、城镇登记失业率、城镇新增就业三项指标，落实好以训稳岗、以工代训、一次性培训补贴三个政策，重点帮扶高校毕业生、就业困难人员、农村转移劳动力三个重点群体，强化中小微企业就业监测预警、“保居民就业”指标分析、就业会商三个机制。同时，要推进社保改革任务落地见效，推进专业技术人才工作创新及职称评价服务便利化改革，保持劳动关系总体和谐稳定，全面提升人社工作信息化水平，持续推进系统行风建设，完成人力资源市场立法，高质量编制好全市人力资源社会保障“十四五”规划，打好人社扶贫攻坚战。</p><p><br/></p></div>','近日，市人力资源社会保障局召开半年工作调度推进会。局党组书记、局长徐熙在会上强调，下半年要重点完成三项指标，落实好三个政策，帮扶三个重点群体，强化三个机制，全面打好稳就业保卫战。面对新冠肺炎疫情，本市实施“减”“免”“缓”“返”“补”“保”等20余项政策措施，纾解企业经营困难，全力稳定工作岗位。截至6月底，本市城镇调查失业率为4.8%，就业局势保持基本稳定；通过减免养老、失业、工伤三项社会保险费，为企业减负545亿元，占五项社会保险费减免总额的近七成，惠及62.1万户企业、900.4万名职工；缓征养老、失业、工伤三险24亿元，惠及1.7万户企业。全市事业单位空余岗位主要用于招聘应届大学生。同时，本市结合疫情防控常态化的形势，着力开展以训稳岗和精准培训帮扶，推行“互联网＋职业技能培训”，截至目前，全市已有5万家享受一次性培训补贴和以训稳岗培训补贴政策的企业开展了培训，109万名企业参保职工在线参加了培训。      徐熙在讲话中强调，做好下半年工作，全市人社系统要会统计、会分析、敢用数、能用数、善用数，用数据推进各项工作。要提高站位，敢于担当，勇于担责，确保数据的准确性、全面性、科学性。要扎实做好“局处长走流程”专项活动，将专项活动作为下半年党建工作的抓手贯穿始终。要全面理解局处长走流程，做好“接诉即办”和“未诉先办”，在“办”字上求突破；要切实抓好活动成效；要积极创建活动品牌。      徐熙要求，下半年，要全面打好稳就业保卫战，要重点完成城镇调查失业率、城镇登记失业率、城镇新增就业三项指标，落实好以训稳岗、以工代训、一次性培训补贴三个政策，重点帮扶高校毕业生、就业困难人员、农村转移劳动力三个重点群体，强化中小微企业就业监测预警、“保居民就业”指标分析、就业会商三个机制。同时，要推进社保改革任务落地见效，推进专业技术人才工作创新及职称评价服务便利化改革，保持劳动关系总体和谐稳定，全面提升人社工作信息化水平，持续推进系统行风建设，完成人力资源市场立法，高质量编制好全市人力资源社会保障“十四五”规划，打好人社扶贫攻坚战。',NULL,'城镇调查失业率;社会保险费;人力资源;工伤;城镇登记失业率;农村转移劳动力;就业困难人员;全市事业单位;人力资源市场;专业技术人才','近日，市人力资源社会保障局召开半年工作调度推进会。同时，本市结合疫情防控常态化的形势，着力开展以训稳岗和精准培训帮扶，推行“互联网＋职业技能培训”，截至目前，全市已有5万家享受一次性培训补贴和以训稳岗培训补贴政策的企业开展了培训， 109万名企业参保职工在线参加了培训。同时，要推进社保改革任务落地见效，推进专业技术人才工作创新及职称评价服务便利化改革，保持劳动关系总体和谐稳定，全面提升人社工作信息化水平，持续推进系统行风建设，完成人力资源市场立法，高质量编制好全市人力资源社会保障“十四五”规划，打好人社扶贫攻坚战。','北京市人力资源和社会保障局','北京市人力资源和社会保障局','2020-08-07 17:55:00',NULL,'2024-05-21 10:33:22',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/202008/t20200810_1978753.html',10),	 (871304,'北京市事业单位技术工人职业技能培训鉴定附件','北京市事业单位技术工人职业技能培训鉴定附件',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 11:15:00',NULL,'2022-11-03 14:22:01',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/P020191206405544868108.rar',10),	 (1665903,'市人力社保局疫情防控期间积极推行“不见面”社会保险服务措施','市人力社保局疫情防控期间积极推行“不见面”社会保险服务措施','<div class="view TRS_UEDITOR trs_paper_default trs_web trs_key4format"><p style="text-indent: 2em;">市人力社保局疫情防控期间推行“不见面”社保服务措施见成效。疫情防控期间，市人力社保局发布《关于切实做好新型冠状病毒感染肺炎疫情防控期间我市社会保险经办工作的通知》，推进“网上办理”“不见面经办”“前台接收、后台办理”“容缺受理”，普及“掌上社保”服务，倡导参保单位和个人利用“北京市社会保险网上服务平台”“北京人社”微信公众号、手机APP、电子邮箱和传真等服务功能办理业务。</p></div>','市人力社保局疫情防控期间推行“不见面”社保服务措施见成效。疫情防控期间，市人力社保局发布《关于切实做好新型冠状病毒感染肺炎疫情防控期间我市社会保险经办工作的通知》，推进“网上办理”“不见面经办”“前台接收、后台办理”“容缺受理”，普及“掌上社保”服务，倡导参保单位和个人利用“北京市社会保险网上服务平台”“北京人社”微信公众号、手机APP、电子邮箱和传真等服务功能办理业务。',NULL,'疫情防控;参保单位;肺炎疫情;服务措施;服务平台;冠状病毒;手机;不见面经办;北京人社;容缺受理','市人力社保局疫情防控期间推行“不见面”社保服务措施见成效。倡导参保单位和个人利用“北京市社会保险网上服务平台”“北京人社”微信公众号、手机APP、电子邮箱和传真等服务功能办理业务。','北京市人力资源和社会保障局','北京市人力资源和社会保障局','2020-02-21 15:19:00',NULL,'2024-05-21 10:33:24',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/202002/t20200221_1665903.html',10),	 (871305,'北京专业技术人员管理信息系统(2001版)','北京专业技术人员管理信息系统(2001版)','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="union"><span style="LINE-HEIGHT: 200%"><div class="union"><span style="color:#0066cc"><strong>如已经安装过2001年系统且没有问题，可以继续使用，不用下载程序。</strong></span></div><div class="union"><span style="color:#0066cc"></span></div><div class="union"><span style="color:#0066cc"><strong>文件下载后，解压缩至硬盘（或在解压缩后，分别将disk1,disk2,disk3三个目录内的文件拷贝至3张软盘中），然后再安装。</strong></span></div></span></div></div>','如已经安装过2001年系统且没有问题，可以继续使用，不用下载程序。文件下载后，解压缩至硬盘（或在解压缩后，分别将disk1,disk2,disk3三个目录内的文件拷贝至3张软盘中），然后再安装。',NULL,'北京专业技术人员管理信息系统;(2001版)','文件下载后，解压缩至硬盘（或在解压缩后，分别将disk1, disk2, disk3三个目录内的文件拷贝至3张软盘中），然后再安装。','自发','北京市人力资源和社会保障局','2010-09-26 15:14:00',NULL,'2023-08-22 20:42:46',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/t20191206_871305.html',10),	 (871306,'关于开展2010年度北京市新世纪百千万人才工程培养经费资助工作的通知','关于开展2010年度北京市新世纪百千万人才工程培养经费资助工作的通知','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_key4format"><p>各区、县人力社保局，市属有关部、委、办、局（总公司）、直属机构、人民团体人事（干部）处，各有关单位</p><p>人事部门：</p><p>根据《北京市贯彻落实国家人事部等七部委〈新世纪百千万人才工程实施方案〉的实施意见》（京人发</p><p>〔2003〕15号，以下简称《实施意见》）和《北京市新世纪百千万人才工程培养经费资助办法（试行）》（京人</p><p>发〔2004〕100号，以下简称《资助办法》）,为加强本市高层次专业技术人才培养工作，经研究决定，2010年继</p><p>续开展新世纪百千万人才工程培养经费资助工作，现就有关事项通知如下：</p><p>一、资助对象</p><p>在本市单位从事专业技术工作的新世纪百千万人才工程国家级人选和市级人选；根据《实施意见》，制定并</p><p>实施了本单位高层次专业技术人才培养计划的本市单位（含非公经济组织）。</p><p>已获得新世纪百千万人才工程培养经费资助的个人或单位，受资助项目未完成或已完成但未提交项目结题报</p><p>告和经费使用明细的，本次不能申请资助。</p><p>二、资助类别</p><p>资助分为个人资助和专项资助。个人资助包括培训研修类（A类）、创新研发类（B类）、学术交流类（C类）</p><p>、出版专著类（D类）等四类。专项资助用于资助本市单位开展高层次人才培养工作。</p><p>三、申报程序</p><p>（一）申请个人资助</p><p>1、工程人选本人填写《北京市新世纪百千万人才工程培养经费资助申请人登记表》（以下简称《登记表》）</p><p>、《北京市新世纪百千万人才工程培养经费资助申请表（个人申请用）》（以下简称《个人资助申请表》，按申</p><p>请资助类别填写）。</p><p>2、工程人选所在单位对申报材料的真实性进行核实并签署意见、加盖公章后，报上级主管单位人事部门。</p><p>3、上级主管单位人事部门对本地区、本部门工程人选申请资助的情况进行汇总，填写《申请北京市新世纪百</p><p>千万人才工程培养经费资助人选情况一览表》（以下简称《一览表》），在对人选申报材料做进一步审核，签署</p><p>意见、加盖公章后，一并报市人力社保局。</p><p>（二）申请专项资助</p><p>申请单位填写《北京市新世纪百千万人才工程专项培养经费资助申请表（单位申请用）》（以下简称《专项</p><p>资助申请表》），签署意见、加盖公章后，报市人力社保局。</p><p>四、报送材料的内容和要求</p><p>（一）报送材料内容</p><p>申请个人资助需报送：《登记表》、《个人资助申请表》各一式8份、《一览表》1份；“北京市新世纪百千</p><p>万人才工程培养经费资助信息系统（单位版）”（以下简称资助系统）生成的数据上报文件。<br/>申请专项资助需报送：本单位高层次专业技术人才培养计划及其实施情况的报告1份、《专项资助申请表》一式2</p><p>份。</p><p>（二）报送要求</p><p>1、《资助办法》、有关申报表格、资助系统软件（单位版、个人版）可从北京市人力资源和社会保障局网站</p><p>（<span>rsj.beijing.gov.cn</span>）的“网上办事”栏目下载，安装使用。</p><p>2、请将《登记表》与《个人资助申请表》装订在一起。</p><p>3、所报送的材料除人才培养计划及其实施情况的报告外，均需提供由Word软件制作的电子文本，其中《登记</p><p>表》、《个人资助申请表》、《一览表》也可由资助系统自动生成。</p><p>4、请于2010年9月29日至30日将申报材料报送市人力社保局专家与博士后工作处；工程人选申请C类资助，也</p><p>可在所主办或参加会议的前两个月将申报材料报送市人力社保局专家与博士后工作处。</p><p>5、所报送的材料应不涉及国家和商业秘密。工程人选和有关单位应按相关规定，慎重处理涉密问题。</p><p>联系人：辛向阳 </p><p>联系电话：（010）65261459 、（010）65256072（传真）</p><p>系统软件支持电话（010）51660877转801－810或231</p><p style="text-align: right;">北京市人力资源和社会保障局<br/>　　　　　　　　　　　　　　　　　&nbsp; 二О一О年八月三十一日</p><p style="text-align: right;">主题词：专业技术人员&nbsp; 人才工程△&nbsp; 资助&nbsp; 通知 　　　　　&nbsp; <br/>北京市人力资源和社会保障局办公室&nbsp; 2010年9月3日印发&nbsp;</p></div>','各区、县人力社保局，市属有关部、委、办、局（总公司）、直属机构、人民团体人事（干部）处，各有关单位人事部门：根据《北京市贯彻落实国家人事部等七部委〈新世纪百千万人才工程实施方案〉的实施意见》（京人发〔2003〕15号，以下简称《实施意见》）和《北京市新世纪百千万人才工程培养经费资助办法（试行）》（京人发〔2004〕100号，以下简称《资助办法》）,为加强本市高层次专业技术人才培养工作，经研究决定，2010年继续开展新世纪百千万人才工程培养经费资助工作，现就有关事项通知如下：一、资助对象在本市单位从事专业技术工作的新世纪百千万人才工程国家级人选和市级人选；根据《实施意见》，制定并实施了本单位高层次专业技术人才培养计划的本市单位（含非公经济组织）。已获得新世纪百千万人才工程培养经费资助的个人或单位，受资助项目未完成或已完成但未提交项目结题报告和经费使用明细的，本次不能申请资助。二、资助类别资助分为个人资助和专项资助。个人资助包括培训研修类（A类）、创新研发类（B类）、学术交流类（C类）、出版专著类（D类）等四类。专项资助用于资助本市单位开展高层次人才培养工作。三、申报程序（一）申请个人资助1、工程人选本人填写《北京市新世纪百千万人才工程培养经费资助申请人登记表》（以下简称《登记表》）、《北京市新世纪百千万人才工程培养经费资助申请表（个人申请用）》（以下简称《个人资助申请表》，按申请资助类别填写）。2、工程人选所在单位对申报材料的真实性进行核实并签署意见、加盖公章后，报上级主管单位人事部门。3、上级主管单位人事部门对本地区、本部门工程人选申请资助的情况进行汇总，填写《申请北京市新世纪百千万人才工程培养经费资助人选情况一览表》（以下简称《一览表》），在对人选申报材料做进一步审核，签署意见、加盖公章后，一并报市人力社保局。（二）申请专项资助申请单位填写《北京市新世纪百千万人才工程专项培养经费资助申请表（单位申请用）》（以下简称《专项资助申请表》），签署意见、加盖公章后，报市人力社保局。四、报送材料的内容和要求（一）报送材料内容申请个人资助需报送：《登记表》、《个人资助申请表》各一式8份、《一览表》1份；“北京市新世纪百千万人才工程培养经费资助信息系统（单位版）”（以下简称资助系统）生成的数据上报文件。申请专项资助需报送：本单位高层次专业技术人才培养计划及其实施情况的报告1份、《专项资助申请表》一式2份。（二）报送要求1、《资助办法》、有关申报表格、资助系统软件（单位版、个人版）可从北京市人力资源和社会保障局网站（rsj.beijing.gov.cn）的“网上办事”栏目下载，安装使用。2、请将《登记表》与《个人资助申请表》装订在一起。3、所报送的材料除人才培养计划及其实施情况的报告外，均需提供由Word软件制作的电子文本，其中《登记表》、《个人资助申请表》、《一览表》也可由资助系统自动生成。4、请于2010年9月29日至30日将申报材料报送市人力社保局专家与博士后工作处；工程人选申请C类资助，也可在所主办或参加会议的前两个月将申报材料报送市人力社保局专家与博士后工作处。5、所报送的材料应不涉及国家和商业秘密。工程人选和有关单位应按相关规定，慎重处理涉密问题。联系人：辛向阳 联系电话：（010）65261459 、（010）65256072（传真）系统软件支持电话（010）51660877转801－810或231北京市人力资源和社会保障局　　　　　　　　　　　　　　　　　  二О一О年八月三十一日主题词：专业技术人员  人才工程△  资助  通知 　　　　　  北京市人力资源和社会保障局办公室  2010年9月3日印发','京人社专家发〔2010〕211号','2010年度;北京市;新世纪百千万人才工程培养经费资助工作','各区、县人力社保局，市属有关部、委、办、局（总公司）、直属机构、人民团体人事（干部）处，各有关单位人事部门：根据《北京市贯彻落实国家人事部等七部委〈新世纪百千万人才工程实施方案〉的实施意见》（京人发〔2003〕15号。工程人选本人填写《北京市新世纪百千万人才工程培养经费资助申请人登记表》(以下简称《登记表》)、《北京市新世纪百千万人才工程培养经费资助申请表(个人申请用)》(以下简称《个人资助申请表》,按申请资助类别填写）。（010）51660877转801－810或231北京市人力资源和社会保障局二О一О年八月三十一日主题词：专业技术人员人才工程△资助通知北京市人力资源和社会保障局办公室2010年9月3日印发.','自发','北京市人力资源和社会保障局','2010-09-03 16:36:00',NULL,'2023-08-22 20:42:46',6,'北京市人力资源和社会保障局',18477,'http://rsj.beijing.gov.cn/fuwu/bmxz/rcdw/201912/t20191206_871306.html',10),	 (871507,'人力资源社会保障报表管理系统（测试版）','人力资源社会保障报表管理系统（测试版）',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2019-12-06 11:35:00',NULL,'2022-12-06 14:34:07',6,'北京市人力资源和社会保障局',18480,'http://rsj.beijing.gov.cn/fuwu/bmxz/gz/201912/P020191206417331078256.rar',10),	 (900010,'该项考试的考场规则是如何规定的？','该项考试的考场规则是如何规定的？','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_key4format"><div>答：点击该项考试打印准考证链接，阅读考场规则和违纪违规及相关须知后方可打印准考证。</div></div>','答：点击该项考试打印准考证链接，阅读考场规则和违纪违规及相关须知后方可打印准考证。',NULL,'该项考试的考场规则','答：点击该项考试打印准考证链接，阅读考场规则和违纪违规及相关须知后方可打印准考证。','自发','北京市人力资源和社会保障局','2017-03-16 11:19:00',NULL,'2023-08-28 10:17:43',6,'北京市人力资源和社会保障局',18590,'http://rsj.beijing.gov.cn/ywsite/bjpta/fwzn/cjwt/kq/201912/t20191206_900010.html',10),	 (4038433,'人事考试，一看就会   第一期   全国报名平台考生注册',NULL,NULL,NULL,'人事考试',NULL,NULL,'北京市人事考评办公室',NULL,'2025-03-19 14:14:00','https://play.shipin.beijing.gov.cn/vod/64329692/srlsbjcpk/mrlm/2025/03/19/485A29DF7F3B438d8DF43855B8EAE5CA1.mp4','2025-03-20 09:38:38',6,'北京市人力资源和社会保障局',63647,'https://play.shipin.beijing.gov.cn/vod/64329692/srlsbjcpk/mrlm/2025/03/19/485A29DF7F3B438d8DF43855B8EAE5CA1.mp4',10);

