INSERT INTO `GovDocNews` (`o_id`,`DocTitle`,`ShortTitle`,`DocHtmlCon`,`DocContent`,`SUBDOCTITLE`,`DOCKEYWORDS`,`DocAbstract`,`DOCSOURCENAME`,`DOCAUTHOR`,`DOCRELTIME`,`DocLink`,`DOCPUBTIME`,`SITEID`,`SITENAME`,`CHANNELID`,`DOCPUBURL`,`DOCSTATUS`) VALUES	 (1980429,'【重要通知】本市发布强降雨重要提示信息',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_web trs_key4format"><p style="text-indent: 2em;">北京市防汛指挥部提示：8月12日早晨至夜间我市将有大到暴雨，倡议各单位实行弹性工作制、居家办公，建议市民减少出行，停放车辆注意安全，避免到山区、景区、河边和危险地带。建议全市在建工地停止施工。</p></div>','北京市防汛指挥部提示：8月12日早晨至夜间我市将有大到暴雨，倡议各单位实行弹性工作制、居家办公，建议市民减少出行，停放车辆注意安全，避免到山区、景区、河边和危险地带。建议全市在建工地停止施工。',NULL,NULL,'北京市防汛指挥部提示：8月12日早晨至夜间我市将有大到暴雨，倡议各单位实行弹性工作制、居家办公，建议市民减少出行，停放车辆注意安全，避免到山区、景区、河边和危险地带。','北京市突发事件预警信息发布中心','北京市人力资源和社会保障局','2020-08-11 19:51:00',NULL,'2023-08-24 20:20:25',6,'北京市人力资源和社会保障局',16733,'http://rsj.beijing.gov.cn/weimenhu/wgsgg/202008/t20200811_1980429.html',10),	 (1799799,'北京多措并举助力受援地区贫困劳动力就业脱贫',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><div></div><p style="text-indent: 2em;"><span style="text-align: left">北京市人力资源和社会保障局今天表示，2019年该局与北京市扶贫支援办、各前方指挥部和挂职干部团队共同努力，帮助受援地区建档立卡贫困劳动力13.1万人实现就业。2020年，还将通过就业扶贫专项行动、技能培训、跟踪帮扶、人才智力帮扶等多种形式，帮助对口地区贫困群众实现就业脱贫。<br/></span></p><p style="text-indent: 2em;">“四个结合”助建档立卡贫困劳动力就业</p><p style="text-align: left; text-indent: 2em;">北京市人力资源和社会保障局表示，2019年，北京与河北、内蒙等地区通过“省级对接”结合“区级结对”，签订扶贫劳务协作协议，出台支持建档立卡贫困人口创业就业的税收减免政策等进行精准帮扶；通过“大规模技能培训”结合“院校学制培养”，帮助贫困家庭学生实现技能脱贫；通过“市场主体带动”结合“政府兜底”，保障贫困劳动力就近就业；通过“岗位供给”结合“需求清单”，向贫困人员精准提供就业信息，全年发布招聘岗位信息约20万条。</p><p style="text-align: left; text-indent: 2em;">疫情防控期间多措并举助力脱贫攻坚</p><p style="text-align: left; text-indent: 2em;">2020年，在新冠肺炎防控关键时期，北京市各级人力资源社会保障部门以“组合拳”方式助力脱贫攻坚。</p><p style="text-align: left; text-indent: 2em;">据介绍，北京市海淀区人力资源和社会保障局通过“摸需求、拓平台、强特色”，建立线上沟通对接机制，了解受援地培训需求，联合市农林科学院，通过视频直播、专家在线答疑等方式，将传统线下“面对面”培训转变为线上“点单式”个性化特色培训。目前已开展8期直播，累计1万余人次观看；丰台区人力资源和社会保障局与受援地区共同建立定期反馈机制，跟踪统计在京就业人员返岗复工、扶贫车间复工、吸纳贫困劳动力就业等情况，做到“底数清，情况明”，并通过短信、微信平台向复工人员发送复工须知与疫情防控知识。对有集体返京需求的务工群体，采取统一组织、统一体检、统一包车、统一防护保障的措施，严格按照疫情防控要求，实行从受援地到企业的“点对点”复工，全力促进群众稳定就业、实现增收。</p><p style="text-align: left; text-indent: 2em;">另外，门头沟、通州、东城、石景山、顺义、平谷、怀柔、延庆等区人力资源社会保障局开展多种形式的帮扶活动。比如，有些区与帮扶地区联合开展线上“春风”招聘活动和各类重点企业专场招聘活动，将所有的招聘活动由线下转到线上，为贫困劳动力搭建网络用工对接平台，提供网络招聘会、职业指导、服务指南等线上就业服务，引导帮扶地区劳动者选择非接触式途径实现就业。截至目前，北京市共组织“春风行动暨就业援助月”线上活动180余场，发布企业招聘岗位4.7万个。</p><p style="text-align: left; text-indent: 2em;">四项措施重点助贫困劳动力转移就业</p><p style="text-align: left; text-indent: 2em;">2020年是全面打赢脱贫攻坚战的收官之年。北京市人力资源和社会保障局表示，将重点帮助贫困劳动力转移就业。其中，将开展就业扶贫专项行动，继续把北京优势产业、龙头企业引入到受援地区，扶持当地及周边特色产业发展；通过技能培训，促进贫困劳动力就近就业，尤其是让贫困家庭的孩子掌握一技之长，具备就业能力。</p><p style="text-align: left; text-indent: 2em;">该局表示，北京还将跟踪帮扶在京贫困劳动力，帮助他们实现稳定就业。用好人才智力帮扶，结合受援地区需求，鼓励北京市高技能人才、技能大师工作室团队、博士后设站单位赴受援地区开展专家智力支援等活动，共同助力打赢脱贫攻坚战。</p><p><br/></p></div>','北京市人力资源和社会保障局今天表示，2019年该局与北京市扶贫支援办、各前方指挥部和挂职干部团队共同努力，帮助受援地区建档立卡贫困劳动力13.1万人实现就业。2020年，还将通过就业扶贫专项行动、技能培训、跟踪帮扶、人才智力帮扶等多种形式，帮助对口地区贫困群众实现就业脱贫。“四个结合”助建档立卡贫困劳动力就业北京市人力资源和社会保障局表示，2019年，北京与河北、内蒙等地区通过“省级对接”结合“区级结对”，签订扶贫劳务协作协议，出台支持建档立卡贫困人口创业就业的税收减免政策等进行精准帮扶；通过“大规模技能培训”结合“院校学制培养”，帮助贫困家庭学生实现技能脱贫；通过“市场主体带动”结合“政府兜底”，保障贫困劳动力就近就业；通过“岗位供给”结合“需求清单”，向贫困人员精准提供就业信息，全年发布招聘岗位信息约20万条。疫情防控期间多措并举助力脱贫攻坚2020年，在新冠肺炎防控关键时期，北京市各级人力资源社会保障部门以“组合拳”方式助力脱贫攻坚。据介绍，北京市海淀区人力资源和社会保障局通过“摸需求、拓平台、强特色”，建立线上沟通对接机制，了解受援地培训需求，联合市农林科学院，通过视频直播、专家在线答疑等方式，将传统线下“面对面”培训转变为线上“点单式”个性化特色培训。目前已开展8期直播，累计1万余人次观看；丰台区人力资源和社会保障局与受援地区共同建立定期反馈机制，跟踪统计在京就业人员返岗复工、扶贫车间复工、吸纳贫困劳动力就业等情况，做到“底数清，情况明”，并通过短信、微信平台向复工人员发送复工须知与疫情防控知识。对有集体返京需求的务工群体，采取统一组织、统一体检、统一包车、统一防护保障的措施，严格按照疫情防控要求，实行从受援地到企业的“点对点”复工，全力促进群众稳定就业、实现增收。另外，门头沟、通州、东城、石景山、顺义、平谷、怀柔、延庆等区人力资源社会保障局开展多种形式的帮扶活动。比如，有些区与帮扶地区联合开展线上“春风”招聘活动和各类重点企业专场招聘活动，将所有的招聘活动由线下转到线上，为贫困劳动力搭建网络用工对接平台，提供网络招聘会、职业指导、服务指南等线上就业服务，引导帮扶地区劳动者选择非接触式途径实现就业。截至目前，北京市共组织“春风行动暨就业援助月”线上活动180余场，发布企业招聘岗位4.7万个。四项措施重点助贫困劳动力转移就业2020年是全面打赢脱贫攻坚战的收官之年。北京市人力资源和社会保障局表示，将重点帮助贫困劳动力转移就业。其中，将开展就业扶贫专项行动，继续把北京优势产业、龙头企业引入到受援地区，扶持当地及周边特色产业发展；通过技能培训，促进贫困劳动力就近就业，尤其是让贫困家庭的孩子掌握一技之长，具备就业能力。该局表示，北京还将跟踪帮扶在京贫困劳动力，帮助他们实现稳定就业。用好人才智力帮扶，结合受援地区需求，鼓励北京市高技能人才、技能大师工作室团队、博士后设站单位赴受援地区开展专家智力支援等活动，共同助力打赢脱贫攻坚战。',NULL,NULL,NULL,'中国新闻网',NULL,'2020-04-02 15:38:00',NULL,'2023-08-28 07:57:24',6,'北京市人力资源和社会保障局',15299,'http://rsj.beijing.gov.cn/weimenhu/wmtgz/202004/t20200410_1799799.html',10),	 (1980612,'北京日常防疫指引——体育馆/游泳场馆篇',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_web trs_key4format"><p style="text-align: center;"><img src="/webpic/W0202008/W020200812/W020200812342538205256.jpg" width="800" height="4252" title="北京日常防疫指引——体育馆/游泳场馆篇" alt="北京日常防疫指引——体育馆/游泳场馆篇" style="text-align: center" OLDSRC="W020200812342538205256.jpg" /></p></div>',NULL,NULL,'北京日常防疫指引——体育馆/游泳场馆篇','北京日常防疫指引——体育馆/游泳场馆篇','首都之窗',NULL,'2020-08-11 18:30:00',NULL,'2021-07-08 17:51:44',6,'北京市人力资源和社会保障局',31112,'http://rsj.beijing.gov.cn/bm/ztzl/yqzl/ts/202008/t20200812_1980612.html',10),	 (3496697,'昌平区教委所属中小学面向2024年应届毕业生公开招聘教师公告',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><p><br/></p><p style="text-indent: 2em;">根据《事业单位公开招聘人员暂行规定》（人事部令第6号）及《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号），结合用人单位工作需要，昌平区教委所属中小学现面向2024年应届毕业生公开招聘教师。现就有关事项公告如下：</p><p style="text-indent: 2em;">一、招聘岗位及数量</p><p style="text-indent: 2em;">本次共招聘专技岗位教师133人。岗位及资格条件详见《昌平区教委所属中小学面向2024年应届毕业生公开招聘教师岗位和资格条件》（附件1）。</p><p style="text-indent: 2em;">二、招聘对象</p><p style="text-indent: 2em;">招聘岗位限列入国家统一招生计划（不含定向、委培），本科及以上学历且能如期取得相应学历、学位证书的普通高等院校2024年应届毕业生。</p><p style="text-indent: 2em;">注：两年内离校未就业的毕业生可报考2024年应届毕业生岗位。两年内离校未就业的毕业生指列入国家统一招生计划，培养方式为非定向（不含定向、委培），离校时和在国家规定的择业期内未落实工作单位，其户口、人事档案、组织关系仍保留在原毕业学校，或保留在各级毕业生就业主管部门（毕业生就业指导服务中心）、各级人才交流服务机构和各级公共就业服务机构，且择业期内未缴纳社会保险的2022年和2023年毕业生。</p><p style="text-indent: 2em;">三、招聘条件</p><p style="text-indent: 2em;">（一）基本要求：具有中华人民共和国国籍；拥护中国共产党的领导，遵守宪法和法律，具有良好的品行；热爱教育事业，具有岗位需要的专业和技能；符合岗位要求的身体条件；符合岗位所规定的其他条件；</p><p style="text-indent: 2em;">（二）年龄要求：本科毕业生25周岁及以下（1999年1月1日及以后出生）；硕士毕业生30周岁及以下（1994年1月1日及以后出生）；博士毕业生35周岁及以下（1989年1月1日及以后出生）；</p><p style="text-indent: 2em;">（三）户口要求：北京生源须具有北京市常住户口（不含户口及档案寄存在毕业学校的非北京生源毕业生）；非北京生源毕业生需符合进京审批条件，就读最高学历期间无社保缴纳记录；</p><p style="text-indent: 2em;">（四）专业要求：最高学历所学专业须与所报岗位学科要求的专业相符（专业要求参照教育部专业目录执行)；</p><p style="text-indent: 2em;">（五）教师资格要求：须具有招聘岗位所需级别和学科的教师资格（已取得“教师资格证书”或“有效期内的中小学教师资格考试合格证明”或“校级教务部门开具的师范生证明”）。相同学科的普通中、小学教师资格，高级别的适用于低级别，例如：持有高级中学数学教师资格人员，可申报高中数学教师岗位，也可申报初中或小学数学教师岗位；</p><p style="text-indent: 2em;">（六）学历及学位要求：2024年7月1日前须取得本科及以上学历及相应学位；</p><p style="text-indent: 2em;">（七）其他要求：同时须符合招聘岗位要求的其他条件。</p><p style="text-indent: 2em;">四、招聘程序</p><p style="text-indent: 2em;">（一）报名和资格初审</p><p style="text-indent: 2em;">1.报名时间：2023年12月22日—12月23日，上午8:30—11:00；下午14:00—16:30。</p><p style="text-indent: 2em;">2.报名地点：详见附件1中的联系信息栏。</p><p style="text-indent: 2em;">3.报名及资格初审：必须本人现场报名，各招聘单位当场进行资格初审。</p><p style="text-indent: 2em;">4.在本次招聘提供的133个岗位中，每位报名人员仅限报考一个岗位，重复报名者将取消本次招聘所有聘用资格。请报考人员切勿选报多个岗位。</p><p style="text-indent: 2em;">5.报名须持材料（请按以下顺序排列）：</p><p style="text-indent: 2em;">（1）《昌平区事业单位公开招聘工作人员报名表》（附件2）原件，请粘贴近期二寸彩色免冠正面照片，其中本人签字处须手签姓名；</p><p style="text-indent: 2em;">（2）身份证原件、复印件；</p><p style="text-indent: 2em;">（3）户口簿原件、户口簿首页和本人页复印件；户口在集体户的须提交集体户首页复印件（须加盖户籍管理部门公章）、本人页原件及本人页复印件，或集体户户籍管理部门出具并盖章的户口证明原件（写明“姓名、身份证号、其户籍在XX集体户”即可）、复印件；</p><p style="text-indent: 2em;">（4）教师资格方面，提供下列材料之一：A.已取得教师资格证书的提交教师资格证书原件、复印件；B.取得有效期内“中小学教师资格考试合格证明”的（有效期内教师资格笔试及面试各科考试均合格的视为具有教师资格，仅笔试合格的不视为具有教师资格），提交教师资格考试合格证明网上查询截图打印件；C.提供校级教务部门开具的师范生免试认定证明视同具有教师资格，证明中明确教师资格学段、学科，提交师范生免试认定证明原件、复印件。</p><p style="text-indent: 2em;">（5）报考人员根据自身情况提供以下材料：</p><p style="text-indent: 2em;">①2024年应届毕业生提供：A.校级就业主管部门盖章的普通高校毕业生就业推荐表原件、复印件，培养方式为非定向。就业推荐表须明确标注毕业生的培养方式、专业、学历、学制和毕业时间等。如有未明确标注相关事项的，需同时提供毕业学校校级就业指导部门出具并盖章的证明函原件、复印件。B.校级教务主管部门盖章的已修全部课程成绩单原件、复印件；</p><p style="text-indent: 2em;">②两年内离校未就业的毕业生提供：A.最高学历毕业证及学位证原件、复印件（学历要求是国家教育行政部门承认的且可在教育部学信就业网查询到的学历）；B.档案存放机构开具的存档证明原件（加盖存档单位公章）、复印件；C.承诺书原件（要求手写，写明“承诺书 &nbsp;姓名XX，身份证号XX，2022年或2023年离校至今无社保缴纳记录。承诺人姓名，日期”）。</p><p style="text-indent: 2em;">（二）笔试&nbsp;</p><p style="text-indent: 2em;">笔试由区教委统一命题、组织，具体安排详见北京市昌平区政府网笔试通知。笔试采取百分制，合格分数线为60分，主要考察内容为基本能力水平以及教育学、教育心理学等相关知识。笔试成绩将于考试结束7个工作日内在北京市昌平区政府网公布。</p><p style="text-indent: 2em;">笔试成绩不合格的不得列入资格复审人选。笔试成绩由高分到低分的顺序依次排列，按岗位招聘人数1:5的比例确定资格复审人选，不足1:5的岗位按实际人数确定。&nbsp;</p><p style="text-indent: 2em;">本次招考无指定培训机构和参考用书，不举办也不委托任何机构举办考试辅导培训班。</p><p style="text-indent: 2em;">（三）资格复审</p><p style="text-indent: 2em;">区教委组织各单位对考生进行资格复审，复审通过后方可参加面试。</p><p style="text-indent: 2em;">（四）面试</p><p style="text-indent: 2em;">由区教委统一组织安排，具体时间和要求另行通知，逾期不参加面试者视为自动放弃。面试成绩实行百分制，合格分数线为60分。</p><p style="text-indent: 2em;">招聘单位根据笔试和面试权重比例，确定考生总成绩，考生的总成绩计算方法为：笔试成绩占30％，面试成绩占70％。总成绩在面试结束后10个工作日内在昌平政府网公示。招聘单位根据总成绩由高到低按招聘岗位数1:1的比例确定考察和体检人选。</p><p style="text-indent: 2em;">（五）考察与体检</p><p style="text-indent: 2em;">1.中小学教师体检标准参照北京市教师资格认定体检标准执行（见教师资格证网中指定医院）。</p><p style="text-indent: 2em;">2.招聘单位负责对拟聘用人选综合考察。</p><p style="text-indent: 2em;">3.招聘单位根据总成绩和体检、考察情况确定公示人员名单。　</p><p style="text-indent: 2em;">（六）公示</p><p style="text-indent: 2em;">拟聘用人员名单在北京市昌平区政府网公布，公示时间为7个工作日，公示前如出现考生个人放弃或资格复查、考察、体检不通过等情况，根据本岗位总成绩由高到低排序依次进行递补。公示一经开始，不再递补。</p><p style="text-indent: 2em;">（七）办理聘用手续</p><p style="text-indent: 2em;">1.公示期满后，报名人员须按照各招聘单位指定时间到招聘单位报到，并服从单位管理，招聘单位对公示无异议的拟聘用人员按照事业单位新招聘人员的有关规定办理入职手续，未报到者和不服从管理者，招聘单位有权终止办理相关手续，后果由报名人员自负。聘用人员上岗后，签订事业单位聘用合同年限一般不低于6年。试用（见习）期满经考核合格者，继续聘用；不合格者，解除聘用合同，档案转入人力资源公共服务机构。非北京生源毕业生通过进京审批的，三年后办理相关落户；未通过进京审批的，取消聘用资格。&nbsp;</p><p style="text-indent: 2em;">2.资格审查贯穿公开招聘工作全过程。在招聘过程中对申报材料故意隐瞒，弄虚作假的一经发现证实，取消资格，已办理聘用手续者取消聘用，由报名人员承担由此产生的一切后果。</p><p style="text-indent: 2em;">3.出现下列情况之一的，直接取消聘用资格：</p><p style="text-indent: 2em;">（1）体检或者考察不符合要求的；</p><p style="text-indent: 2em;">（2）拟聘人选公示结果影响聘用的；</p><p style="text-indent: 2em;">（3）拟聘人选放弃聘用的；</p><p style="text-indent: 2em;">（4）未在规定时限内报到的;</p><p style="text-indent: 2em;">（5）不能按时取得毕业证、学位证；</p><p style="text-indent: 2em;">（6）提供虚假材料的；</p><p style="text-indent: 2em;">（7）导致拟聘职位空缺的其他情形。</p><p style="text-indent: 2em;">五、注意事项</p><p style="text-indent: 2em;">（一）报名人员应保证通讯工具畅通，因通讯不畅导致相关后果由考生本人负责。报名人员应自行及时上网查阅各项公告公示事宜，因考生自身原因未能参加下一步招聘程序的后果由报名人员承担；</p><p style="text-indent: 2em;">（二）报名人员上交材料不予退还；</p><p style="text-indent: 2em;">（三）报名资料不全者不受理报名；</p><p style="text-indent: 2em;">（四）入职人员须服从教委岗位调剂，否则视为放弃；</p><p style="text-indent: 2em;">（五）正在受党纪、政纪处分或接受纪律审查的人员，以及刑事处罚期限未满或涉嫌违法犯罪正在接受调查的人员不得参加应聘；</p><p style="text-indent: 2em;">（六）招聘相关信息在北京市昌平区政府网公布。</p><p style="text-indent: 2em;">六、纪律要求</p><p style="text-indent: 2em;">（一）工作人员凡与报名人员有夫妻关系、直系血亲关系、三代以内旁系血亲或者近姻亲关系的，要实行回避制度。</p><p style="text-indent: 2em;">（二）纪检工作人员全程参与，对公开招聘工作进行监督。</p><p style="text-indent: 2em;">联系人：徐老师 李老师</p><p style="text-indent: 2em;">咨询监督电话：010-69742366 &nbsp;</p><p style="text-indent: 2em;">咨 询 时 间：工作日上午9:00-11:00 ；下午2:00-5:00</p><p style="text-indent: 2em;">北京市昌平区政府网站网址：http://www.bjchp.gov.cn/cpqzf/xxgk2671/rsgz/gzgg/index.html</p><p style="text-indent: 2em;">附件：</p><p style="text-indent: 2em;">1.昌平区教委所属中小学面向2024年应届毕业生公开招聘教师岗位和资格条件</p><p style="text-indent: 2em;">2.昌平区事业单位公开招聘工作人员报名表</p><p style="text-indent: 2em; text-align: center;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 北京市昌平区教育委员会</p><p style="text-indent: 2em; text-align: center;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2023年12月12日</p></div>','根据《事业单位公开招聘人员暂行规定》（人事部令第6号）及《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号），结合用人单位工作需要，昌平区教委所属中小学现面向2024年应届毕业生公开招聘教师。现就有关事项公告如下：一、招聘岗位及数量本次共招聘专技岗位教师133人。岗位及资格条件详见《昌平区教委所属中小学面向2024年应届毕业生公开招聘教师岗位和资格条件》（附件1）。二、招聘对象招聘岗位限列入国家统一招生计划（不含定向、委培），本科及以上学历且能如期取得相应学历、学位证书的普通高等院校2024年应届毕业生。注：两年内离校未就业的毕业生可报考2024年应届毕业生岗位。两年内离校未就业的毕业生指列入国家统一招生计划，培养方式为非定向（不含定向、委培），离校时和在国家规定的择业期内未落实工作单位，其户口、人事档案、组织关系仍保留在原毕业学校，或保留在各级毕业生就业主管部门（毕业生就业指导服务中心）、各级人才交流服务机构和各级公共就业服务机构，且择业期内未缴纳社会保险的2022年和2023年毕业生。三、招聘条件（一）基本要求：具有中华人民共和国国籍；拥护中国共产党的领导，遵守宪法和法律，具有良好的品行；热爱教育事业，具有岗位需要的专业和技能；符合岗位要求的身体条件；符合岗位所规定的其他条件；（二）年龄要求：本科毕业生25周岁及以下（1999年1月1日及以后出生）；硕士毕业生30周岁及以下（1994年1月1日及以后出生）；博士毕业生35周岁及以下（1989年1月1日及以后出生）；（三）户口要求：北京生源须具有北京市常住户口（不含户口及档案寄存在毕业学校的非北京生源毕业生）；非北京生源毕业生需符合进京审批条件，就读最高学历期间无社保缴纳记录；（四）专业要求：最高学历所学专业须与所报岗位学科要求的专业相符（专业要求参照教育部专业目录执行)；（五）教师资格要求：须具有招聘岗位所需级别和学科的教师资格（已取得“教师资格证书”或“有效期内的中小学教师资格考试合格证明”或“校级教务部门开具的师范生证明”）。相同学科的普通中、小学教师资格，高级别的适用于低级别，例如：持有高级中学数学教师资格人员，可申报高中数学教师岗位，也可申报初中或小学数学教师岗位；（六）学历及学位要求：2024年7月1日前须取得本科及以上学历及相应学位；（七）其他要求：同时须符合招聘岗位要求的其他条件。四、招聘程序（一）报名和资格初审1.报名时间：2023年12月22日—12月23日，上午8:30—11:00；下午14:00—16:30。2.报名地点：详见附件1中的联系信息栏。3.报名及资格初审：必须本人现场报名，各招聘单位当场进行资格初审。4.在本次招聘提供的133个岗位中，每位报名人员仅限报考一个岗位，重复报名者将取消本次招聘所有聘用资格。请报考人员切勿选报多个岗位。5.报名须持材料（请按以下顺序排列）：（1）《昌平区事业单位公开招聘工作人员报名表》（附件2）原件，请粘贴近期二寸彩色免冠正面照片，其中本人签字处须手签姓名；（2）身份证原件、复印件；（3）户口簿原件、户口簿首页和本人页复印件；户口在集体户的须提交集体户首页复印件（须加盖户籍管理部门公章）、本人页原件及本人页复印件，或集体户户籍管理部门出具并盖章的户口证明原件（写明“姓名、身份证号、其户籍在XX集体户”即可）、复印件；（4）教师资格方面，提供下列材料之一：A.已取得教师资格证书的提交教师资格证书原件、复印件；B.取得有效期内“中小学教师资格考试合格证明”的（有效期内教师资格笔试及面试各科考试均合格的视为具有教师资格，仅笔试合格的不视为具有教师资格），提交教师资格考试合格证明网上查询截图打印件；C.提供校级教务部门开具的师范生免试认定证明视同具有教师资格，证明中明确教师资格学段、学科，提交师范生免试认定证明原件、复印件。（5）报考人员根据自身情况提供以下材料：①2024年应届毕业生提供：A.校级就业主管部门盖章的普通高校毕业生就业推荐表原件、复印件，培养方式为非定向。就业推荐表须明确标注毕业生的培养方式、专业、学历、学制和毕业时间等。如有未明确标注相关事项的，需同时提供毕业学校校级就业指导部门出具并盖章的证明函原件、复印件。B.校级教务主管部门盖章的已修全部课程成绩单原件、复印件；②两年内离校未就业的毕业生提供：A.最高学历毕业证及学位证原件、复印件（学历要求是国家教育行政部门承认的且可在教育部学信就业网查询到的学历）；B.档案存放机构开具的存档证明原件（加盖存档单位公章）、复印件；C.承诺书原件（要求手写，写明“承诺书  姓名XX，身份证号XX，2022年或2023年离校至今无社保缴纳记录。承诺人姓名，日期”）。（二）笔试 笔试由区教委统一命题、组织，具体安排详见北京市昌平区政府网笔试通知。笔试采取百分制，合格分数线为60分，主要考察内容为基本能力水平以及教育学、教育心理学等相关知识。笔试成绩将于考试结束7个工作日内在北京市昌平区政府网公布。笔试成绩不合格的不得列入资格复审人选。笔试成绩由高分到低分的顺序依次排列，按岗位招聘人数1:5的比例确定资格复审人选，不足1:5的岗位按实际人数确定。 本次招考无指定培训机构和参考用书，不举办也不委托任何机构举办考试辅导培训班。（三）资格复审区教委组织各单位对考生进行资格复审，复审通过后方可参加面试。（四）面试由区教委统一组织安排，具体时间和要求另行通知，逾期不参加面试者视为自动放弃。面试成绩实行百分制，合格分数线为60分。招聘单位根据笔试和面试权重比例，确定考生总成绩，考生的总成绩计算方法为：笔试成绩占30％，面试成绩占70％。总成绩在面试结束后10个工作日内在昌平政府网公示。招聘单位根据总成绩由高到低按招聘岗位数1:1的比例确定考察和体检人选。（五）考察与体检1.中小学教师体检标准参照北京市教师资格认定体检标准执行（见教师资格证网中指定医院）。2.招聘单位负责对拟聘用人选综合考察。3.招聘单位根据总成绩和体检、考察情况确定公示人员名单。　（六）公示拟聘用人员名单在北京市昌平区政府网公布，公示时间为7个工作日，公示前如出现考生个人放弃或资格复查、考察、体检不通过等情况，根据本岗位总成绩由高到低排序依次进行递补。公示一经开始，不再递补。（七）办理聘用手续1.公示期满后，报名人员须按照各招聘单位指定时间到招聘单位报到，并服从单位管理，招聘单位对公示无异议的拟聘用人员按照事业单位新招聘人员的有关规定办理入职手续，未报到者和不服从管理者，招聘单位有权终止办理相关手续，后果由报名人员自负。聘用人员上岗后，签订事业单位聘用合同年限一般不低于6年。试用（见习）期满经考核合格者，继续聘用；不合格者，解除聘用合同，档案转入人力资源公共服务机构。非北京生源毕业生通过进京审批的，三年后办理相关落户；未通过进京审批的，取消聘用资格。 2.资格审查贯穿公开招聘工作全过程。在招聘过程中对申报材料故意隐瞒，弄虚作假的一经发现证实，取消资格，已办理聘用手续者取消聘用，由报名人员承担由此产生的一切后果。3.出现下列情况之一的，直接取消聘用资格：（1）体检或者考察不符合要求的；（2）拟聘人选公示结果影响聘用的；（3）拟聘人选放弃聘用的；（4）未在规定时限内报到的;（5）不能按时取得毕业证、学位证；（6）提供虚假材料的；（7）导致拟聘职位空缺的其他情形。五、注意事项（一）报名人员应保证通讯工具畅通，因通讯不畅导致相关后果由考生本人负责。报名人员应自行及时上网查阅各项公告公示事宜，因考生自身原因未能参加下一步招聘程序的后果由报名人员承担；（二）报名人员上交材料不予退还；（三）报名资料不全者不受理报名；（四）入职人员须服从教委岗位调剂，否则视为放弃；（五）正在受党纪、政纪处分或接受纪律审查的人员，以及刑事处罚期限未满或涉嫌违法犯罪正在接受调查的人员不得参加应聘；（六）招聘相关信息在北京市昌平区政府网公布。六、纪律要求（一）工作人员凡与报名人员有夫妻关系、直系血亲关系、三代以内旁系血亲或者近姻亲关系的，要实行回避制度。（二）纪检工作人员全程参与，对公开招聘工作进行监督。联系人：徐老师 李老师咨询监督电话：010-69742366  咨 询 时 间：工作日上午9:00-11:00 ；下午2:00-5:00北京市昌平区政府网站网址：http://www.bjchp.gov.cn/cpqzf/xxgk2671/rsgz/gzgg/index.html附件：1.昌平区教委所属中小学面向2024年应届毕业生公开招聘教师岗位和资格条件2.昌平区事业单位公开招聘工作人员报名表                                                                                                                        北京市昌平区教育委员会                                                                                                                          2023年12月12日',NULL,'事业单位;公开招聘',NULL,'北京市昌平区教育委员会',NULL,'2023-12-12 14:35:00',NULL,'2024-03-06 21:14:23',6,'北京市人力资源和社会保障局',39157,'https://rsj.beijing.gov.cn/xxgk/gkzp/202312/t20231212_3496697.html',10),	 (951175,'北京市科学技术委员会直属事业单位2019年公开招聘工作人员公告','北京市科学技术委员会直属事业单位2019年公开招聘工作人员公告','<div class="view TRS_UEDITOR trs_paper_default trs_external trs_key4format"><div><div><div><p style="text-indent: 2em;">根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）和我委直属事业单位工作需要， 13家单位共招聘49名工作人员。拟面向2019年非京生源应届毕业生公开招聘13名，面向退役大学生士兵公开招聘4名，面向北京生源应届毕业生及留学生招聘10名，面向社会在职人员招聘22名。现将有关事项公告如下：</p><p style="text-indent: 2em;">一、招聘单位及岗位</p><p style="text-indent: 2em;">北京生物技术和新医药产业促进中心、北京新材料发展中心等13家单位面向非京生源应届毕业生、退役大学生士兵、北京生源应届毕业生及留学生设置17个岗位，共招聘27名工作人员；面向社会在职人员设置12个岗位，共招聘22名工作人员。岗位及要求详见《北京市科学技术委员会直属事业单位面向2019年应届毕业生公开招聘工作人员岗位计划表》（附件1）、《北京市科学技术委员会直属事业单位面向社会在职人员招聘工作人员岗位计划表》（附件2）；招聘单位基本信息详见市科委网站直属机构介绍（http://kw.beijing.gov.cn/col/col24/index.html）。</p><p style="text-indent: 2em;">二、招聘条件</p><p style="text-indent: 2em;">（一）拥护中国共产党的领导，热爱社会主义祖国；遵守宪法和法律，品行端正，具有良好的职业道德，愿意履行事业单位工作人员义务。</p><p style="text-indent: 2em;">（二）符合招聘岗位所要求的国家承认的全日制学历、专业和资格等条件；身体健康，适应岗位要求。</p><p style="text-indent: 2em;">（三）应届毕业生为列入国家统一招生计划（不含定向、委培）能够正常参加2019年就业派遣的统招统分普通高校应届毕业生。</p><p style="text-indent: 2em;">（四）退役大学生士兵为按照国家普通高等学校招生计划统一录取的全日制普通高等教育的学生，在校期间从本市入伍且服役期满退役后复学完成学业的2019年应届毕业生;或高等教育应届毕业当年从本市入伍且2018年退出现役的服役期满退役士兵。</p><p style="text-indent: 2em;">（五）留学生为2018年8月1日至2019年7月31日期间取得国（境）外学位并完成教育部门学历认证的留学回国人员。</p><p style="text-indent: 2em;">（六）社会在职工作人员须具有北京市常住户口；符合岗位要求的工作年限、工作经历、从业资格等条件，不在原单位试用期内。</p><p style="text-indent: 2em;">（七）报考人员对招聘的专业、学历、学位、资格条件等信息需要咨询时，可直接联系招聘单位，联系方式详见附件岗位表。</p><p style="text-indent: 2em;">（八）非北京生源应届毕业生及海外留学生需符合进京条件及落户政策要求。</p><p style="text-indent: 2em;">（九）报名人员应当遵守以下回避制度：凡与招聘单位负责人及负责招聘工作的相关人员有夫妻关系、直系血亲关系、三代以内旁系血亲关系或者近姻亲关系的应聘人员，不得应聘该单位人事、财务岗位，以及与单位负责人有直接上下级关系的岗位。</p><p style="text-indent: 2em;">三、报名与资格审查</p><p style="text-indent: 2em;">报考人员可于公告发布之日起至6月20日17:00前登录北京市人力资源与社会保障局网站、北京市科学技术委员会网站（http://kw.beijing.gov.cn/），查看相关通知，下载报名表(附件3)，填写完整后，按照各招聘岗位指定的邮箱提交报名表，同时抄送市科委人事处邮箱rsc@kw.beijing.gov.cn。报名表文件名和邮件标题请注明：报考单位+岗位+姓名。各单位初审后电话通知合格人员携带相关材料参加现场资格复审，现场资格审查时间和地点由招聘单位提前通知。</p><p style="text-indent: 2em;">报考者须如实提交有关信息和材料，凡弄虚作假的，一经查实，即取消考试资格或聘用资格。</p><p style="text-indent: 2em;">四、资格审查需提交的材料</p><p style="text-indent: 2em;">（一）报名表（请考生自行下载打印，见附件3），粘贴照片并在“诚信承诺”处用黑色字迹签字笔签名；</p><p style="text-indent: 2em;">（二）身份证原件和复印件（正反面）；</p><p style="text-indent: 2em;">（三）学历、学位证书原件和复印件（尚未取得学历、学位证书的需提供能够按时取得的相关证明）；《毕业生就业推荐表》原件及复印件，须毕业院校校级就业主管部门盖章；《成绩单》原件及复印件，须毕业院校教务部门盖章；大学英语等级证书原件及复印件。</p><p style="text-indent: 2em;">（四）留学归国人员还须提供经教育部留学人员服务中心出具的《国外学历学位认证书》及学历学位证书。</p><p style="text-indent: 2em;">（五）退役大学生士兵还须提供服役相关证件。</p><p style="text-indent: 2em;">（六）个人简历及能够证明符合招聘岗位所要求条件的其他证书或证明材料的原件和复印件。</p><p style="text-indent: 2em;">上述材料复印件均需一份，使用A4纸，并按照上述顺序装订整齐。</p><p style="text-indent: 2em;">五、考试</p><p style="text-indent: 2em;">资格审查通过者领取准考证，参加笔试。</p><p style="text-indent: 2em;">（一）笔试</p><p style="text-indent: 2em;">笔试时间和地点以准考证为准。笔试请考生携带准考证、身份证。</p><p style="text-indent: 2em;">笔试以百分制计算，合格线60分，笔试成绩低于合格线者不能进入面试。按照招聘人数与进入面试人数比例（详见附件），从高分到低分依次确定面试人选；若未达到比例，招聘单位组织成绩合格报名人员进行下一步考试。考生可登陆北京市科学技术委员会网站查看成绩公告。</p><p style="text-indent: 2em;">（二）面试</p><p style="text-indent: 2em;">面试具体时间、地点、考试方式另行通知。进入面试考生低于对应比例的职位，报考人员面试成绩应达到所在面试考官组使用同一套面试题面试的所有人员的平均分，否则不计入总成绩。面试成绩将与总成绩一并在北京市科学技术委员会网站公布。</p><p style="text-indent: 2em;">（三）岗位能力测试</p><p style="text-indent: 2em;">招聘岗位仅组织面试的，岗位能力测试成绩等于面试成绩；招聘岗位同时组织面试和专业技能考试的，岗位能力测试成绩=“面试成绩×50%+专业技能考试成绩×50%”。面试、专业技能考试成绩均按百分制折算，考试成绩合格线均为60分。岗位能力测试合格者方可进入下一环节。综合成绩＝笔试成绩×50%＋岗位能力测试成绩×50%。</p><p style="text-indent: 2em;">六、确定拟聘人选</p><p style="text-indent: 2em;">各招聘单位根据考试、考察和体检情况，择优确定拟聘用人员，考生均未达到聘用要求的本次招聘岗位取消。因考生个人原因不能按时完成体检的，视为本人自动放弃。拟聘人选名单在北京市科学技术委员会网站及招聘单位网站公示7个工作日。</p><p style="text-indent: 2em;">七、其他事项</p><p style="text-indent: 2em;">1.从资格审核到体检考察结束，考生应保证通讯畅通，因通讯不畅造成无法通知考生本人的，后果由考生本人负责。</p><p style="text-indent: 2em;">2. 招聘条件中的年龄及工作年限时间截止到2019年9月30日。</p><p style="text-indent: 2em;">3. 本次招聘工作，在市科委人事处的指导下，由各招聘单位人事部门组织实施，招聘过程中，遇招聘单位机构调整的按照调整后的机构定岗。</p><p style="text-indent: 2em;">4.招聘过程中如有任何违法违纪行为或影响招聘结果公正性的情形，考生可据实向相关主管部门反映情况。</p><p style="text-indent: 2em;">监督电话：010-55577865。</p><p style="text-indent: 2em;">特此公告。</p><p style="text-indent: 2em;">附件：</p><p style="text-indent: 2em;">1.北京市科学技术委员会直属事业单位面向2019年应届毕业生公开招聘工作人员岗位计划表</p><p style="text-indent: 2em;">2.北京市科学技术委员会直属事业单位面向社会在职人员招聘工作人员岗位计划表</p><p style="text-indent: 2em;">3.北京市科学技术委员会直属事业单位公开招聘工作人员报名表</p><p style="text-align: right; text-indent: 0em;">北京市科学技术委员会</p><p style="text-align: right;">2019年6月10日</p></div></div></div></div>','根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）和我委直属事业单位工作需要， 13家单位共招聘49名工作人员。拟面向2019年非京生源应届毕业生公开招聘13名，面向退役大学生士兵公开招聘4名，面向北京生源应届毕业生及留学生招聘10名，面向社会在职人员招聘22名。现将有关事项公告如下：一、招聘单位及岗位北京生物技术和新医药产业促进中心、北京新材料发展中心等13家单位面向非京生源应届毕业生、退役大学生士兵、北京生源应届毕业生及留学生设置17个岗位，共招聘27名工作人员；面向社会在职人员设置12个岗位，共招聘22名工作人员。岗位及要求详见《北京市科学技术委员会直属事业单位面向2019年应届毕业生公开招聘工作人员岗位计划表》（附件1）、《北京市科学技术委员会直属事业单位面向社会在职人员招聘工作人员岗位计划表》（附件2）；招聘单位基本信息详见市科委网站直属机构介绍（http://kw.beijing.gov.cn/col/col24/index.html）。二、招聘条件（一）拥护中国共产党的领导，热爱社会主义祖国；遵守宪法和法律，品行端正，具有良好的职业道德，愿意履行事业单位工作人员义务。（二）符合招聘岗位所要求的国家承认的全日制学历、专业和资格等条件；身体健康，适应岗位要求。（三）应届毕业生为列入国家统一招生计划（不含定向、委培）能够正常参加2019年就业派遣的统招统分普通高校应届毕业生。（四）退役大学生士兵为按照国家普通高等学校招生计划统一录取的全日制普通高等教育的学生，在校期间从本市入伍且服役期满退役后复学完成学业的2019年应届毕业生;或高等教育应届毕业当年从本市入伍且2018年退出现役的服役期满退役士兵。（五）留学生为2018年8月1日至2019年7月31日期间取得国（境）外学位并完成教育部门学历认证的留学回国人员。（六）社会在职工作人员须具有北京市常住户口；符合岗位要求的工作年限、工作经历、从业资格等条件，不在原单位试用期内。（七）报考人员对招聘的专业、学历、学位、资格条件等信息需要咨询时，可直接联系招聘单位，联系方式详见附件岗位表。（八）非北京生源应届毕业生及海外留学生需符合进京条件及落户政策要求。（九）报名人员应当遵守以下回避制度：凡与招聘单位负责人及负责招聘工作的相关人员有夫妻关系、直系血亲关系、三代以内旁系血亲关系或者近姻亲关系的应聘人员，不得应聘该单位人事、财务岗位，以及与单位负责人有直接上下级关系的岗位。三、报名与资格审查报考人员可于公告发布之日起至6月20日17:00前登录北京市人力资源与社会保障局网站、北京市科学技术委员会网站（http://kw.beijing.gov.cn/），查看相关通知，下载报名表(附件3)，填写完整后，按照各招聘岗位指定的邮箱提交报名表，同时抄送市科委人事处邮箱rsc@kw.beijing.gov.cn。报名表文件名和邮件标题请注明：报考单位+岗位+姓名。各单位初审后电话通知合格人员携带相关材料参加现场资格复审，现场资格审查时间和地点由招聘单位提前通知。报考者须如实提交有关信息和材料，凡弄虚作假的，一经查实，即取消考试资格或聘用资格。四、资格审查需提交的材料（一）报名表（请考生自行下载打印，见附件3），粘贴照片并在“诚信承诺”处用黑色字迹签字笔签名；（二）身份证原件和复印件（正反面）；（三）学历、学位证书原件和复印件（尚未取得学历、学位证书的需提供能够按时取得的相关证明）；《毕业生就业推荐表》原件及复印件，须毕业院校校级就业主管部门盖章；《成绩单》原件及复印件，须毕业院校教务部门盖章；大学英语等级证书原件及复印件。（四）留学归国人员还须提供经教育部留学人员服务中心出具的《国外学历学位认证书》及学历学位证书。（五）退役大学生士兵还须提供服役相关证件。（六）个人简历及能够证明符合招聘岗位所要求条件的其他证书或证明材料的原件和复印件。上述材料复印件均需一份，使用A4纸，并按照上述顺序装订整齐。五、考试资格审查通过者领取准考证，参加笔试。（一）笔试笔试时间和地点以准考证为准。笔试请考生携带准考证、身份证。笔试以百分制计算，合格线60分，笔试成绩低于合格线者不能进入面试。按照招聘人数与进入面试人数比例（详见附件），从高分到低分依次确定面试人选；若未达到比例，招聘单位组织成绩合格报名人员进行下一步考试。考生可登陆北京市科学技术委员会网站查看成绩公告。（二）面试面试具体时间、地点、考试方式另行通知。进入面试考生低于对应比例的职位，报考人员面试成绩应达到所在面试考官组使用同一套面试题面试的所有人员的平均分，否则不计入总成绩。面试成绩将与总成绩一并在北京市科学技术委员会网站公布。（三）岗位能力测试招聘岗位仅组织面试的，岗位能力测试成绩等于面试成绩；招聘岗位同时组织面试和专业技能考试的，岗位能力测试成绩=“面试成绩×50%+专业技能考试成绩×50%”。面试、专业技能考试成绩均按百分制折算，考试成绩合格线均为60分。岗位能力测试合格者方可进入下一环节。综合成绩＝笔试成绩×50%＋岗位能力测试成绩×50%。六、确定拟聘人选各招聘单位根据考试、考察和体检情况，择优确定拟聘用人员，考生均未达到聘用要求的本次招聘岗位取消。因考生个人原因不能按时完成体检的，视为本人自动放弃。拟聘人选名单在北京市科学技术委员会网站及招聘单位网站公示7个工作日。七、其他事项1.从资格审核到体检考察结束，考生应保证通讯畅通，因通讯不畅造成无法通知考生本人的，后果由考生本人负责。2. 招聘条件中的年龄及工作年限时间截止到2019年9月30日。3. 本次招聘工作，在市科委人事处的指导下，由各招聘单位人事部门组织实施，招聘过程中，遇招聘单位机构调整的按照调整后的机构定岗。4.招聘过程中如有任何违法违纪行为或影响招聘结果公正性的情形，考生可据实向相关主管部门反映情况。监督电话：010-55577865。特此公告。附件：1.北京市科学技术委员会直属事业单位面向2019年应届毕业生公开招聘工作人员岗位计划表2.北京市科学技术委员会直属事业单位面向社会在职人员招聘工作人员岗位计划表3.北京市科学技术委员会直属事业单位公开招聘工作人员报名表北京市科学技术委员会2019年6月10日',NULL,'岗位;事业单位;毕业生;考生;资格;社会在职人员;大学生士兵;面试成绩;生源;计划表','根据《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）和我委直属事业单位工作需要， 13家单位共招聘49名工作人员。现将有关事项公告如下：一、招聘单位及岗位北京生物技术和新医药产业促进中心、北京新材料发展中心等13家单位面向非京生源应届毕业生、退役大学生士兵、北京生源应届毕业生及留学生设置17个岗位，共招聘27名工作人员。岗位及要求详见《北京市科学技术委员会直属事业单位面向2019年应届毕业生公开招聘工作人员岗位计划表》（附件。岗位能力测试招聘岗位仅组织面试的,岗位能力测试成绩等于面试成绩。','北京市科学技术委员会','北京市人力资源和社会保障局','2019-06-10 09:20:00',NULL,'2025-03-24 19:15:25',6,'北京市人力资源和社会保障局',39157,'https://rsj.beijing.gov.cn/wx/xxgk/ywdt/201912/t20191207_951175.html',10),	 (4035609,'中共北京市委第八巡视组关于对北京市人民政府国有资产监督管理委员会党委开展巡视“回头看”的通告','中共北京市委第八巡视组关于对北京市人民政府国有资产监督管理委员会党委开展巡视“回头看”的通告',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-03-17 09:17:00','https://mp.weixin.qq.com/s/oYGt71sErrqhms3k8tLqVg','2025-03-17 09:18:06',12,'北京市人民政府国有资产监督管理委员会',937,'https://mp.weixin.qq.com/s/oYGt71sErrqhms3k8tLqVg',10),	 (951176,'北京市大兴区2019年第一批部分事业单位公开招聘工作人员公告','北京市大兴区2019年第一批部分事业单位公开招聘工作人员公告','<div class=TRS_Editor><div class="Custom_UnionStyle"><div><div>　　为进一步加强大兴区事业单位干部队伍建设，按照《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）等文件精神，结合大兴区各事业单位实际用人需求，现面向社会公开招聘工作人员，有关事项公告如下：</div><p>　　一、招聘条件</p><p>　　（一）拥护中国共产党的领导，遵守宪法和法律，具有良好的品行。</p><p>　　（二）身心健康，具有良好的职业道德和符合岗位要求的身体条件。</p><p>　　（三）北京市常住户口且人事行政关系、人事档案在京；非北京市常住户口仅限2019年应届毕业生报考，且须同时符合非北京生源毕业生引进条件和岗位要求条件。</p><p>　　（四）具备岗位要求的（国家承认）学历、专业等条件。具体岗位要求条件详见附件。</p><p>　　（五）符合回避制度的有关规定。</p><p>　　（六）岗位条件说明事项：</p><p>　　1.要求年龄在35周岁及以下，即1983年6月10日及以后出生；30周岁及以下，即1988年6月10日及以后出生。</p><p>　　2.要求工作经历的岗位，不包括户口、档案保留在学校的非北京生源往届毕业生。</p><p>　　3.符合相关岗位条件的2019年应届毕业生，限于列入国家统一招生计划（不含定向、委培）的全日制普通高等院校的2019年应届毕业生。</p><p>　　4.工作经历年限计算时间截止到2019年6月30日。</p><p>　　5.按照相关要求，报考户口“不限”岗位的非北京市常住户口2019年应届毕业生，须为硕士研究生及以上学历。其中，硕士研究生须为1992年1月1日及以后出生，博士研究生须为1984年1月1日及以后出生，凡非北京生源应届毕业生报考，须同时符合非北京生源毕业生引进条件和岗位要求条件。</p><p>　　二、报名方法</p><p>　　本次报名采取网上报名、网上初审、现场确认的方式。</p><p>　　（一）网上报名。考生可于2019年6月17日上午9:00至2019年6月18日下午16:30，登录“大兴区人事考试报名系统”（http://rsks.daxing.net/hr/clogin.htm)提交报考申请，每人限报一个岗位。首次使用报名系统的考生，须先“注册新用户”。未通过网上报名的人员，不得进入后续招聘环节。</p><p>　　（二）网上初审。考生在提交报名信息后，招聘单位将进行初审。考生须随时关注报名系统中初审结果。初审通过的考生登录报名系统打印《北京市大兴区事业单位公开招聘报名表》，仔细阅读“诚信声明”后在相应位置签字。</p><p>　　（三）现场确认。初审通过的考生于2019年6月19日至2019年6月20日（共2天）上午9:00-11:30，下午13:30-16:30，本人持《报名表》及相关附件材料进行现场确认。现场确认地点详见附件（岗位一览表）。</p><p>　　现场确认需提交的材料：</p><p>　　1.报名表（从报名系统打印并经本人签字）；</p><p>　　2.身份证原件及复印件；</p><p>　　3.户口簿原件及首页、本人页复印件；</p><p>　　4.学历证书原件及复印件，要求具备相应学位的需提供相应学位证书原件及复印件；还未取得学历证书及学位证书的2019年应届毕业生，需提供就业推荐表(就业指导中心盖章)、成绩单（教务处盖章）的原件及复印件；</p><p>　　5.招聘岗位要求具有工作经历和年限的，须提供能够证明工作经历和年限的相关证明；</p><p>　　6.人事档案存放单位的存档证明或相关证明材料；</p><p>　　7.能够证明符合招聘岗位所要求条件的其他证书原件及复印件或证明材料原件。</p><p>　　（四）打印准考证。现场确认通过的考生，于2019年6月22日9:00至笔试当天9:30期间登录报名系统打印准考证（用于参加笔试及成绩查询）。</p><p>　　三、笔试事项</p><p>　　（一）笔试内容：行政综合能力测试，考试不指定辅导用书。</p><p>　　（二）时间、地点：以准考证为准。</p><p>　　（三）成绩查询：笔试成绩实行百分制，划定合格分数线为60分，考生可登录北京市大兴区人民政府网站（http://www.bjdx.gov.cn）查看成绩。每个岗位按照计划聘用人数与面试人选1:3的比例，从高分到低分排序依次确定面试人选。成绩低于合格分数线者不能进入面试。未达到规定比例的岗位，按成绩不低于合格分数线的实际人数参加面试。</p><p>　　（四）对进入面试的人选进行资格复审，复审内容包括考生年龄、学历、专业以及岗位要求的其他条件。资格复审通过的考生参加面试；未通过的不得参加面试，并按照本岗位笔试成绩由高到低依次递补人员进行复审。</p><p>　　四、面试事项</p><p>　　（一）面试由大兴区人力资源和社会保障局统一组织实施，具体时间、地点另行通知。</p><p>　　（二）面试成绩实行百分制，按照笔试、面试成绩各占50%的权重计算综合成绩，每个岗位按照1:1的比例，在面试成绩合格人员中，根据综合成绩从高分到低分排序确定进入体检、考察人选。</p><p>　　个别实际参加面试人数与聘用计划人数比例低于3:1的岗位，考生面试成绩应达到其所在面试考官小组使用同一套面试题本面试的所有人员的平均分，方可进入体检和考察。</p><p>　　五、体检、考察</p><p>　　由招聘单位统一组织体检、考察工作，具体时间另行通知。体检标准参照公务员录用有关体检标准执行。</p><p>　　六、确定拟聘用人选</p><p>　　根据笔试、面试、体检和考察结果，择优确定拟聘用人选。拟聘用人员名单在北京市大兴区人民政府网站（http://www.bjdx.gov.cn）公示7个工作日。公示无异议的按相关规定办理聘用手续。</p><p>　　七、需说明事项</p><p>　　（一）资格审核贯穿招聘始终，在报名、考试、复审等任何环节发现考生不符合报名条件，将取消招聘资格；在公开招聘过程中存在违纪违规行为的，将依据人社部《事业单位公开招聘违规违纪行为处理规定》严肃处理，并对考生的违纪违规、失信行为进行记录。</p><p>　　（二）从资格审核到招聘工作结束，考生应保证报名时所留电话号码通讯畅通，因通讯不畅造成无法通知考生本人的，后果由考生本人负责。</p><p>　　（三）公开招聘过程中，面试工作安排、考试成绩等相关信息均会通过网站进行公示，请考生务必随时关注北京市大兴区人民政府网站发布的相关公告，并按公告要求参加招聘。</p><p>　　（四）公开招聘岗位专业要求依据教育部《普通高等学校本科专业目录（2012年）》、《学位授予和人才培养学科目录（2018年）》设置。</p><p>　　注：更多岗位同步在北京市大兴区人民政府网站（http://www.bjdx.gov.cn）发布。</p><p>　　附件：</p><p>&nbsp;&nbsp;&nbsp; 1.大兴区2019年第一批部分事业单位公开招聘工作人员岗位一览表</p><p>　　2.普通高等学校本科专业目录（2012年）</p><p>　　3.学位授予和人才培养学科目录（2018年）</p><p align="right">　　北京市大兴区人力资源和社会保障局</p><p align="right">　　2019年6月10日&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p></div></div></div>','oracle.sql.CLOB@7b4c50bc',NULL,NULL,'<FONT color=#3366ff>[公告]</FONT>',NULL,NULL,'2019-06-10 09:10:00',NULL,'2025-03-25 12:00:05',6,'北京市人力资源和社会保障局',39157,'https://rsj.beijing.gov.cn/xxgk/gkzp/201912/t20191207_951176.html',10),	 (1668343,'战疫情、促增收，就业扶贫在发力',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><p style="text-indent: 2em;">日前，人力资源社会保障部、国务院扶贫办印发《关于应对新冠肺炎疫情进一步做好就业扶贫工作的通知》（以下简称《通知》），部署做好贫困劳动力返岗就业有关工作。</p><p style="text-indent: 2em;">《通知》要求，各地要把思想和行动切实统一到习近平总书记重要讲话精神和党中央决策部署上来，在确保疫情防控安全的前提下，切实做好就业扶贫工作，不能有缓一缓、等一等的思想，努力减轻疫情对贫困劳动力就业增收的影响，助力全面建成小康社会和打赢脱贫攻坚战。</p><p style="text-indent: 2em;">《通知》提出一系列促进贫困劳动力就业增收的政策举措。一是鼓励重点企业优先招录。梳理本地区重点企业用工需求，远程精准推送适合贫困劳动力的就业岗位，支持重点企业优先招用贫困劳动力。二是安全有序组织外出返岗务工。优先组织贫困劳动力实施“点对点”集中运送到岗，对公共就业服务机构、人力资源服务机构、劳务经纪人开展贫困劳动力有组织劳务输出的，给予就业创业服务补助。三是促进就地就近就业。推动疫情较轻地区的各类经营主体、工程项目尽早复工复产，推荐贫困劳动力优先上岗；鼓励临时增设的保洁环卫、防疫消杀、卡点值守等岗位优先吸纳贫困劳动力；鼓励参加春耕备耕等农业生产，支持各类农资经营主体吸纳贫困劳动力就业。四是加强关心关爱，及时解决困难问题，对受疫情影响失业的参保贫困劳动力按规定发放失业补助金。五是优化线上服务线上培训。帮助贫困劳动力掌握居家线上求职应聘操作流程，有条件的地区可在确保防疫安全前提下，组织不具备线上求职条件的贫困劳动力参加视频面试。鼓励支持贫困劳动力积极参加线上培训，在培训期间按规定给予职业培训补贴和生活费补贴。</p><p style="text-indent: 2em;">《通知》强调，将“三区三州”等深度贫困地区、易地扶贫搬迁安置点所在地区以及挂牌督战的52个贫困县作为工作重点，组织定向投放岗位，加大有组织劳务输出力度，适当扩大乡村公益性岗位规模。积极向当地疫情防控领导机构建言献策，加强部门协同，及时提供就业帮扶，创造有利于贫困劳动力就业增收的良好环境，防止因疫失业返贫。</p></div>','日前，人力资源社会保障部、国务院扶贫办印发《关于应对新冠肺炎疫情进一步做好就业扶贫工作的通知》（以下简称《通知》），部署做好贫困劳动力返岗就业有关工作。《通知》要求，各地要把思想和行动切实统一到习近平总书记重要讲话精神和党中央决策部署上来，在确保疫情防控安全的前提下，切实做好就业扶贫工作，不能有缓一缓、等一等的思想，努力减轻疫情对贫困劳动力就业增收的影响，助力全面建成小康社会和打赢脱贫攻坚战。《通知》提出一系列促进贫困劳动力就业增收的政策举措。一是鼓励重点企业优先招录。梳理本地区重点企业用工需求，远程精准推送适合贫困劳动力的就业岗位，支持重点企业优先招用贫困劳动力。二是安全有序组织外出返岗务工。优先组织贫困劳动力实施“点对点”集中运送到岗，对公共就业服务机构、人力资源服务机构、劳务经纪人开展贫困劳动力有组织劳务输出的，给予就业创业服务补助。三是促进就地就近就业。推动疫情较轻地区的各类经营主体、工程项目尽早复工复产，推荐贫困劳动力优先上岗；鼓励临时增设的保洁环卫、防疫消杀、卡点值守等岗位优先吸纳贫困劳动力；鼓励参加春耕备耕等农业生产，支持各类农资经营主体吸纳贫困劳动力就业。四是加强关心关爱，及时解决困难问题，对受疫情影响失业的参保贫困劳动力按规定发放失业补助金。五是优化线上服务线上培训。帮助贫困劳动力掌握居家线上求职应聘操作流程，有条件的地区可在确保防疫安全前提下，组织不具备线上求职条件的贫困劳动力参加视频面试。鼓励支持贫困劳动力积极参加线上培训，在培训期间按规定给予职业培训补贴和生活费补贴。《通知》强调，将“三区三州”等深度贫困地区、易地扶贫搬迁安置点所在地区以及挂牌督战的52个贫困县作为工作重点，组织定向投放岗位，加大有组织劳务输出力度，适当扩大乡村公益性岗位规模。积极向当地疫情防控领导机构建言献策，加强部门协同，及时提供就业帮扶，创造有利于贫困劳动力就业增收的良好环境，防止因疫失业返贫。',NULL,NULL,NULL,'人社部',NULL,'2020-02-25 11:38:00',NULL,'2023-08-28 07:57:49',6,'北京市人力资源和社会保障局',15299,'http://rsj.beijing.gov.cn/weimenhu/wmtgz/202002/t20200225_1668343.html',10),	 (871652,'市人力社保局近日发布2019年劳动人事争议仲裁十大典型案例','市人力社保局近日发布2019年劳动人事争议仲裁十大典型案例','<div class=TRS_Editor><div class="Custom_UnionStyle"><div style="overflow-x: hidden; word-break: break-all"><p align="left" style="text-align: left">　　<span>市人力社保局近日发布<span lang="EN-US">2019</span>年劳动人事争议仲裁十大典型案例。</span><span>案例涉及特殊工时工作制、竞业限制、劳动合同的履行、变更和解除、开具离职证明、经济补偿计算基数、解除聘用合同等较为常见的劳动人事争议。通过以案说法的形式宣传解读劳动争议案件，普及劳动法律知识。</span></p></div></div></div>','oracle.sql.CLOB@63a65a25',NULL,NULL,NULL,NULL,NULL,'2019-11-12 14:11:00',NULL,'2024-05-21 10:33:27',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/201912/t20191206_871652.html',10),	 (871651,'本市支持雄安劳动力就业培训项目“退役军人无人机应用技能培训班”近日举办','本市支持雄安劳动力就业培训项目“退役军人无人机应用技能培训班”近日举办','<div class=TRS_Editor><div class="Custom_UnionStyle"><div style="overflow-x: hidden; word-break: break-all">　　<p align="left" style="text-align: left">　　<span>本市支持雄安劳动力就业培训项目“退役军人无人机应用技能培训班”近日举办。</span><span>北京</span><span>市人力社保局主动对接雄安新区劳动力就业培训需求，组织我市新媒体技师学院<span lang="EN-US">12</span>名优秀教师携带无人机教学设备赴雄安授课。培训采用理论实操一体化教学模式，突出培训技能的针对性和实用性，内容包括无人机飞行知识、飞行原理、<span lang="EN-US">DIY</span>无人机、模拟飞行、<span lang="EN-US">GPS</span>飞行动作、姿态飞行动作、航空摄影摄像技法训练及后期处理等。</span></p></div></div></div>','oracle.sql.CLOB@4445629',NULL,NULL,NULL,NULL,NULL,'2019-11-18 16:20:00',NULL,'2024-05-21 10:33:27',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/201912/t20191206_871651.html',10);

