INSERT INTO `GovDocNews` (`o_id`,`DocTitle`,`ShortTitle`,`DocHtmlCon`,`DocContent`,`SUBDOCTITLE`,`DOCKEYWORDS`,`DocAbstract`,`DOCSOURCENAME`,`DOCAUTHOR`,`DOCRELTIME`,`DocLink`,`DOCPUBTIME`,`SITEID`,`SITENAME`,`CHANNELID`,`DOCPUBURL`,`DOCSTATUS`) VALUES	 (1668670,'关于进一步加强我市技工院校新型冠状病毒感染的肺炎疫情防控工作的通知','关于进一步加强我市技工院校新型冠状病毒感染的肺炎疫情防控工作的通知','<div class="view TRS_UEDITOR trs_paper_default trs_web trs_word trs_key4format"><p style="text-indent: 0em; text-align: center;">京能指文〔2020〕2号</p><p style="text-indent: 2em;"><br/></p><p style="text-indent: 0em;">各技工院校：</p><p style="text-indent: 2em;">新型冠状病毒感染的肺炎疫情发生以来，在防疫工作中各院校按照习近平总书记的指示和党中央的精神积极落实市委、市政府各项防控工作部署，采取有力防控措施，严格校园内部管理，制定工作方案，采取离校不离家的方式开展线上教学培训工作，切实把各项工作抓实、抓细，坚决打赢疫情防控的人民战争、总体战、阻击战。为坚决贯彻习近平总书记“全力做好北京疫情防控工作”的重要指示精神，克服松懈麻痹思想，进一步提高对疫情防控重要性的认识，压实疫情防控责任，加大疫情防控工作力度，现对疫情防控工作中教职工、学生（含实习生）等方面的管理提出如下要求，请结合实际抓好落实。</p><p style="text-indent: 2em;">一、内防扩散，继续强化院校内部管理</p><p style="text-indent: 2em;">一是对校园实行封闭管理。严禁外来人员进入校园。校园内工作人员要减少聚集和会议频次，控制参会规模，提倡开短会。持续加强食堂管理，采用盒饭分散用餐。严格落实院校住宿防控标准，坚持做好校园内公共区域的通风、消毒，设置好隔离观察区域，备足必要的疫情防控物资。完善开学后疫情防控工作预案，制定并实施好防控措施，加大环境卫生整治力度，全面做好疫情防控工作，确保校园内部安全稳定。</p><p style="text-indent: 2em;">二是加强人员管理。在分类防控的基础上，分级分类做好师生健康管理，继续坚持每日开展体温检测和信息统计制度，建立师生流动、健康台账，实时掌握疫情防控底数。督促教职工做好安全防护，减少感冒等疾病以防就医产生交叉感染。有外包服务及劳务派遣等用工的院校要尽最大可能减少用工数量，降低此类人员来校工作频次，督促在校工作人员严格落实疫情防控要求。及时掌握在京学生实际情况，教育引导学生按照疫情防控工作要求，在京期间尽量减少外出，居家学习生活，做好自我防护。疫情防控期间暂停所有学生实习工作。</p><p style="text-indent: 2em;">二、外防输入，严把疫情防控标准</p><p style="text-indent: 2em;">各院校要按照“四方责任”的要求，持续履行好主体责任，教育引导学生“不离家、不返校”，落实好本市疫情防控工作的关键措施、环节。各院校要及时向学生及家长传达本市的相关要求，了解居家情况。严守政治要求和政治纪律，自通知下发之日起，严格返京师生（北京居住）全程管理工作，返京师生（北京居住）必须报所在院校批准后方可返京，返京途中回京后做好安全防护和隔离观察。</p><p style="text-indent: 2em;">一是严格返京师生（北京居住）进京标准。在湖北地区人员由所属院校负责通知其本人疫情防控期间一律不得返京，并严格服从当地管理，暂时不能离开湖北；除湖北外地区原则上由院校进行劝阻，暂不返京；湖北以外地区因工作需要确需返京的教工，由院校为管理主体，统一将人员名单报办学单位，经办学单位批准同意后，相关人员方可进京。</p><p style="text-indent: 2em;">二是严格执行隔离观察标准。请各院校对近期来京人员进行排查，对未满隔离期的进京人员进行相应隔离处置。抵京前14日内，离开武汉及湖北疫情高发地区或者有过疫情高发地区人员接触史的人员，按规定接受医学观察或者居家观察14天，一律不得外出，出现发热症状，按规定及时就诊排查。其他地区人员进京当天要及时向社区报到，严格执行14天居家观察，并按居住地要求做好相关工作。对本市新增并经卫生健康部门流行病学调查确认为密切接触者的人员，要服从各区安排实行集中隔离并进行医学观察。</p><p style="text-indent: 2em;">三、积极采取措施，组织好在线教育</p><p style="text-indent: 2em;">根据前期“一校一策”工作安排，各院校均成立教学工作领导小组，按照“延期开学不停学”要求积极开展线上教学培训准备工作，目前各类在线教学培训工作已经陆续展开。各院校要周密组织加强教学管理，严格落实线上教学计划，依托自有网站和第三方平台，通过在线直播、视频录播、实时互动、课中答题、课后考核等灵活多样的形式开展线上教学培训，确保教学质量。及时与学生家庭沟通，了解掌握学生学习情况，收集对在线教学的意见建议，针对性做好解释、整改。疫情防控期间严禁开展任何形式的线下教学培训。</p><p style="text-indent: 2em;">四、加强教育，持续加大舆论宣传力度</p><p style="text-indent: 2em;">疫情发生以来，市人力资源和社会保障局和各院校先后通过倡议书、微信、微博等形式开展宣传教育，向广大师生普及疫情防控知识，加强心理疏导，缓解师生的焦虑情绪，提高全体师生防护意识，坚定师生战胜疫情的信心和决心。各院校要继续发挥互联网优势，利用公众号、微信群、微博等宣传手段科普疫情防控知识和防控政策，让广大师生及时掌握疫情防控工作要求，自觉落实防控措施，自觉遵守各级疫情防控规定。引导全体师生不信谣、不传谣，正确应对疫情。</p><p style="text-indent: 2em;">各院校应参照《新型冠状病毒感染的肺炎流行期间中小学校和托幼机构防控指引（第一版）》积极抗击疫情。</p><p style="text-indent: 2em;"><br/></p><p style="text-indent: 2em;">附件：新型冠状病毒感染的肺炎流行期间中小学校和托幼机构防控指引（第一版）</p><p style="text-indent: 2em;"><br/></p><p style="text-align: left; text-indent: 2em;"><br/></p><p style="text-align: right; text-indent: 2em;">北京市职业能力建设指导中心</p><p style="text-align: right; text-indent: 2em;">2020年2月25日</p><p style="text-align: right;"><br/></p></div>','京能指文〔2020〕2号各技工院校：新型冠状病毒感染的肺炎疫情发生以来，在防疫工作中各院校按照习近平总书记的指示和党中央的精神积极落实市委、市政府各项防控工作部署，采取有力防控措施，严格校园内部管理，制定工作方案，采取离校不离家的方式开展线上教学培训工作，切实把各项工作抓实、抓细，坚决打赢疫情防控的人民战争、总体战、阻击战。为坚决贯彻习近平总书记“全力做好北京疫情防控工作”的重要指示精神，克服松懈麻痹思想，进一步提高对疫情防控重要性的认识，压实疫情防控责任，加大疫情防控工作力度，现对疫情防控工作中教职工、学生（含实习生）等方面的管理提出如下要求，请结合实际抓好落实。一、内防扩散，继续强化院校内部管理一是对校园实行封闭管理。严禁外来人员进入校园。校园内工作人员要减少聚集和会议频次，控制参会规模，提倡开短会。持续加强食堂管理，采用盒饭分散用餐。严格落实院校住宿防控标准，坚持做好校园内公共区域的通风、消毒，设置好隔离观察区域，备足必要的疫情防控物资。完善开学后疫情防控工作预案，制定并实施好防控措施，加大环境卫生整治力度，全面做好疫情防控工作，确保校园内部安全稳定。二是加强人员管理。在分类防控的基础上，分级分类做好师生健康管理，继续坚持每日开展体温检测和信息统计制度，建立师生流动、健康台账，实时掌握疫情防控底数。督促教职工做好安全防护，减少感冒等疾病以防就医产生交叉感染。有外包服务及劳务派遣等用工的院校要尽最大可能减少用工数量，降低此类人员来校工作频次，督促在校工作人员严格落实疫情防控要求。及时掌握在京学生实际情况，教育引导学生按照疫情防控工作要求，在京期间尽量减少外出，居家学习生活，做好自我防护。疫情防控期间暂停所有学生实习工作。二、外防输入，严把疫情防控标准各院校要按照“四方责任”的要求，持续履行好主体责任，教育引导学生“不离家、不返校”，落实好本市疫情防控工作的关键措施、环节。各院校要及时向学生及家长传达本市的相关要求，了解居家情况。严守政治要求和政治纪律，自通知下发之日起，严格返京师生（北京居住）全程管理工作，返京师生（北京居住）必须报所在院校批准后方可返京，返京途中回京后做好安全防护和隔离观察。一是严格返京师生（北京居住）进京标准。在湖北地区人员由所属院校负责通知其本人疫情防控期间一律不得返京，并严格服从当地管理，暂时不能离开湖北；除湖北外地区原则上由院校进行劝阻，暂不返京；湖北以外地区因工作需要确需返京的教工，由院校为管理主体，统一将人员名单报办学单位，经办学单位批准同意后，相关人员方可进京。二是严格执行隔离观察标准。请各院校对近期来京人员进行排查，对未满隔离期的进京人员进行相应隔离处置。抵京前14日内，离开武汉及湖北疫情高发地区或者有过疫情高发地区人员接触史的人员，按规定接受医学观察或者居家观察14天，一律不得外出，出现发热症状，按规定及时就诊排查。其他地区人员进京当天要及时向社区报到，严格执行14天居家观察，并按居住地要求做好相关工作。对本市新增并经卫生健康部门流行病学调查确认为密切接触者的人员，要服从各区安排实行集中隔离并进行医学观察。三、积极采取措施，组织好在线教育根据前期“一校一策”工作安排，各院校均成立教学工作领导小组，按照“延期开学不停学”要求积极开展线上教学培训准备工作，目前各类在线教学培训工作已经陆续展开。各院校要周密组织加强教学管理，严格落实线上教学计划，依托自有网站和第三方平台，通过在线直播、视频录播、实时互动、课中答题、课后考核等灵活多样的形式开展线上教学培训，确保教学质量。及时与学生家庭沟通，了解掌握学生学习情况，收集对在线教学的意见建议，针对性做好解释、整改。疫情防控期间严禁开展任何形式的线下教学培训。四、加强教育，持续加大舆论宣传力度疫情发生以来，市人力资源和社会保障局和各院校先后通过倡议书、微信、微博等形式开展宣传教育，向广大师生普及疫情防控知识，加强心理疏导，缓解师生的焦虑情绪，提高全体师生防护意识，坚定师生战胜疫情的信心和决心。各院校要继续发挥互联网优势，利用公众号、微信群、微博等宣传手段科普疫情防控知识和防控政策，让广大师生及时掌握疫情防控工作要求，自觉落实防控措施，自觉遵守各级疫情防控规定。引导全体师生不信谣、不传谣，正确应对疫情。各院校应参照《新型冠状病毒感染的肺炎流行期间中小学校和托幼机构防控指引（第一版）》积极抗击疫情。附件：新型冠状病毒感染的肺炎流行期间中小学校和托幼机构防控指引（第一版）北京市职业能力建设指导中心2020年2月25日',NULL,'疫情防控;师生;院校;疫情;地区人员;冠状病毒;办学单位;托幼机构;频次;肺炎','京能指文〔2020〕2号各技工院校：新型冠状病毒感染的肺炎疫情发生以来，在防疫工作中各院校按照习近平总书记的指示和党中央的精神积极落实市委、市政府各项防控工作部署，采取有力防控措施，严格校园内部管理，制定工作方案，采取离校不离家的方式开展线上教学培训工作。为坚决贯彻习近平总书记“全力做好北京疫情防控工作”的重要指示精神，克服松懈麻痹思想，进一步提高对疫情防控重要性的认识，压实疫情防控责任，加大疫情防控工作力度，现对疫情防控工作中教职工、学生（含实习生）等方面的管理提出如下要求，请结合实际抓好落实。各院校应参照《新型冠状病毒感染的肺炎流行期间中小学校和托幼机构防控指引（第一版）》积极抗击疫情。','北京市职业能力建设指导中心','北京市职业能力建设指导中心','2020-02-25 23:36:00',NULL,'2023-08-24 20:20:50',6,'北京市人力资源和社会保障局',16733,'http://rsj.beijing.gov.cn/weimenhu/wgsgg/202002/t20200225_1668670.html',10),	 (1893090,'疫情期间劳动争议如何解决？北京发布22条法律适用问题解答',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><div></div><p style="text-indent: 2em;">4月29日，北京市高级人民法院与北京市劳动人事争议仲裁委员会联合发布《关于审理新型冠状病毒感染肺炎疫情防控期间劳动争议案件法律适用问题的解答》（以下简称《解答》），针对疫情期间劳动争议案件审理中亟待解决的具体问题作出规范和回应。其中明确，因疫情影响受聘劳动者无法按约定入职的，劳动者开始提供劳动之日视为用人单位开始用工之日。<br/></p><p style="text-indent: 2em;">统一裁判尺度，减少劳动争议</p><p style="text-indent: 2em;">“受疫情影响，劳动关系领域矛盾凸显，出现了一些前所未有的新情况和新问题。”北京高院民一庭庭长宋毅表示，为公正、高效处理争议，统一裁判尺度，北京市高级人民法院和北京市劳动人事争议仲裁委员会共同研究制定了《解答》。</p><p style="text-indent: 2em;">《解答》共22条，明确了疫情防控期间劳动争议案件处理原则，在劳动关系建立、工资待遇、劳动合同解除等方面，结合疫情期间可能存在的特殊情况进行解答，厘清思路。</p><p style="text-indent: 2em;">在劳动关系建立方面，《解答》明确，受聘劳动者因疫情影响无法按约定入职，用人单位以灵活用工方式已经安排劳动者提供劳动的，劳动者开始提供劳动之日视为用人单位开始用工之日。</p><p style="text-indent: 2em;">针对工资待遇问题，《解答》明确，用人单位安排劳动者在家上班或灵活办公，一般应视为劳动者正常出勤；用人单位安排劳动者看护未成年子女期间在家上班，按照劳动者正常出勤支付劳动报酬。</p><p style="text-indent: 2em;">在劳动合同解除方面，《解答》提出，劳动者以非正当理由拒绝返岗的，用人单位可以依法解除劳动合同。</p><p style="text-indent: 2em;">在疫情期间员工试用期方面，《解答》明确，用人单位与劳动者协商顺延试用期，不违反“同一用人单位与同一劳动者只能约定一次试用期”规定精神。若扣除受疫情影响期间后，实际履行的试用期超过原约定试用期，劳动者可主张工资差额及赔偿金。</p><p style="text-indent: 2em;">司法服务不打烊</p><p style="text-indent: 2em;">北京劳动仲裁委常务副主任陆晓播表示，疫情防控以来，市区两级仲裁机构窗口服务不停歇，咨询热线不间断；及时出台仲裁政策，中止仲裁时效，案件可申请延期审理；开展邮寄立案，搭建“云仲裁庭”，实现线上与线下审理相结合；推广“互联网+调解”平台，会同司法局建立法律援助窗口。</p><p style="text-indent: 2em;">陆晓播介绍，疫情防控期间，全市基层劳动人事争议调解组织受理调解申请4000余件，其中82%的争议调解成功；仲裁机构受理案件1.5万余件，审结1万余件。</p><p style="text-indent: 2em;">北京高院副院长蔡慧永表示，疫情期间北京市法院审判工作不停摆、不打烊，开发建设了北京“云法庭”，开展网上云审判，方便当事人参与庭审。2月3日至4月26日，全市法院通过北京云法庭审理案件48035件。此外，当事人通过“北京移动微法院”“北京法院审判信息网”等诉讼服务平台进行网上立案34431件，开展网上调解近5万次，12368热线接听当事人电话24686次，为律师提供在线服务17994人次。</p><p style="text-indent: 2em;">“除劳动争议外，市高级法院目前对疫情期间房屋租赁合同纠纷、网约车案件等重点领域纠纷进行梳理研判，加大对中基层法院的指导力度，统一全市法院相关案件裁判尺度。”蔡慧永表示。</p><p><br/></p></div>','4月29日，北京市高级人民法院与北京市劳动人事争议仲裁委员会联合发布《关于审理新型冠状病毒感染肺炎疫情防控期间劳动争议案件法律适用问题的解答》（以下简称《解答》），针对疫情期间劳动争议案件审理中亟待解决的具体问题作出规范和回应。其中明确，因疫情影响受聘劳动者无法按约定入职的，劳动者开始提供劳动之日视为用人单位开始用工之日。统一裁判尺度，减少劳动争议“受疫情影响，劳动关系领域矛盾凸显，出现了一些前所未有的新情况和新问题。”北京高院民一庭庭长宋毅表示，为公正、高效处理争议，统一裁判尺度，北京市高级人民法院和北京市劳动人事争议仲裁委员会共同研究制定了《解答》。《解答》共22条，明确了疫情防控期间劳动争议案件处理原则，在劳动关系建立、工资待遇、劳动合同解除等方面，结合疫情期间可能存在的特殊情况进行解答，厘清思路。在劳动关系建立方面，《解答》明确，受聘劳动者因疫情影响无法按约定入职，用人单位以灵活用工方式已经安排劳动者提供劳动的，劳动者开始提供劳动之日视为用人单位开始用工之日。针对工资待遇问题，《解答》明确，用人单位安排劳动者在家上班或灵活办公，一般应视为劳动者正常出勤；用人单位安排劳动者看护未成年子女期间在家上班，按照劳动者正常出勤支付劳动报酬。在劳动合同解除方面，《解答》提出，劳动者以非正当理由拒绝返岗的，用人单位可以依法解除劳动合同。在疫情期间员工试用期方面，《解答》明确，用人单位与劳动者协商顺延试用期，不违反“同一用人单位与同一劳动者只能约定一次试用期”规定精神。若扣除受疫情影响期间后，实际履行的试用期超过原约定试用期，劳动者可主张工资差额及赔偿金。司法服务不打烊北京劳动仲裁委常务副主任陆晓播表示，疫情防控以来，市区两级仲裁机构窗口服务不停歇，咨询热线不间断；及时出台仲裁政策，中止仲裁时效，案件可申请延期审理；开展邮寄立案，搭建“云仲裁庭”，实现线上与线下审理相结合；推广“互联网+调解”平台，会同司法局建立法律援助窗口。陆晓播介绍，疫情防控期间，全市基层劳动人事争议调解组织受理调解申请4000余件，其中82%的争议调解成功；仲裁机构受理案件1.5万余件，审结1万余件。北京高院副院长蔡慧永表示，疫情期间北京市法院审判工作不停摆、不打烊，开发建设了北京“云法庭”，开展网上云审判，方便当事人参与庭审。2月3日至4月26日，全市法院通过北京云法庭审理案件48035件。此外，当事人通过“北京移动微法院”“北京法院审判信息网”等诉讼服务平台进行网上立案34431件，开展网上调解近5万次，12368热线接听当事人电话24686次，为律师提供在线服务17994人次。“除劳动争议外，市高级法院目前对疫情期间房屋租赁合同纠纷、网约车案件等重点领域纠纷进行梳理研判，加大对中基层法院的指导力度，统一全市法院相关案件裁判尺度。”蔡慧永表示。',NULL,NULL,NULL,'人民网',NULL,'2020-04-30 15:29:00',NULL,'2023-08-28 07:57:12',6,'北京市人力资源和社会保障局',15299,'http://rsj.beijing.gov.cn/weimenhu/wmtgz/202005/t20200509_1893090.html',10),	 (901555,'2019年度北京市初级注册安全工程师职业资格考试将于10月10日开始报名','2019年度北京市初级注册安全工程师职业资格考试将于10月10日开始报名',NULL,NULL,NULL,NULL,NULL,'自发','北京市人力资源和社会保障局','2019-12-06 18:11:00',NULL,'2024-04-22 10:15:04',6,'北京市人力资源和社会保障局',17836,'https://rsj.beijing.gov.cn/ywsite/bjpta/xwzx/zytz/201912/P020191206654676913363.pdf',10),	 (871657,'京津冀人社事业协同发展第三次部省（市）联席会议近日召开','京津冀人社事业协同发展第三次部省（市）联席会议近日召开','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><div class="Custom_UnionStyle"><div style="overflow-x: hidden; word-break: break-all">　　京津冀人社事业协同发展第三次部省（市）联席会议近日召开。人社部汤涛副部长、市政府陈蓓副秘书长、北京市人力社保局徐熙局长，天津市人力社保局杨光局长，河北省人力社保厅宋立民厅长参加会议。会议总结交流了京津冀人力社保事业协同发展成效与经验，对支持河北雄安新区人社改革创新，以及下一步攻坚克难、下更大力气推动京津冀协同发展工作进行了研究部署。会议期间，全体参会人员参观调研了北京城市副中心建设情况和中国北京人力资源服务产业园通州园发展情况。 　　&nbsp;&nbsp;&nbsp; 徐熙局长指出，过去一年中，北京人力资源社会保障部门在稳步推进三地社保政策对接和标准衔接、京津共设新职称和缩短养老保险转移接续时间、支持雄安新区劳动力再就业技能培训、推动人力社保公共服务向廊坊北三县延伸等方面开展了一系列工作，下一步将深入落实好人力资源社会保障部关于人社事业协同发展和支持雄安新区改革创新相关部署，围绕进一步推进人力社保基本公共服务共建共享、支持雄安新区再就业培训和廊坊北三县人力社保公共服务协同、助推河北打赢打好脱贫攻坚战并巩固好工作成果等方面重点开展工作。&nbsp;</div><div style="overflow-x: hidden; word-break: break-all">&nbsp;&nbsp;&nbsp; 陈蓓副秘书长表示，京津冀协同发展是以习近平同志为核心的党中央在新的历史条件下作出的重大决策部署，是习近平总书记亲自谋划、亲自决策、亲自推动的重大国家战略。北京市委、市政府高度重视协同发展工作，疏解北京非首都功能已经成为北京核心工作，北京发展取得的成就，离不开天津、河北兄弟省市的有力帮助，更离不开人社部的大力支持，特别是协同发展5年多来，在人社部的领导和指挥下，三地人社部门开展了一系列卓有成效的工作。当前，京津冀协同发展进入滚石上山、爬坡过坎、攻坚克难的关键阶段，北京将在人社部的指导支持下，和天津、河北一起，全面贯彻习近平总书记重要讲话精神，进一步推动京津冀协同发展取得新成效，不断提高人民群众的幸福感、获得感。&nbsp;</div><div style="overflow-x: hidden; word-break: break-all">&nbsp;&nbsp;&nbsp; 汤涛副部长强调，在京津冀协同发展战略实施五周年之际，习近平总书记视察京津冀，主持召开京津冀协同发展座谈会并发表重要讲话，再次表明了中央推进这项事业的坚定决心，我们要进一步提高政治站位，更好地将总书记重要讲话精神落到实处，从全局的高度和更长远的考虑来认识和做好京津冀协同发展工作；要增强协同发展的自觉性、主动性、创造性，重点突破、以点带面，抓好支持河北雄安新区人社改革创新工作；要进一步深化劳务协作、发展人力资源服务业、优化社会保险关系转接、深化人才体制机制改革、加强争议处理和监察执法协作，推动京津冀人社事业协同发展取得新的更大突破。</div></div></div></div>','　　京津冀人社事业协同发展第三次部省（市）联席会议近日召开。人社部汤涛副部长、市政府陈蓓副秘书长、北京市人力社保局徐熙局长，天津市人力社保局杨光局长，河北省人力社保厅宋立民厅长参加会议。会议总结交流了京津冀人力社保事业协同发展成效与经验，对支持河北雄安新区人社改革创新，以及下一步攻坚克难、下更大力气推动京津冀协同发展工作进行了研究部署。会议期间，全体参会人员参观调研了北京城市副中心建设情况和中国北京人力资源服务产业园通州园发展情况。 　　    徐熙局长指出，过去一年中，北京人力资源社会保障部门在稳步推进三地社保政策对接和标准衔接、京津共设新职称和缩短养老保险转移接续时间、支持雄安新区劳动力再就业技能培训、推动人力社保公共服务向廊坊北三县延伸等方面开展了一系列工作，下一步将深入落实好人力资源社会保障部关于人社事业协同发展和支持雄安新区改革创新相关部署，围绕进一步推进人力社保基本公共服务共建共享、支持雄安新区再就业培训和廊坊北三县人力社保公共服务协同、助推河北打赢打好脱贫攻坚战并巩固好工作成果等方面重点开展工作。     陈蓓副秘书长表示，京津冀协同发展是以习近平同志为核心的党中央在新的历史条件下作出的重大决策部署，是习近平总书记亲自谋划、亲自决策、亲自推动的重大国家战略。北京市委、市政府高度重视协同发展工作，疏解北京非首都功能已经成为北京核心工作，北京发展取得的成就，离不开天津、河北兄弟省市的有力帮助，更离不开人社部的大力支持，特别是协同发展5年多来，在人社部的领导和指挥下，三地人社部门开展了一系列卓有成效的工作。当前，京津冀协同发展进入滚石上山、爬坡过坎、攻坚克难的关键阶段，北京将在人社部的指导支持下，和天津、河北一起，全面贯彻习近平总书记重要讲话精神，进一步推动京津冀协同发展取得新成效，不断提高人民群众的幸福感、获得感。     汤涛副部长强调，在京津冀协同发展战略实施五周年之际，习近平总书记视察京津冀，主持召开京津冀协同发展座谈会并发表重要讲话，再次表明了中央推进这项事业的坚定决心，我们要进一步提高政治站位，更好地将总书记重要讲话精神落到实处，从全局的高度和更长远的考虑来认识和做好京津冀协同发展工作；要增强协同发展的自觉性、主动性、创造性，重点突破、以点带面，抓好支持河北雄安新区人社改革创新工作；要进一步深化劳务协作、发展人力资源服务业、优化社会保险关系转接、深化人才体制机制改革、加强争议处理和监察执法协作，推动京津冀人社事业协同发展取得新的更大突破。',NULL,NULL,NULL,NULL,NULL,'2019-10-21 11:01:00',NULL,'2024-05-21 10:33:28',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/201912/t20191206_871657.html',10),	 (871660,'市人力社保局积极开展“喜迎国庆，服务民生”系列宣传活动','市人力社保局积极开展“喜迎国庆，服务民生”系列宣传活动','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><div class="Custom_UnionStyle"><div style="-ms-word-break: break-all; -ms-overflow-x: hidden;">&nbsp;<p>　　市人力社保局积极开展“喜迎国庆，服务民生”系列宣传活动。参加“北京市庆祝中华人民共和国成立70周年”系列新闻发布会-社会民生专场活动，介绍新中国成立70年以来本市不断推进更高质量更充分就业的积极举措和显著成果。新华社、北京日报等30余家中央及市属媒体分别以“新中国成立70周年北京市就业工作进展和成效”“北京给参加技能培训的企业职工送大礼包”等为题报道百余条次。组织中央及市属媒体宣传市局出版的《北京社保七十年》一书，北京日报、北京青年报、今日头条等媒体围绕“新中国成立70年来，北京社会保险制度历史变迁和发展脉络”“北京人力社保工作在凝聚民心、巩固党的执政基础中发挥的重要作用”等方面予以报道。依托北京日报“壮丽70年·奋斗新时代”特刊，以“接力率先实现全面小康”为题，解读本市在帮助农村劳动力多渠道就业方面的综合措施，点赞本市人力社保部门稳就业、促就业，持续保障和改善民生的惠民举措。北京劳动就业报、北京人才市场报分别以“壮丽70年·奋斗新时代”“我和我的祖国”为题出版特刊44版。制作“我和我的祖国”MV，组织全局干部职工举行迎国庆、升国旗活动并制作短视频，通过学习强国、北京劳动就业报微信等平台宣传推送。</p></div></div></div></div>','　　市人力社保局积极开展“喜迎国庆，服务民生”系列宣传活动。参加“北京市庆祝中华人民共和国成立70周年”系列新闻发布会-社会民生专场活动，介绍新中国成立70年以来本市不断推进更高质量更充分就业的积极举措和显著成果。新华社、北京日报等30余家中央及市属媒体分别以“新中国成立70周年北京市就业工作进展和成效”“北京给参加技能培训的企业职工送大礼包”等为题报道百余条次。组织中央及市属媒体宣传市局出版的《北京社保七十年》一书，北京日报、北京青年报、今日头条等媒体围绕“新中国成立70年来，北京社会保险制度历史变迁和发展脉络”“北京人力社保工作在凝聚民心、巩固党的执政基础中发挥的重要作用”等方面予以报道。依托北京日报“壮丽70年·奋斗新时代”特刊，以“接力率先实现全面小康”为题，解读本市在帮助农村劳动力多渠道就业方面的综合措施，点赞本市人力社保部门稳就业、促就业，持续保障和改善民生的惠民举措。北京劳动就业报、北京人才市场报分别以“壮丽70年·奋斗新时代”“我和我的祖国”为题出版特刊44版。制作“我和我的祖国”MV，组织全局干部职工举行迎国庆、升国旗活动并制作短视频，通过学习强国、北京劳动就业报微信等平台宣传推送。',NULL,'市人力社保局积极开展“喜迎国庆;服务民生”系列宣传活动','市人力社保局积极开展“喜迎国庆，服务民生”系列宣传活动。依托北京日报“壮丽70年·奋斗新时代”特刊，以“接力率先实现全面小康”为题，解读本市在帮助农村劳动力多渠道就业方面的综合措施，点赞本市人力社保部门稳就业、促就业，持续保障和改善民生的惠民举措。制作“我和我的祖国”MV，组织全局干部职工举行迎国庆、升国旗活动并制作短视频，通过学习强国、北京劳动就业报微信等平台宣传推送。','自发','北京市人力资源和社会保障局','2019-10-10 10:01:00',NULL,'2024-05-21 10:33:28',6,'北京市人力资源和社会保障局',15291,'https://rsj.beijing.gov.cn/weimenhu/wgzdt/201912/t20191206_871660.html',10),	 (1893096,'北京市重点行业中小微企业可享援企稳岗补贴 最高标准可达每人4540元',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><div></div><p style="text-indent: 2em;">近日，北京市人力资源和社会保障局、北京市财政局联合印发《关于精准支持重点行业中小微企业稳定就业工作的通知》，把职业技能培训作为保持就业稳定的重要举措，精准支持重点行业中小微企业稳定就业岗位，提升劳动力技能素质，助力企业复工复产。此次援企稳岗政策包括以训稳岗培训补贴和临时性岗位补贴两项政策。5月6日起，北京市将分四批公布重点行业中小微企业名单，名单内企业可叠加申请上述两项补贴政策。<br/></p><p style="text-indent: 2em;">企业援企稳岗补贴最高标准可达每人4540元</p><p style="text-indent: 2em;">援企稳岗补贴政策主要面向符合首都功能定位和区域发展规划的科技创新、城市运行保障、生活性服务业等重点行业，且在北京市参加失业保险的中小微企业，同时企业还要满足“受疫情影响，2020年2-4月生产经营收入同比下降80%（含）以上”这一条件。各参保企业所在区对符合条件的中小微企业名单进行认定。对于组织职工开展培训时长累计不低于20课时（900分钟）的，按照每人500元标准给予企业以训稳岗培训补贴，培训补贴最高不超过120课时（5400分钟）3000元。此外，对开展培训的企业，按照参训职工每人1540元的标准给予企业临时性岗位补贴。</p><p style="text-indent: 2em;">本次针对重点行业中小微企业的两项补贴政策，均可在线申请，无需企业跑腿。两项补贴的申请截止时间均为2020年8月31日。其中，临时性岗位补贴在开展培训的同时，企业就可以立即申请，标准是按参训职工每人1540元标准。以训稳岗补贴是在培训完成后，企业通过一证通登录市人力资源社会保障局官网（http://rsj.beijing.gov.cn/）“职业技能提升行动”模块“援企稳岗培训补贴”，按流程申请即可。企业参保地所属区人力资源社会保障局将及时审核申请。申请培训补贴时，参训职工须仍在本企业就业。领取培训补贴后，企业可将补贴用于职工教育经费各项支出，或缴纳本企业社会保险费。</p><p style="text-indent: 2em;">在培训内容上，企业可以根据岗位技能需求和生产经营特点自主确定，包括岗位技能提升、技能竞赛培训、健康防疫、通用职业素质、职业指导、工伤预防、安全生产等。培训可采取线上、线下，或两者结合的方式开展，线上线下合并申请培训补贴。企业可以自行组织培训，也可委托具备资质的机构组织开展培训工作。</p><p style="text-indent: 2em;">据悉，为保障补贴及时到位，北京市人力资源社会保障局搭建了“北京市职业技能提升行动管理平台”（www.bjjnts.cn），5月6日起上线运行。企业可在5月6日到7月31日期间，组织职工登录管理平台，注册后即可开展线上或使用平台考勤录制功能开展线下培训。企业通过平台就可以开展直播、录播等企业内训，平台会记录培训全过程，生成学习记录电子报告凭证，企业下载凭证后即可线上申请补贴。</p><p><br/></p></div>','近日，北京市人力资源和社会保障局、北京市财政局联合印发《关于精准支持重点行业中小微企业稳定就业工作的通知》，把职业技能培训作为保持就业稳定的重要举措，精准支持重点行业中小微企业稳定就业岗位，提升劳动力技能素质，助力企业复工复产。此次援企稳岗政策包括以训稳岗培训补贴和临时性岗位补贴两项政策。5月6日起，北京市将分四批公布重点行业中小微企业名单，名单内企业可叠加申请上述两项补贴政策。企业援企稳岗补贴最高标准可达每人4540元援企稳岗补贴政策主要面向符合首都功能定位和区域发展规划的科技创新、城市运行保障、生活性服务业等重点行业，且在北京市参加失业保险的中小微企业，同时企业还要满足“受疫情影响，2020年2-4月生产经营收入同比下降80%（含）以上”这一条件。各参保企业所在区对符合条件的中小微企业名单进行认定。对于组织职工开展培训时长累计不低于20课时（900分钟）的，按照每人500元标准给予企业以训稳岗培训补贴，培训补贴最高不超过120课时（5400分钟）3000元。此外，对开展培训的企业，按照参训职工每人1540元的标准给予企业临时性岗位补贴。本次针对重点行业中小微企业的两项补贴政策，均可在线申请，无需企业跑腿。两项补贴的申请截止时间均为2020年8月31日。其中，临时性岗位补贴在开展培训的同时，企业就可以立即申请，标准是按参训职工每人1540元标准。以训稳岗补贴是在培训完成后，企业通过一证通登录市人力资源社会保障局官网（http://rsj.beijing.gov.cn/）“职业技能提升行动”模块“援企稳岗培训补贴”，按流程申请即可。企业参保地所属区人力资源社会保障局将及时审核申请。申请培训补贴时，参训职工须仍在本企业就业。领取培训补贴后，企业可将补贴用于职工教育经费各项支出，或缴纳本企业社会保险费。在培训内容上，企业可以根据岗位技能需求和生产经营特点自主确定，包括岗位技能提升、技能竞赛培训、健康防疫、通用职业素质、职业指导、工伤预防、安全生产等。培训可采取线上、线下，或两者结合的方式开展，线上线下合并申请培训补贴。企业可以自行组织培训，也可委托具备资质的机构组织开展培训工作。据悉，为保障补贴及时到位，北京市人力资源社会保障局搭建了“北京市职业技能提升行动管理平台”（www.bjjnts.cn），5月6日起上线运行。企业可在5月6日到7月31日期间，组织职工登录管理平台，注册后即可开展线上或使用平台考勤录制功能开展线下培训。企业通过平台就可以开展直播、录播等企业内训，平台会记录培训全过程，生成学习记录电子报告凭证，企业下载凭证后即可线上申请补贴。',NULL,NULL,NULL,'央视网',NULL,'2020-05-06 15:30:00',NULL,'2023-08-28 07:57:12',6,'北京市人力资源和社会保障局',15299,'http://rsj.beijing.gov.cn/weimenhu/wmtgz/202005/t20200509_1893096.html',10),	 (1893104,'发放援企稳岗补贴 支持复工复产贵在“精准”',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><div></div><p style="text-indent: 2em;">随着疫情防控形势的好转，各地复工复产稳步推进，一些利好政策也不断推出。近日，北京市人力资源和社会保障局、北京市财政局联合印发《关于精准支持重点行业中小微企业稳定就业工作的通知》（以下简称《通知》），出台“以训稳岗”培训补贴和临时性岗位补贴等援企稳岗政策，企业援企稳岗补贴，最高标准可达每人4540元。从5月6日起，北京市将分四批公布重点行业中小微企业名单，名单内企业可叠加申请上述两项补贴政策。（人民网5月6日）<br/></p><p style="text-indent: 2em;">审视这项最新面世的政策，的确有不少值得点赞的“招法”。首先就是靶子定位“精准”，将重点行业中小微企业作为支持的主要对象。中小微企业和民营企业发展，是复工复产、稳定就业的关键所在。据有关统计，仅小微企业便贡献了全国80%的就业。从某种程度上讲，稳住了中小微企业，就稳住了就业，才会有真正意义上的复工复产。北京市出台的最新《通知》，将中小微企业作为支持对象，可谓抓住了推动经济全面复苏的“牛鼻子”。</p><p style="text-indent: 2em;">支持中小微企业发展，离不开一定的资金投入。在当前的特殊形势下，面临经营困顿的中小微企业为数不少，而政府资金也很有限，平均分到每个企业头上，也起不到多大的功效。根据《通知》，将需要支持的中小微企业，限定在面向符合首都功能定位和区域发展规划的科技创新、城市运行保障、生活性服务业等重点行业，且在北京市参加失业保险的中小微企业，同时企业还要满足“受疫情影响，2020年2-4月生产经营收入同比下降80%（含）以上”等条件。重点行业，的确是亟待重点扶持的领域，而精准化投放的“纾困”资金，更会产生“四两拨千斤”、稳定市场秩序的效果。</p><p style="text-indent: 2em;">《通知》的另一大亮点，就是路径选得“精准”。从以往的一些补贴政策看，主要采取的是按人头分配的方法，这固然能帮困难者解燃眉之急，但只是“授之以鱼”，对帮困对象来说，并没有因此增强“造血”能力。根据《通知》，此次援企稳岗政策，还包括一定数额的以训稳岗培训补贴，企业可以根据岗位技能需求和生产经营特点，自主确定线上线下的培训内容，包括岗位技能提升、技能竞赛培训、健康防疫、通用职业素质、职业指导、工伤预防、安全生产等。这笔资金投入，既让企业留住了员工财富，还能利用困难期间，为员工“充电”，提高劳动技能，有利于企业的长远发展，可谓一举多得。</p><p style="text-indent: 2em;">一项政策好不好，出台时机也很重要。从当前形势看，《通知》的出台时机把握“精准”。今年2月召开的国务院常务会议提出，“鼓励地方综合运用失业保险基金结余等资金加大援企稳岗力度，支持有条件的地方实施缓缴或返还部分社保费等政策”，人社部随后也打出“免、返、补、缓、服”的阶段性政策组合拳，表示“全力支持中小微企业稳就业”。审视北京市的最新《通知》，与国家援企稳岗、支持中小微企业政策一脉相承，但分量更足、力道更大、定位更准，在复工复产进入关键期推出，更释放出政府大力支持的讯号，让相关企业和劳动者吃上定心丸，有利于助推经济企稳向好。</p><p style="text-indent: 2em;">援企稳岗，不是一句空话，需要实在管用、精确高效的政策和措施。北京市出台的最新《通知》，大力支持重点行业中小微企业稳定就业，在“精准”上拿出了一剂新药方。服务中小微企业和广大劳动者，同舟共济，共克时艰，我们有理由相信，疫情之后市场复苏的春天势必到来。</p><p><br/></p></div>','随着疫情防控形势的好转，各地复工复产稳步推进，一些利好政策也不断推出。近日，北京市人力资源和社会保障局、北京市财政局联合印发《关于精准支持重点行业中小微企业稳定就业工作的通知》（以下简称《通知》），出台“以训稳岗”培训补贴和临时性岗位补贴等援企稳岗政策，企业援企稳岗补贴，最高标准可达每人4540元。从5月6日起，北京市将分四批公布重点行业中小微企业名单，名单内企业可叠加申请上述两项补贴政策。（人民网5月6日）审视这项最新面世的政策，的确有不少值得点赞的“招法”。首先就是靶子定位“精准”，将重点行业中小微企业作为支持的主要对象。中小微企业和民营企业发展，是复工复产、稳定就业的关键所在。据有关统计，仅小微企业便贡献了全国80%的就业。从某种程度上讲，稳住了中小微企业，就稳住了就业，才会有真正意义上的复工复产。北京市出台的最新《通知》，将中小微企业作为支持对象，可谓抓住了推动经济全面复苏的“牛鼻子”。支持中小微企业发展，离不开一定的资金投入。在当前的特殊形势下，面临经营困顿的中小微企业为数不少，而政府资金也很有限，平均分到每个企业头上，也起不到多大的功效。根据《通知》，将需要支持的中小微企业，限定在面向符合首都功能定位和区域发展规划的科技创新、城市运行保障、生活性服务业等重点行业，且在北京市参加失业保险的中小微企业，同时企业还要满足“受疫情影响，2020年2-4月生产经营收入同比下降80%（含）以上”等条件。重点行业，的确是亟待重点扶持的领域，而精准化投放的“纾困”资金，更会产生“四两拨千斤”、稳定市场秩序的效果。《通知》的另一大亮点，就是路径选得“精准”。从以往的一些补贴政策看，主要采取的是按人头分配的方法，这固然能帮困难者解燃眉之急，但只是“授之以鱼”，对帮困对象来说，并没有因此增强“造血”能力。根据《通知》，此次援企稳岗政策，还包括一定数额的以训稳岗培训补贴，企业可以根据岗位技能需求和生产经营特点，自主确定线上线下的培训内容，包括岗位技能提升、技能竞赛培训、健康防疫、通用职业素质、职业指导、工伤预防、安全生产等。这笔资金投入，既让企业留住了员工财富，还能利用困难期间，为员工“充电”，提高劳动技能，有利于企业的长远发展，可谓一举多得。一项政策好不好，出台时机也很重要。从当前形势看，《通知》的出台时机把握“精准”。今年2月召开的国务院常务会议提出，“鼓励地方综合运用失业保险基金结余等资金加大援企稳岗力度，支持有条件的地方实施缓缴或返还部分社保费等政策”，人社部随后也打出“免、返、补、缓、服”的阶段性政策组合拳，表示“全力支持中小微企业稳就业”。审视北京市的最新《通知》，与国家援企稳岗、支持中小微企业政策一脉相承，但分量更足、力道更大、定位更准，在复工复产进入关键期推出，更释放出政府大力支持的讯号，让相关企业和劳动者吃上定心丸，有利于助推经济企稳向好。援企稳岗，不是一句空话，需要实在管用、精确高效的政策和措施。北京市出台的最新《通知》，大力支持重点行业中小微企业稳定就业，在“精准”上拿出了一剂新药方。服务中小微企业和广大劳动者，同舟共济，共克时艰，我们有理由相信，疫情之后市场复苏的春天势必到来。',NULL,NULL,NULL,'中国青年报',NULL,'2020-05-08 15:31:00',NULL,'2023-08-28 07:57:10',6,'北京市人力资源和社会保障局',15299,'http://rsj.beijing.gov.cn/weimenhu/wmtgz/202005/t20200509_1893104.html',10),	 (1982021,'2020年丰台区卫生健康委所属事业单位面向医疗卫生专业应届毕业生招聘工作人员公告',NULL,'<div class="view TRS_UEDITOR trs_paper_default trs_word trs_key4format"><p style="text-align: left; text-indent: 2em;"><span style="text-indent: 0em;">根据丰台区卫生健康委员会所属事业单位实际工作需要，按照《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）和 《关于进一步规范事业单位公开招聘工作有关问题的通知》（京人社专技发〔2012〕247号）等文件规定，现面向2020年医疗卫生专业应届毕业生公开招聘190名事业单位工作人员，相关事项公告如下：</span><br/></p><p style="text-indent: 2em;">一、招聘条件</p><p style="text-indent: 2em;">（一）遵守宪法和法律，具有良好的品行；</p><p style="text-indent: 2em;">（二）适应岗位要求的身体条件，身心健康；</p><p style="text-indent: 2em;">（三）岗位条件要求的学历、专业、专业技术（职务任职）资格、执（职、从）业资格或专业技能等级等；</p><p style="text-indent: 2em;">（四）招聘对象为列入国家统一招生计划，能够正常参加2020年就业派遣的普通高等院校应届毕业生（不含定向、委培）；</p><p style="text-indent: 2em;">（五）年龄要求为博士研究生不超过35周岁,硕士研究生不超过30周岁，年龄计算日期截止至2020年7月31日（如30周岁以下为1990年7月31日以后出生）；</p><p style="text-indent: 2em;">（六）非北京生源需符合进京条件：硕士研究生及以上学历；学习成绩全部及格，无补考记录，能按时取得相应学历、学位；在校学习期间为全脱产，且未缴纳职工社会保险；其他非京生源进京条件；</p><p style="text-indent: 2em;">北京生源具有北京市常住户口，需学习成绩全部及格，并能按时取得相应学历；</p><p style="text-indent: 2em;">（七）符合招聘岗位所要求的其他条件及相关回避政策。</p><p style="text-indent: 2em;">二、报名程序</p><p style="text-indent: 2em;">采取网上报名、网上资格初审与网上资格复审的方式。</p><p style="text-indent: 2em;">（一）网上报名及资格初审：应聘人员于2020年8月18日9:00至8月21日16:00，登录北京卫生人才网（http://www.bjwsrc.cn/hhrnew/index.php)进行网上报名，每人限报一个岗位。应聘人员需详细填写个人资料，并上传近期2寸彩色免冠照片。在提交报名信息后，请注意随时登录报名系统，关注自己的资格初审结果。有关资格初审的问题，可拨打报考单位的初审咨询电话联系沟通。报名后请务必关注网上资格初审结果，审核通过后才算报名成功。8月21日16:00后报名系统关闭, 应聘人员不能再报名或更改其他个人信息；报名系统关闭后，网上报名审核不通过者，不能再修改个人信息或改报其他岗位，且不能进入网上资格复审环节，请应聘人员把握好报名时间。</p><p style="text-indent: 2em;">应聘人员除填报个人信息外，还需提交以下材料原件的pdf文件：</p><p style="text-indent: 2em;">1.本人签字的《应聘资料真实性和完整性承诺书》 (详见附件2)；</p><p style="text-indent: 2em;">2.本人身份证正反面（须在有效期内）；</p><p style="text-indent: 2em;">3.毕业院校就业主管部门盖章的高校毕业生就业推荐表，就业推荐表上须明确标注毕业生的培养方式（统招统分、非定向等）、生源地、学历、学制和毕业时间；</p><p style="text-indent: 2em;">4.毕业院校教务主管部门盖章的已修全部课程的成绩单；</p><p style="text-indent: 2em;">5.符合招聘岗位所要求的医师资格证书、执业资格证书，以及住院医师规范化培训合格证书；</p><p style="text-indent: 2em;">6.北京生源须上传本人户口本户主页及本人页；</p><p style="text-indent: 2em;">7.上传本人的学历、学位证书；如暂未取得，可不上传；</p><p style="text-indent: 2em;">8.招聘岗位条件所需的其他证明材料。</p><p style="text-indent: 2em;">注：报名与参加考试时使用的身份证必须一致。</p><p style="text-indent: 2em;">（二）资格复审：资格初审结束5个工作日后，应聘人员可登录报名系统查看资格复审结果。资格复审不通过者，不能进入下一个环节。</p><p style="text-indent: 2em;">三、考试考核安排</p><p style="text-indent: 2em;">（一）考试形式：采取笔试、面试相结合方式，具体时间及方式另行通知。</p><p style="text-indent: 2em;">（二）笔试内容：专业知识。笔试无指定参考用书。</p><p style="text-indent: 2em;">（三）成绩公布：笔试成绩于考试后10个工作日内统一在丰台区政府网站公开招聘栏(http://www.bjft.gov.cn/ftq/gkzp/list.shtml)公布。笔试成绩实行百分制，划定合格分数线为60分，笔试成绩未过合格分数线的应聘人员不能进入后面环节。</p><p style="text-indent: 2em;">（四）面试内容：每个招聘岗位按照拟招聘人数与参加面试人数1：3的比例，在笔试成绩合格人员中，从高分到低分依次确定拟面试人选；未达到1：3的岗位，按成绩合格的实际人数面试。请应聘人员随时关注报考网站，使用本人用户名和密码登录报考系统后，按照网页提示打印面试准考证（只有具备面试资格的应聘人员才可成功打印准考证），面试详情以准考证为准。面试合格成绩为60分,未过合格分数线的应聘人员不能进入后面环节。</p><p style="text-indent: 2em;">（五）面试及综合成绩公布：综合成绩按笔试、面试各占50%的比例相加计算得出，并按照1:1的比例确定体检和考察人选。如综合成绩相同则看笔试成绩高低，笔试成绩高者进入后面环节。面试及综合成绩将于面试结束后5个工作日内统一在丰台区政府网站公开招聘栏(http://www.bjft.gov.cn/ftq/gkzp/list.shtml)公布。</p><p style="text-indent: 2em;">（六）体检和考察：体检和考察均合格人员确定为拟聘用人选。按照相关文件规定，体检考察参照公务员录用的有关标准执行，体检费用自理。体检前有应聘人员主动放弃的，按综合成绩由高到低的顺序进行递补。</p><p style="text-indent: 2em;">四、拟聘用人员公示</p><p style="text-indent: 2em;">拟聘用人员名单统一在北京市丰台区政府网站公示，公示时间为7个工作日。</p><p style="text-indent: 2em;">五、注意事项</p><p style="text-indent: 2em;">（一）应聘人员应及时按照公告告知的方式查询成绩，打印准考证等。因应聘人员自身原因未能参加招聘下一步程序的由应聘人员本人负责。</p><p style="text-indent: 2em;">（二）应聘人员提供的联系方式应保持畅通，因联系不畅导致的后果，责任自负。</p><p style="text-indent: 2em;">（三）资格审核工作贯穿招聘全过程，应聘人员应确保填写、提交的个人报名信息真实准确，确保个人符合所报岗位条件，如应聘人员提供虚假信息或不符合岗位报考条件的，取消本次报考或聘用资格。</p><p style="text-indent: 2em;">出现下列情况之一的，直接取消聘用资格：</p><p style="text-indent: 2em;">（1）拟聘用人选公示结果影响聘用的；</p><p style="text-indent: 2em;">（2）拟聘用人选放弃聘用的；</p><p style="text-indent: 2em;">（3）未在拟聘用人选名单公示期满后30日内报到的；</p><p style="text-indent: 2em;">（4）2020年度应届毕业生不能按时毕业的；</p><p style="text-indent: 2em;">（5）非京生源进京审批手续不合格的；</p><p style="text-indent: 2em;">（6）政策文件规定的需取消聘用资格的其他情形。</p><p style="text-indent: 2em;">（四）非京生源应聘人员仅能报考《岗位情况表》中，生源条件为“不限”的岗位。</p><p style="text-indent: 2em;">卫健委咨询电话：83949083</p><p style="text-indent: 2em;">各招聘单位咨询电话：详见附件1</p><p style="text-indent: 2em;">附件：</p><p style="text-indent: 2em;">1.2020年丰台区卫健委所属事业单位面向应届毕业生公开招聘工作人员岗位情况表</p><p style="text-indent: 2em;">2. 应聘资料真实性和完整性承诺书</p><p style="text-indent: 2em;"><br/></p><p style="text-align: right; text-indent: 2em;">丰台区卫生健康委</p><p style="text-align: right; text-indent: 2em;">2020年8月13日&nbsp;</p></div>','根据丰台区卫生健康委员会所属事业单位实际工作需要，按照《北京市事业单位公开招聘工作人员实施办法》（京人社专技发〔2010〕102号）和 《关于进一步规范事业单位公开招聘工作有关问题的通知》（京人社专技发〔2012〕247号）等文件规定，现面向2020年医疗卫生专业应届毕业生公开招聘190名事业单位工作人员，相关事项公告如下：一、招聘条件（一）遵守宪法和法律，具有良好的品行；（二）适应岗位要求的身体条件，身心健康；（三）岗位条件要求的学历、专业、专业技术（职务任职）资格、执（职、从）业资格或专业技能等级等；（四）招聘对象为列入国家统一招生计划，能够正常参加2020年就业派遣的普通高等院校应届毕业生（不含定向、委培）；（五）年龄要求为博士研究生不超过35周岁,硕士研究生不超过30周岁，年龄计算日期截止至2020年7月31日（如30周岁以下为1990年7月31日以后出生）；（六）非北京生源需符合进京条件：硕士研究生及以上学历；学习成绩全部及格，无补考记录，能按时取得相应学历、学位；在校学习期间为全脱产，且未缴纳职工社会保险；其他非京生源进京条件；北京生源具有北京市常住户口，需学习成绩全部及格，并能按时取得相应学历；（七）符合招聘岗位所要求的其他条件及相关回避政策。二、报名程序采取网上报名、网上资格初审与网上资格复审的方式。（一）网上报名及资格初审：应聘人员于2020年8月18日9:00至8月21日16:00，登录北京卫生人才网（http://www.bjwsrc.cn/hhrnew/index.php)进行网上报名，每人限报一个岗位。应聘人员需详细填写个人资料，并上传近期2寸彩色免冠照片。在提交报名信息后，请注意随时登录报名系统，关注自己的资格初审结果。有关资格初审的问题，可拨打报考单位的初审咨询电话联系沟通。报名后请务必关注网上资格初审结果，审核通过后才算报名成功。8月21日16:00后报名系统关闭, 应聘人员不能再报名或更改其他个人信息；报名系统关闭后，网上报名审核不通过者，不能再修改个人信息或改报其他岗位，且不能进入网上资格复审环节，请应聘人员把握好报名时间。应聘人员除填报个人信息外，还需提交以下材料原件的pdf文件：1.本人签字的《应聘资料真实性和完整性承诺书》 (详见附件2)；2.本人身份证正反面（须在有效期内）；3.毕业院校就业主管部门盖章的高校毕业生就业推荐表，就业推荐表上须明确标注毕业生的培养方式（统招统分、非定向等）、生源地、学历、学制和毕业时间；4.毕业院校教务主管部门盖章的已修全部课程的成绩单；5.符合招聘岗位所要求的医师资格证书、执业资格证书，以及住院医师规范化培训合格证书；6.北京生源须上传本人户口本户主页及本人页；7.上传本人的学历、学位证书；如暂未取得，可不上传；8.招聘岗位条件所需的其他证明材料。注：报名与参加考试时使用的身份证必须一致。（二）资格复审：资格初审结束5个工作日后，应聘人员可登录报名系统查看资格复审结果。资格复审不通过者，不能进入下一个环节。三、考试考核安排（一）考试形式：采取笔试、面试相结合方式，具体时间及方式另行通知。（二）笔试内容：专业知识。笔试无指定参考用书。（三）成绩公布：笔试成绩于考试后10个工作日内统一在丰台区政府网站公开招聘栏(http://www.bjft.gov.cn/ftq/gkzp/list.shtml)公布。笔试成绩实行百分制，划定合格分数线为60分，笔试成绩未过合格分数线的应聘人员不能进入后面环节。（四）面试内容：每个招聘岗位按照拟招聘人数与参加面试人数1：3的比例，在笔试成绩合格人员中，从高分到低分依次确定拟面试人选；未达到1：3的岗位，按成绩合格的实际人数面试。请应聘人员随时关注报考网站，使用本人用户名和密码登录报考系统后，按照网页提示打印面试准考证（只有具备面试资格的应聘人员才可成功打印准考证），面试详情以准考证为准。面试合格成绩为60分,未过合格分数线的应聘人员不能进入后面环节。（五）面试及综合成绩公布：综合成绩按笔试、面试各占50%的比例相加计算得出，并按照1:1的比例确定体检和考察人选。如综合成绩相同则看笔试成绩高低，笔试成绩高者进入后面环节。面试及综合成绩将于面试结束后5个工作日内统一在丰台区政府网站公开招聘栏(http://www.bjft.gov.cn/ftq/gkzp/list.shtml)公布。（六）体检和考察：体检和考察均合格人员确定为拟聘用人选。按照相关文件规定，体检考察参照公务员录用的有关标准执行，体检费用自理。体检前有应聘人员主动放弃的，按综合成绩由高到低的顺序进行递补。四、拟聘用人员公示拟聘用人员名单统一在北京市丰台区政府网站公示，公示时间为7个工作日。五、注意事项（一）应聘人员应及时按照公告告知的方式查询成绩，打印准考证等。因应聘人员自身原因未能参加招聘下一步程序的由应聘人员本人负责。（二）应聘人员提供的联系方式应保持畅通，因联系不畅导致的后果，责任自负。（三）资格审核工作贯穿招聘全过程，应聘人员应确保填写、提交的个人报名信息真实准确，确保个人符合所报岗位条件，如应聘人员提供虚假信息或不符合岗位报考条件的，取消本次报考或聘用资格。出现下列情况之一的，直接取消聘用资格：（1）拟聘用人选公示结果影响聘用的；（2）拟聘用人选放弃聘用的；（3）未在拟聘用人选名单公示期满后30日内报到的；（4）2020年度应届毕业生不能按时毕业的；（5）非京生源进京审批手续不合格的；（6）政策文件规定的需取消聘用资格的其他情形。（四）非京生源应聘人员仅能报考《岗位情况表》中，生源条件为“不限”的岗位。卫健委咨询电话：83949083各招聘单位咨询电话：详见附件1附件：1.2020年丰台区卫健委所属事业单位面向应届毕业生公开招聘工作人员岗位情况表2. 应聘资料真实性和完整性承诺书丰台区卫生健康委2020年8月13日',NULL,'事业单位;公开招聘',NULL,'丰台区卫生健康委',NULL,'2020-08-13 13:11:00',NULL,'2023-08-28 00:52:32',6,'北京市人力资源和社会保障局',39157,'http://rsj.beijing.gov.cn/xxgk/gkzp/202008/t20200813_1982021.html',10),	 (880196,'案例九 女职工产检、产假期间的工资应照发','案例九 女职工产检、产假期间的工资应照发','<div class="view TRS_UEDITOR trs_paper_default trs_external"><div class="TRS_Editor"><div class="Custom_UnionStyle"><p style="text-align:justify;"><span style="font-size: 10.5pt">　　付女士于2011年6月入职某航空公司，担任出纳一职，双方签订三年期固定期限劳动合同，合同中约定付女士的月基本工资为1800元，加上岗位工资每月共计6000元，付女士在职期间航空公司未为其缴纳生育保险。2012年9月付女士怀孕，之后一直坚持工作，只是有时按照医院的要求进行产前检查，但每次产检航空公司都将此算作事假，并扣发付女士相应的事假工资。2013年6月5日付女士剖宫产生育一女，产假期间航空公司一直按照付女士基本工资1800元的标准每月向其支付工资。付女士于2014年6月3日提起仲裁，请求航空公司支付产检和产假期间工资差额。</span></p><p style="text-align:justify;"><span style="font-size: 10.5pt">　　仲裁委审理后认为，依据《女职工劳动保护特别规定》第六条的规定，女职工依法享有产前检查的权利，怀孕女职工如在劳动时间内进行产前检查，所需时间应计入劳动时间，且用人单位应为怀孕女职工适时的提供方便，女职工在劳动时间进行产前检查的，按出勤对待，不能按病假、事假、旷工处理，故航空公司应支付付女士产检期间克扣的工资。由于航空公司没有为付女士缴纳生育保险，因此付女士产假期间工资应由航空公司承担，工资标准参照她正常出勤的月工资水平。本案中，航空公司在付女士产假期间以每月基本工资1800元的工资标准向她支付产假工资，不符合相关法律规定，所以航空公司应补足付女士产假期间的工资差额。</span></p><p style="text-align:justify;"><span style="font-size: 10.5pt">　　我国法律对于女职工特别是处在孕期、产期和哺乳期(以下简称三期)内的女职工有一系列的特别保护措施。除了上述《女职工劳动保护特别规定》外，《劳动合同法》也规定，处在三期内的女职工，用人单位不得依据本法第四十条和第四十一条解除劳动合同。劳动合同期限届满而女职工尚处在三期内的，劳动合同应顺延至三期期满。但是法律对于女职工的特别保护也并非是无限的，如果女职工严重违反用人单位的规章制度，或者营私舞弊给用人单位造成重大损害的，用人单位有权依法解除劳动合同。另外，如果女职工与用人单位协商一致也可以解除劳动合同。</span></p></div></div></div>','　　付女士于2011年6月入职某航空公司，担任出纳一职，双方签订三年期固定期限劳动合同，合同中约定付女士的月基本工资为1800元，加上岗位工资每月共计6000元，付女士在职期间航空公司未为其缴纳生育保险。2012年9月付女士怀孕，之后一直坚持工作，只是有时按照医院的要求进行产前检查，但每次产检航空公司都将此算作事假，并扣发付女士相应的事假工资。2013年6月5日付女士剖宫产生育一女，产假期间航空公司一直按照付女士基本工资1800元的标准每月向其支付工资。付女士于2014年6月3日提起仲裁，请求航空公司支付产检和产假期间工资差额。　　仲裁委审理后认为，依据《女职工劳动保护特别规定》第六条的规定，女职工依法享有产前检查的权利，怀孕女职工如在劳动时间内进行产前检查，所需时间应计入劳动时间，且用人单位应为怀孕女职工适时的提供方便，女职工在劳动时间进行产前检查的，按出勤对待，不能按病假、事假、旷工处理，故航空公司应支付付女士产检期间克扣的工资。由于航空公司没有为付女士缴纳生育保险，因此付女士产假期间工资应由航空公司承担，工资标准参照她正常出勤的月工资水平。本案中，航空公司在付女士产假期间以每月基本工资1800元的工资标准向她支付产假工资，不符合相关法律规定，所以航空公司应补足付女士产假期间的工资差额。　　我国法律对于女职工特别是处在孕期、产期和哺乳期(以下简称三期)内的女职工有一系列的特别保护措施。除了上述《女职工劳动保护特别规定》外，《劳动合同法》也规定，处在三期内的女职工，用人单位不得依据本法第四十条和第四十一条解除劳动合同。劳动合同期限届满而女职工尚处在三期内的，劳动合同应顺延至三期期满。但是法律对于女职工的特别保护也并非是无限的，如果女职工严重违反用人单位的规章制度，或者营私舞弊给用人单位造成重大损害的，用人单位有权依法解除劳动合同。另外，如果女职工与用人单位协商一致也可以解除劳动合同。',NULL,'女职工产检、产假期间的工资应照发','付女士于2011年6月入职某航空公司，担任出纳一职，双方签订三年期固定期限劳动合同，合同中约定付女士的月基本工资为1800元，加上岗位工资每月共计6000元，付女士在职期间航空公司未为其缴纳生育保险。由于航空公司没有为付女士缴纳生育保险，因此付女士产假期间工资应由航空公司承担，工资标准参照她正常出勤的月工资水平。本案中，航空公司在付女士产假期间以每月基本工资1800元的工资标准向她支付产假工资，不符合相关法律规定，所以航空公司应补足付女士产假期间的工资差额。另外，如果女职工与用人单位协商一致也可以解除劳动合同。','自发','北京市人力资源和社会保障局','2015-07-10 11:24:00',NULL,'2023-08-28 07:47:32',6,'北京市人力资源和社会保障局',18487,'http://rsj.beijing.gov.cn/bm/ztzl/dxal/201912/t20191206_880196.html',10),	 (1524621,'职业鉴定全市统考',NULL,NULL,NULL,NULL,NULL,'http://bjt.beijing.gov.cn/renzheng/open/login/goUserLogin?client_id=2117&redirect_uri=http://fuwu.rsj.beijing.gov.cn/bjtsso/third/redirect&response_type=code&scope=user_info&state=http://fuwu.rsj.beijing.gov.cn/zhiye/main',NULL,NULL,'2019-12-27 19:59:00',NULL,'2024-09-05 19:36:45',6,'北京市人力资源和社会保障局',29662,'https://rsj.beijing.gov.cn/fuwu/zxbs/grbs/201912/t20191227_1524621.html',10);

